const e="sensor",a="2.0.0",l="フルサイズ積層型CMOSイメージセンサー＆5軸IBIS（90パーツ）",s="Full-Frame Stacked CMOS Image Sensor & 5-Axis IBIS",t=90,o=JSON.parse('[{"id":"aperture-mask","order":1,"swatchColor":"#252932","groupKey":"S01_光学開口・迷光制御","assembledPos":[0,0,7.8],"explodeOffset":[0,0,82],"integratedExplodeOffset":[0,0,12.2],"edgeOpacity":0.22,"title":"センサー遮光マスク ＆ 防塵ガスケット枠","subtitle":"Optical Aperture Baffle & EPDM Dust-Seal Bezel","category":"S01 / 光学開口・迷光制御","plainAnalogy":"映画館のスクリーンの周りにある「真っ黒な縁取り」と、すきま風を防ぐ「ドアのゴムパッキン」を合体させた最前面の額縁です。写真に不要な横からの迷い光を黒い枠で吸い取ってコントラストを守りつつ、センサーの命である撮像面にホコリや湿気が入り込むのをぴっちりガードします。","summary":"フルサイズ有効撮像面（36.0 × 24.0 mm）の直前に配置され、レンズ通過後の不要な周辺光束と内面多重反射（迷光）を物理的に遮断するとともに、光学フィルター群の周囲を気密防塵シールする最前面フレーム。","opticsAndPhysics":["内縁に精密な段付きナイフエッジ・バッフル形状と低反射マットブラックアルマイト処理（可視光反射率 < 1.5%）を施し、大口径レンズ（F1.2〜F1.4）の斜め入射光がセンサー枠で反射して生じるフレア・ゴーストを抑制。","背面に圧縮率制御された低アウトガスEPDM発泡ガスケットを配置し、シャッター機構やミラーレスマウント側からの微細塵埃・湿気がフィルター間に侵入するのを遮断。","四隅の精密ねじと位置決め基準ピンにより、センサー像面中心に対する開口アライメントを数十ミクロン精度で固定。"],"formula":{"expression":"R(θ) = [(n₁cosθᵢ − n₂cosθₜ) / (n₁cosθᵢ + n₂cosθₜ)]²  →  < 0.015","description":"微細粗面黒色アルマイトとナイフエッジ勾配により斜め入射の鏡面反射成分を多重散乱吸収。"},"nextGenInnovation":"最新のショートフランジバック大口径マウントでは像面周辺への最大入射角が30°を超えるため、開口エッジの段差勾配を光線追跡シミュレーションで最適化し、センサーエッジ反射由来のゴーストを劇的に低減している。","specs":[{"label":"光学開口寸法","value":"36.6 × 24.6 mm（有効 36×24 mm）"},{"label":"基材・表面処理","value":"A6061 艶消し黒アルマイト"},{"label":"可視光反射率","value":"< 1.5%（400–700 nm）"},{"label":"防塵シール材","value":"低アウトガス EPDM ガスケット"}],"diagramType":"baffle"},{"id":"sswf-piezo","order":2,"swatchColor":"#95c8e8","groupKey":"S02_超音波防塵・表面物理","assembledPos":[0,0,6.2],"explodeOffset":[0,0,72],"integratedExplodeOffset":[0,0,7.6],"edgeOpacity":0.22,"title":"超音波ダストリダクション振動ガラス板（SSWF）","subtitle":"Supersonic Wave Filter (SSWF) Anti-Static Fluorine Glass Plate","category":"S02 / 超音波防塵・表面物理","plainAnalogy":"センサーの一番前に張られた「自動でホコリを弾き飛ばす超ツルツルな防塵ガラス」です。静電気を逃がす透明コートとフッ素の撥水コートでゴミをつきにくくし、さらに電源ON/OFF時に下の圧電バーから毎秒3万〜7万回の超音波振動を受けて、ミクロのホコリをトランポリンのように弾き飛ばします。","summary":"センサーユニット最前面に浮遊支持された厚さ約0.5 mmの超薄型光学ガラス振動板。透明導電帯電防止膜（ITO）とフッ素撥水ARコートを備え、下端の圧電セラミックバー（S03）から励起される超音波定在波で付着塵埃を払い落とす。","opticsAndPhysics":["屈曲定在波モード：四隅のシリコーン弾性ダンパーで振動の「節（ノード）」を優しく支えることで、ガラス板全体のエネルギー損失を抑えつつ、画面全域にわたって均一な超音波屈曲定在波（30–70 kHz）を形成する。","微粒子の付着力は静電力・ファンデルワールス力・液架橋力が支配的であり、重力の数万倍の加速度が必要。加速度は振動数の2乗に比例するため、数μmの微小振幅でも数万Gの剥離加速度を発生できる。","表面の極薄ITO帯電防止膜で静電吸着を抑え、フッ素系低表面エネルギー多層ARコートで花粉や油分を含んだ微細塵の固着を防ぐ。"],"formula":{"expression":"a_max = A · (2π f)²   (f = 35–70 kHz → a ≈ 10⁴–10⁵ G)","description":"振動加速度は周波数 f の2乗で増大し、数μmの塵のファンデルワールス付着力を上回る慣性力を生成。"},"nextGenInnovation":"2024–2026年のプロ機では、単一周波数振動から複数共振モードのスイープ駆動＋帯電防止フッ素コート＋電源OFF時の保護シャッター連動を組み合わせ、レンズ交換時のダスト付着を極めて高確率で除去する。","specs":[{"label":"励起共振周波数","value":"30,000 – 70,000 Hz（超音波帯）"},{"label":"光学ガラス厚","value":"約 0.50 – 0.55 mm（超薄型）"},{"label":"表面コーティング","value":"フッ素撥水 + ITO帯電防止 + AR膜"},{"label":"四隅支持構造","value":"振動節（ノード）シリコーンダンパー × 4"}],"diagramType":"sswf"},{"id":"sensor-sswf-holder","order":3,"swatchColor":"#f472b6","groupKey":"S03_超音波共振絶縁・ダスト除去効率化","assembledPos":[0,0,5.75],"explodeOffset":[0,0,62],"integratedExplodeOffset":[0,0,4.2],"edgeOpacity":0.22,"title":"SSWF 超音波防振サスペンションホルダー ＆ ノード点シリコーン支持枠","subtitle":"SSWF Ultrasonic Nodal Suspension Frame & CuBe2 Hold-Down Spring Clips","category":"S03 / 超音波共振絶縁・ダスト除去効率化","plainAnalogy":"毎秒4万回もブルブル震えるゴミ落としガラス（S02）を、「揺れが一番少ない4つのツボ（節）」だけでフワッと支える専用フレーム。振動がカメラ本体へ逃げないため、ホコリを弾き飛ばすパワーが最大になります。","summary":"超音波ダストリダクションガラス（SSWF）を固定しつつ、35〜40kHzの定在波たわみ振動がIBISステージ側へ減衰流出するのを防ぐ精密防振ホルダー。振動振幅がゼロとなるノード（節）位置へ低硬度シリコーンパッドを配置し、ベリリウム銅の微圧クリップで共振Q値を極大化します。","opticsAndPhysics":["定在波ノード（節）支持の音響力学：PZT圧電素子が励起する高次たわみモードには、変位が極大となる「腹」と常に静止している「節（ノード）」が存在します。節点のみを弾性支持することで振動エネルギー損失（機械ダンピング）を最小化し、10,000 G超の加速度で付着ダストを吹き飛ばします。","防塵密閉シールと防振の両立：SSWFガラスとOLPFの間へ外部からホコリが回り込むのを防ぐ超低剛性発泡シリコーンガスケットを全周に備え、センサー光学スタック内部をクラス100相当のクリーン環境に隔離します。","熱膨張差の吸収：ベリリウム銅の薄板クリップによる一定予圧支持のため、−20℃〜+60℃の環境変化でもガラスへ局所応力（光学複屈折）を与えません。"],"formula":{"expression":"a_dust = (2π f_res)² · A_amp · Q_mech > 10,000 G   (ノード点支持で機械Q値を極大化)","description":"ノード点シリコーン絶縁支持によって振動の逃げを抑え、小さな圧電駆動電力で極めて高いダスト剥離加速度を実現。"},"nextGenInnovation":"最新世代では、SSWFホルダーの下辺に微粘着ダストキャッチ溝を一体化し、超音波で弾き落としたホコリが重力で落下した瞬間に永久捕捉する構造へ進化しています。","specs":[{"label":"支持方式","value":"定在波ノード点4点 低硬度シリコーン防振支持"},{"label":"押さえバネ","value":"ベリリウム銅 (CuBe2) 微圧板バネクリップ"},{"label":"共振周波数帯","value":"35 〜 42 kHz 高次たわみ定在波モード"},{"label":"光学影響","value":"ガラス応力複屈折ゼロ・気密ダストバリア内蔵"}],"diagramType":"sensor_sswf_holder"},{"id":"sensor-pzt-bar","order":4,"swatchColor":"#eab308","groupKey":"S04_逆圧電効果・超音波励振","assembledPos":[0,-14.1,6.88],"explodeOffset":[0,-24,72],"integratedExplodeOffset":[0,-36,6.2],"edgeOpacity":0.22,"title":"積層圧電セラミック超音波アクチュエータ（PZTバー）","subtitle":"Multi-Layer PZT Piezoelectric Ultrasonic Actuator & Silver Electrodes","category":"S04 / 逆圧電効果・超音波励振","plainAnalogy":"電気をかけると目に見えない超高速で伸び縮みする「魔法のセラミック棒」です。ガスコンロの点火装置や超音波メガネ洗浄機と同じ「圧電効果」を逆に使い、わずか数ミリの棒が毎秒何万回も振動して、上の防塵ガラス板にゴミを吹き飛ばす強力な揺れを送り込みます。","summary":"SSWFガラス板の下縁に精密接着された積層チタン酸ジルコン酸鉛（PZT）圧電アクチュエータ。左右対称の銀電極と専用フレキ配線を通じて高周波交流電圧を印加し、逆圧電効果で強力な超音波屈曲振動を生み出す。","opticsAndPhysics":["逆圧電効果（Converse Piezoelectric Effect）：強誘電体結晶であるPZT（Pb(Zr,Ti)O₃）の分極軸方向へ電界 E を加えると、結晶格子内のイオンが変位して機械的ひずみ S = d₃₁·E が生じる。","対称2分割電極による屈曲モード制御：左右2枚の銀電極へ同相・逆相の高周波交流パルスを印加することで、ガラス板の1次・2次・高次屈曲共振モードを自在に励起し、定在波の「節（揺れない線）」にホコリが居残るのを防ぐ。","専用の高耐圧ポリイミド駆動リード線により、周囲の超微小なアナログ画素信号線へ高周波ノイズが飛び込むのを遮断。"],"formula":{"expression":"S = d₃₁ · E = d₃₁ · (V_drive / t_pzt),   f_res = (1 / 2π) · √(k_eff / m_eff)","description":"積層構造で1層厚 t_pzt を薄くすることで、カメラの低電圧バッテリー電源からでも大きな電界と振動振幅を獲得。"},"nextGenInnovation":"最新世代のSSWF駆動回路は、駆動中の圧電素子のインピーダンス位相をリアルタイム監視し、温度変化でわずかにズレるガラス板の共振周波数を自動追尾（フェーズロック）して常に最大の塵剥離加速度を維持する。","specs":[{"label":"圧電セラミック材","value":"高変位 積層 PZT (Pb(Zr,Ti)O₃)"},{"label":"電極構成","value":"左右対称2分割 焼成銀（Ag）電極"},{"label":"駆動モード","value":"複数共振周波数スイープ＋位相追尾"},{"label":"剥離加速度","value":"最大 約 30,000 – 50,000 G"}],"diagramType":"sensor_pzt_bar"},{"id":"olpf-16pt","order":5,"swatchColor":"#79b7cf","groupKey":"S05_波動光学・空間周波数制御","assembledPos":[0,0,4.95],"explodeOffset":[0,0,52],"integratedExplodeOffset":[0,0,0.55],"edgeOpacity":0.22,"title":"前面・人工水晶複屈折光学ローパスフィルター（水平/斜め分離層）","subtitle":"Front Birefringent Synthetic Quartz OLPF (H-Split & ±45° Separation)","category":"S05 / 波動光学・空間周波数制御","plainAnalogy":"細かいチェック柄のシャツを撮ったときに出る「変な虹色のモヤモヤ（偽色・モアレ）」を防ぐための、特殊な人工水晶のガラス板です。1本の光の粒を水晶の不思議な性質（複屈折）でミクロの距離だけ2本にそっと分けることで、デジタル特有のギザギザや偽色を自然に消してくれます。","summary":"人工水晶単結晶（α-SiO₂）の複屈折現象を利用し、入射光束をまず水平および±45°方向へサブ画素ピッチ分だけ精密分離する前面光学ローパスフィルター層。次層の1/4波長板＋垂直水晶板（S05）と組んで16点ガウス分離を完成させる。","opticsAndPhysics":["結晶光学・複屈折：単軸異方性結晶である人工水晶は偏光方向によって屈折率が異なる（常光線 n_o = 1.544、異常光線 n_e = 1.553）。光軸に対して約45°傾けて切り出した水晶板に光を通すと、直交する2偏光が微小距離 d だけ分離する。","ナイキストサンプリング定理：画素ピッチ p のベイヤーセンサーでは、ナイキスト空間周波数 f_N = 1/(2p) を超える高周波パターン（繊維や建築格子など）が折り返し雑音（エイリアシング・カラーモアレ）として現れる。","水平・±45°方向の分離幅を画素ピッチに最適化することで、解像感（MTF）を保ったまま偽色の原因となる高周波成分のみを急峻に減衰させる。"],"formula":{"expression":"d = t · (n_e² − n_o²) · tanθ / (n_e² + n_o² tan²θ),   MTF(f) = |cos(π d · f)|","description":"水晶厚 t と光軸角 θ で分離幅 d を0.1 μm精度で制御し、偽色が発生する空間周波数帯にMTFの零点を配置。"},"nextGenInnovation":"Canon EOS R1等の最新プロ機で採用された16点ガウス分布型OLPFは、従来の4点分離比で斜め方向の偽色・モアレを約1/4まで低減しつつ、ナイキスト周波数以下のシャープな解像感を維持する革新的光学設計である。","specs":[{"label":"結晶材料","value":"高純度人工水晶単結晶 (α-SiO₂)"},{"label":"屈折率 (589 nm)","value":"n_o = 1.544 / n_e = 1.553"},{"label":"分離方向","value":"水平 (0°) + 斜め (±45°) 複屈折積層"},{"label":"結晶軸基準","value":"右上オリエンテーションノッチ管理"}],"diagramType":"olpf16"},{"id":"sensor-qwp-plate","order":6,"swatchColor":"#a855f7","groupKey":"S06_偏光光学・16点ガウス分離完成層","assembledPos":[0,0,4.3],"explodeOffset":[0,0,42],"integratedExplodeOffset":[0,0,-4.8],"edgeOpacity":0.22,"title":"1/4波長位相差板（円偏光解消）＆ 後面・垂直分離水晶板","subtitle":"Zero-Order λ/4 Quarter-Wave Plate & Rear Vertical Quartz OLPF","category":"S06 / 偏光光学・16点ガウス分離完成層","plainAnalogy":"偏光サングラスをかけたままカメラで空や水面を撮っても変に暗くなったり縞が出たりしないよう、光の「振動の向き（偏光）」をクルクル回る円偏光に整え直す透明シートと、タテ方向にも光を優しく分離する2枚目の水晶板です。S04とタッグを組んで完璧なモアレ防止フィルターを完成させます。","summary":"前面水晶板（S04）を通過した直線偏光を円偏光へ変換して偏光依存性をリセットする「ゼロ次1/4波長位相差板（λ/4 Plate）」と、垂直方向の複屈折分離を担う後面水晶板の複合光学ユニット。","opticsAndPhysics":["1/4波長位相差（λ/4 Retardation）：常光線と異常光線の間にちょうど波長の1/4（位相差 π/2 = 90°）の光路差 Δn·t = λ/4 を与えることで、前段の水晶板で分離した直交直線偏光をそれぞれ右回り・左回りの円偏光へ変換する。","もしλ/4板がなければ、風景撮影でCPL（円偏光）フィルターを装着した際や水面反射光を撮る際に、特定の偏光成分が後段の水晶板で再分離されずローパス効果が片方向だけ消失してしまう。λ/4板が偏光状態を均等化することで、後段の垂直水晶板が常に50:50の強度比で光を2分割できる。","前面（S04）と後面（S05）の畳み込みにより、最終的に1点の入射光をガウス分布に近い16点の点拡がり関数（PSF）へ仕上げる。"],"formula":{"expression":"Γ = (2π / λ) · (n_e − n_o) · t = π / 2   ⇒   Linear Pol. → Circular Pol.","description":"中心波長 λ ≈ 550 nm で正確に位相差 π/2 を与えることで、あらゆる偏光入力でも均等な縦横モアレ抑制を保証。"},"nextGenInnovation":"広帯域ゼロ次位相差板（2枚の異方性フィルムまたは水晶の光学軸を直交微差配置）を用いることで、青（450 nm）から赤（650 nm）までの可視光全域で位相差ズレを最小化し、色ごとのモアレ抑制ムラの発生を防いでいる。","specs":[{"label":"位相差仕様","value":"ゼロ次 λ/4 位相差板（λ₀ ≈ 550 nm）"},{"label":"後段分離層","value":"垂直方向（90°）人工水晶複屈折板"},{"label":"光学機能","value":"直線偏光 → 円偏光変換（CPL対応）"},{"label":"最終PSF分布","value":"S04＋S05 統合 16点ガウス近似分離"}],"diagramType":"sensor_qwp_plate"},{"id":"ir-cut-filter","order":7,"swatchColor":"#38b2da","groupKey":"S07_分光光学・薄膜干渉","assembledPos":[0,0,3.25],"explodeOffset":[0,0,32],"integratedExplodeOffset":[0,0,-9.75],"edgeOpacity":0.22,"title":"ハイブリッド赤外線吸収ガラス ＆ 誘電体多層膜IR/UVカット","subtitle":"Cu²⁺ Phosphate IR-Absorption + Dichroic Multilayer Filter","category":"S07 / 分光光学・薄膜干渉","plainAnalogy":"人間の目には見えないけれどセンサーには強く写ってしまう「赤外線」と「紫外線」だけをカットする、鮮やかな青緑色の特製サングラスです。これがないと黒い服が赤紫に写ったりピントがズレたりするため、カメラの色を人間の目と同じ自然な色に合わせる絶対不可欠なフィルターです。","summary":"シリコンが持つ近赤外線（700–1100 nm）への強い感度を精密にカットし、センサーの分光感度特性を人間の視覚（比視感度曲線）へ厳密に整合させるハイブリッド分光フィルター。","opticsAndPhysics":["シリコンのバンドギャップエネルギー E_g = 1.12 eV は波長 λ_c ≈ 1107 nm に相当するため、IRカットなしでは近赤外光が赤・緑・青すべてのカラーフィルターを透過し、深刻な色転び（マゼンタ被り）と軸上色収差ボケを引き起こす。","誘電体多層膜（TiO₂ / SiO₂等の40〜60層交互蒸着）はブラッグ光干渉により急峻なカットオフ特性を持つが、広角レンズ周辺で斜め入射角 θ が大きくなるとカットオフ波長が短波長側へシフトする（ブルーシフト現象）。","そこで、銅イオン（Cu²⁺）の電子遷移吸収を利用し入射角依存性がゼロの「リン酸塩系青色赤外吸収ガラス」と「誘電体多層干渉膜」を組み合わせることで、画面中央から最周辺まで均一かつ正確な色再現を実現する。"],"formula":{"expression":"λ(θ) = λ₀ · √[1 − (sinθ / n_eff)²]  （干渉膜の入射角シフト）","description":"吸収型ガラス（ランベルト・ベール則 I = I₀e⁻ᵅᵈ）とのハイブリッド化で広角周辺の色被りを解消。"},"nextGenInnovation":"ショートフランジバックのミラーレス光学系向けに、大入射角（30°超）でも色シフトが極めて小さい高屈折率多層膜＋超低反射広帯域ARコートと、薄型高濃度Cu²⁺吸収ガラスの複合設計が主流となっている。","specs":[{"label":"可視光透過帯域","value":"420 – 650 nm（平均透過率 > 96%）"},{"label":"半値カットオフ波長","value":"λ₅₀ ≈ 650 ± 5 nm / UV < 395 nm"},{"label":"近赤外遮断率","value":"OD > 4（720 – 1100 nm で < 0.01%）"},{"label":"ガラス基材","value":"Cu²⁺含有リン酸塩ガラス + 誘電体多層膜"}],"diagramType":"ircut"},{"id":"cover-glass","order":8,"swatchColor":"#8c99a8","groupKey":"S08_半導体実装・環境保護","assembledPos":[0,0,2.05],"explodeOffset":[0,0,22],"integratedExplodeOffset":[0,0,-14.55],"edgeOpacity":0.22,"title":"低α線光学カバーガラス ＆ コバール気密封止リング","subtitle":"Low-Alpha Borosilicate Cover Glass & Kovar Hermetic Seal","category":"S08 / 半導体実装・環境保護","plainAnalogy":"超繊細な半導体チップ（センサー）をホコリや結露から完全に守る「博物館の気密ショーケースのガラス蓋」です。しかも普通のガラスに微量含まれる自然放射線（α線）すら極限まで取り除いた超純粋ガラスを使い、星空の長時間露光でも謎の白い点ノイズが出ないようにしています。","summary":"セラミックパッケージ上面を気密封止し、シリコンダイ表面の繊細なマイクロレンズと金ワイヤーボンディングを湿気・塵・自然放射線から隔離保護する光学窓。","opticsAndPhysics":["低α線（Low-Alpha）ガラス：通常の光学ガラスに極微量含まれるウラン・トリウム系放射性同位体が崩壊する際に放出するα線（エネルギー数 MeV）は、直下のシリコン内に数十万個の電子-正孔対を突発生成し、長時間露光時の白点ノイズやソフトエラーの原因となる。超高純度精製によりα線放出率を極小化している。","両面に反射率 0.2% 以下の多層無反射（AR）コーティングを施し、シリコン表面とカバーガラス裏面間での往復反射（センサーゴースト）を抑制。","シールリングに熱膨張係数がアルミナセラミックおよびホウケイ酸ガラスと整合するコバール合金（Fe-29Ni-17Co）を採用し、内部キャビティに乾燥窒素（N₂）を封入して低温結露を防止。"],"formula":{"expression":"CTE: Si (2.6) ≈ Borosilicate (3.3) ≈ Kovar (5.1) ≈ Al₂O₃ (6.8) [ppm/K]","description":"異種材料間の熱膨張係数（CTE）整合により、−20℃〜+85℃の環境変化でも像面歪みとクラックを防止。"},"nextGenInnovation":"最新の大型フルサイズパッケージでは、カバーガラスの平坦度（ウェーブフロント誤差 λ/4 以下）と極めて薄い接着ボンドライン制御により、バックフォーカス長と像面湾曲誤差を数ミクロン以内に抑制している。","specs":[{"label":"ガラス材質","value":"低α線高純度ホウケイ酸光学ガラス"},{"label":"α線放出率","value":"< 0.002 counts / (cm²·h)"},{"label":"封止枠材質","value":"コバール合金（Fe-Ni-Co）+ Ni/Auめっき"},{"label":"可視光透過率","value":"> 99.2%（両面広帯域ARコート）"}],"diagramType":"coverglass"},{"id":"cmos-die","order":9,"swatchColor":"#1d6d7c","groupKey":"S09_光電変換・第1積層ウェハー","assembledPos":[0,0,0.97],"explodeOffset":[0,0,12],"integratedExplodeOffset":[0,0,-19.47],"edgeOpacity":0.22,"title":"第1ウェハー：フルサイズ・グローバルシャッター BSI画素ダイ","subtitle":"Wafer 1: Full-Frame Global Shutter + 2-Layer Transistor BSI Pixel Die","category":"S09 / 光電変換・第1積層ウェハー","plainAnalogy":"カメラの「網膜」にあたる一番主役の半導体チップです。36×24 mmの虹色に光る面に数千万個の「光の粒を電気に変えるバケツ（画素）」がぎっしり並び、しかも全バケツが一斉に「せーの！」で光を閉じ込めるグローバルシャッター方式なので、高速回転するプロペラやゴルフクラブも一切歪まずに写せます。","summary":"3ウェハー3D積層センサーの最上層（第1ウェハー）。36.0 × 24.0 mmの有効撮像面に数千万個の裏面照射（BSI）フォトダイオードと全画素同時露光メモリノードを高密度集積した光電変換の心臓部。","opticsAndPhysics":["内部光電効果：入射光子のエネルギー E = hν = hc/λ がシリコンのバンドギャップ E_g = 1.12 eV を超えると、価電子帯から伝導帯へ電子が励起され、入射光子数に厳密比例した電子-正孔対を生成する。","裏面照射（BSI）＋2層トランジスタ画素：シリコン基板を約3 μmまで裏面研削して配線層の影をなくし、フォトダイオードと画素トランジスタを別層へ分離積層することで飽和電子量（FWC）を大幅に拡大。","グローバルシャッター（全画素同時露光）：全画素に遮光メモリノードを内蔵し、全画素一斉に露光開始・終了・転送を実行。動体歪み（コンニャク現象）とフラッシュ同調速度制限を物理的に撤廃する。","※下部ドックのミクロ切替アイコンから、この画素ウェハー内部のナノスケール断面をさらに解剖できます。"],"formula":{"expression":"E_photon = hc / λ > E_g(Si) = 1.12 eV   ⇒   N_e = η(λ) · Φ · A · t_exp","description":"量子効率 η(λ)、光子束 Φ、画素面積 A、露光時間 t_exp の積が生成光電子数 N_e を決定する。"},"nextGenInnovation":"2024–2026年のフラッグシップ技術（フルサイズ・グローバルシャッター120fps／1/80,000秒全速フラッシュ同調、クロスタイプDual Pixel AF、2層トランジスタ画素＋LOFIC広DR）を集約した最先端第1ウェハー。","specs":[{"label":"有効撮像サイズ","value":"36.0 × 24.0 mm（35mmフルサイズ）"},{"label":"画素構造","value":"BSI裏面照射 + 2層トランジスタ画素"},{"label":"露光方式","value":"全画素同時電子グローバルシャッター"},{"label":"下部接続界面","value":"3 μmピッチ Cu-Cu直接接合（S09へ直結）"}],"diagramType":"stacked_die"},{"id":"sensor-cucu-layer","order":10,"swatchColor":"#d97706","groupKey":"S10_3D半導体実装・直接分子接合","assembledPos":[0,0,0.76],"explodeOffset":[0,0,4],"integratedExplodeOffset":[0,0,-24.76],"edgeOpacity":0.22,"title":"Cu-Cu バンプレス直接ハイブリッド接合層（3 μmピッチ垂直配線網）","subtitle":"3 μm-Pitch Wafer-on-Wafer Cu-Cu Bumpless Direct Hybrid Bonding Interface","category":"S10 / 3D半導体実装・直接分子接合","plainAnalogy":"上層の「光をキャッチする階（S08）」と下層の「高速計算する階（S10）」を、はんだボールも使わず数百万本の極細銅エレベーターで真下に直結する「超高層ビルの中間接続フロア」です。外周をぐるっと遠回りせず真下へ電気を送れるため、120コマ/秒という異次元の爆速データ転送と省電力が実現します。","summary":"第1ウェハー（画素層）と第2ウェハー（高速ADC/ロジック層）の間に形成される、約3 μmピッチの超微細Cu-Cu直接ハイブリッドボンディング接合界面。従来の外周貫通電極（TSV）を廃し、撮像面直下で数百万本の垂直ダイレクト配線を実現する。","opticsAndPhysics":["バンプレス・ハイブリッドボンディング（WoWoW）：上下ウェハーのSiO₂絶縁膜と埋め込み銅（Cu）パッドを化学機械研磨（CMP）で原子レベルの平坦度（粗さ < 0.5 nm）に仕上げ、常温で酸化膜同士を直接接合したのち200–300℃の低温アニールで銅パッド同士を金属拡散融合させる。","超低寄生容量＆超並列伝送：チップ外周まで長い水平配線を引き回す必要がないため、配線抵抗 R と寄生容量 C の積（RC遅延）が1/100以下に激減。全画素・ブロック単位の超並列読み出しが可能になる。","放熱パスの高効率化：全面に高密度配置された純銅パッド群が垂直方向のサーマルビアとしても機能するため、2026年世代の3ウェハー積層では従来比で約20%の熱抵抗低減を達成している。"],"formula":{"expression":"τ_RC = R_Cu · C_via ≪ 1 ns,    Pitch ≈ 2–3 μm  (≈ 10⁷ Cu-Cu bonds / die)","description":"撮像領域直下に数百万〜1千万個規模の銅-銅直接接合を形成し、超並列・超低遅延・高放熱を同時達成。"},"nextGenInnovation":"2025–2026年に実用化が進んだ3層ウェハー直接積層（WoWoW: Wafer-on-Wafer-on-Wafer）の中核技術であり、将来の全画素個別ADC（デジタルピクセルセンサー）や画素直下AI演算への道を拓いている。","specs":[{"label":"接合方式","value":"バンプレス SiO₂ + Cu-Cu 直接ハイブリッド接合"},{"label":"接続ピッチ","value":"約 2.0 – 3.0 μm（撮像エリア全面配列）"},{"label":"平坦度要求","value":"CMP 表面粗さ RMS < 0.5 nm"},{"label":"熱抵抗改善","value":"従来TSV/バンプ積層比 約 20% 低減"}],"diagramType":"sensor_cucu_layer"},{"id":"sensor-logic-dram","order":11,"swatchColor":"#4f46e5","groupKey":"S11_超高速A_D変換・オンセンサーDRAM","assembledPos":[0,0,0.46],"explodeOffset":[0,0,-3],"integratedExplodeOffset":[0,0,-29.2],"edgeOpacity":0.22,"title":"第2・第3ウェハー：高速列並列ADCロジック ＆ 積層DRAMバッファ","subtitle":"Wafer 2 & 3: High-Speed Column-Parallel CDS/ADC Logic & 120fps Stacked DRAM","category":"S11 / 超高速A/D変換・オンセンサーDRAM","plainAnalogy":"画素チップ（S08）のすぐ真下に貼り合わされた「超高速な通訳（ADC）と巨大メモ帳（DRAM）」の2階建てチップです。数千万画素からのアナログ電気信号を数千レーン並列で一瞬のうちに14〜16bitのデジタル数値へ翻訳し、120コマ/秒の膨大なデータをDRAMのメモ帳へ一時保存してからメイン基板へ送り出します。","summary":"Cu-Cu接合（S09）の直下に3次元積層された、微細ロジックプロセスによる超高速列並列CDS/ADC回路（第2ウェハー）と、120fpsグローバルシャッター連写データを一時保持する超高帯域オンセンサーDRAM（第3ウェハー）。","opticsAndPhysics":["異種プロセス最適分離（Heterogeneous Integration）：第1ウェハーは低暗電流に特化した画素専用シリコンプロセス、第2ウェハーは高速・低消費電力な微細ロジックプロセス（14nm〜4nm級）、第3ウェハーは高密度DRAMプロセスでそれぞれ独立製造し、ウェハー単位で合体させる。","相関二重サンプリング（CDS）＆列並列ADC：数千〜数万基のコンパレータが並列に動作し、画素リセット直後のノイズ基準電位と信号電位の差分を取って14–16bitへ高速量子化。読み出しノイズを1–2電子（e⁻）レベルまで抑える。","オンセンサーDRAMバッファ：全画素同時露光で一瞬に発生する数ギガビットのフレームデータを直下のDRAMへ超広帯域格納することで、後段へのSLVS-EC v3出力（~128 Gbps）と完璧に速度整合させる。"],"formula":{"expression":"V_CDS = (V_sig + V_kTC) − (V_rst + V_kTC) = V_sig − V_rst,   BW_DRAM > 1 Tbps","description":"CDSで熱リセットノイズを物理相殺し、第3ウェハーDRAMの超広帯域が120fps・歪みゼロ連写を支える。"},"nextGenInnovation":"2024–2026年のフラッグシップ積層センサーでは、第2ロジック層内部にリアルタイムHDR合成（LOFIC/DCGマージ）やAF位相差前処理回路まで統合され、センサー自体がインテリジェント処理を担う時代へ突入している。","specs":[{"label":"第2ウェハー機能","value":"列並列 CDS / 14–16bit 高速 ADC ロジック"},{"label":"第3ウェハー機能","value":"超広帯域 積層 DRAM フレームバッファ"},{"label":"読み出し速度","value":"最大 120 fps フルサイズ RAW（GS対応）"},{"label":"読み出しノイズ","value":"< 1.0 – 2.5 e⁻ RMS（高変換ゲイン時）"}],"diagramType":"sensor_logic_dram"},{"id":"sensor-dram-wafer","order":12,"swatchColor":"#312e81","groupKey":"S12_3層積層CMOS・超高速フレームバッファメモリ","assembledPos":[0,0,0.06],"explodeOffset":[0,0,-11],"integratedExplodeOffset":[0,0,-34],"edgeOpacity":0.22,"title":"第3ウェハー：3層積層・超広帯域 DRAM バッファダイ ＆ 貫通Cu-TSVスパイン","subtitle":"Wafer 3 — 3D-Stacked Ultra-High-Bandwidth 120fps DRAM Die & Copper TSV Spine","category":"S12 / 3層積層CMOS・超高速フレームバッファメモリ","plainAnalogy":"画素チップと計算チップのさらに真下に貼り付けられた「超高速な一時データ倉庫（第3のシリコン板）」。1秒間に120枚もの超高精細写真を一瞬で飲み込み、メイン基板へ落ち着いて送り出す秘密基地です。","summary":"画素ウェハー（Wafer 1）と4nm ADCロジックウェハー（Wafer 2）のさらに直下へ3次元積層された専用超広帯域DRAMメモリウェハー（Wafer 3）。中央を貫通する高密度銅TSV（Through-Silicon Via）スパインとナノ銀焼結接合層を介して数Tbps級のオンセンサーメモリ帯域を実現し、ブラックアウトフリー120fps連写とローリング歪み極小化を支えます。","opticsAndPhysics":["3層積層構造による読み出しボトルネックの解消：外部SLVS-ECインターフェースの伝送速度（最大約128Gbps）を超える瞬間データレートで全画素を一斉ADC変換しても、直下の第3ウェハーDRAM（数Gbit級）へ瞬時に退避できるため、実質的な読み出し時間を1/250秒〜完全グローバル同時化できます。","銅TSV（シリコン貫通電極）による最短垂直配線：薄化研削（約40〜60μm厚）したDRAMシリコン基板を垂直に貫通する銅TSV群により、電源供給インピーダンスと配線遅延を大幅に削減しています。","プリキャプチャー＆120fps RAW連続記録：シャッター全押し前から直近1秒間（最大120フレーム）をDRAMリングバッファへ常時循環記録するプリ撮影機能のハードウェア基盤でもあります。"],"formula":{"expression":"BW_internal = N_col · f_ADC · B_bit > 1.2 Tbps   (オンセンサーDRAMで瞬時吸収!)","description":"外部出力帯域の約10倍の内部DRAM書き込み帯域により、全画素超高速読み出しとブラックアウトフリー連写を実現。"},"nextGenInnovation":"2025–2026年の次世代イメージセンサー（ISSCC発表の3層積層センサーやLYTIA上位系）では、DRAMウェハーとロジックウェハーの接合にも微細Cu-Cuハイブリッドボンディングが導入され、さらなる低消費電力化と高速化が進んでいます。","specs":[{"label":"積層位置","value":"3層積層CMOS 最下層（Wafer 3 / 40–60 μm薄化ダイ）"},{"label":"貫通配線","value":"高密度 銅TSV（Through-Silicon Via）垂直スパイン"},{"label":"ダイ接合材","value":"高熱伝導ナノ銀焼結（Ag Sintered）ダイアタッチ層"},{"label":"役割","value":"120fps RAW瞬時バッファ・プリキャプチャー・歪み低減"}],"diagramType":"sensor_dram_wafer"},{"id":"wire-bonds","order":13,"swatchColor":"#e3b952","groupKey":"S13_マイクロ電気実装","assembledPos":[0,0,0.55],"explodeOffset":[0,0,-19],"integratedExplodeOffset":[0,0,-38.8],"edgeOpacity":0.22,"title":"超高密度 99.99% 純金 低ループ・ワイヤーボンディング","subtitle":"4N Au Ultra-Low-Loop Thermosonic Wire Bond Array","category":"S13 / マイクロ電気実装","plainAnalogy":"半導体チップ（S08〜S10）の周りにある小さな電極と、外側のセラミック容器（S12）を数百本の「髪の毛より細い99.99%純金の糸」でびっしり結ぶ超微細ブリッジです。一瞬の大電流や100ギガビット級の高速信号がブレないように、純金の糸を極限まで低く短くアーチ状に張っています。","summary":"シリコンダイ外周に並ぶ数百個のアルミ／金電極パッドと、セラミックパッケージ内部の段付きシェルフ電極を電気的に接続する直径約25 μmの超高純度金（4N Au）ワイヤー群。","opticsAndPhysics":["サーモソニック接合：約150〜200℃の加熱と超音波振動（60–120 kHz）および加圧を同時に与え、金ボールとアルミパッド界面に金属間化合物（Au-Al拡散層）を形成して強固なオーミック接触を実現。","寄生インダクタンス最小化：高速差動信号（SLVS-EC 10 Gbps級）や瞬時大電流（グローバルシャッター一斉転送時のパルス電流）では、ワイヤーの寄生インダクタンス L による電源ドロップ ΔV = L(di/dt) がノイズ源となるため、極限まで短い超低ループ（高さ55–80 μm）設計が不可欠。","隣接する電源・グラウンドワイヤーを交互配置（GSG: Ground-Signal-Ground）することでリターンパスを最短化し、高周波クロストークとEMI放射を抑制。"],"formula":{"expression":"ΔV_noise = L_wire · (dI / dt),   L ≈ (μ₀ l / 2π) · [ln(2l / r) − 0.75]","description":"ワイヤー長 l を短縮し並列グラウンド本数を増やすことで同時スイッチングノイズ（SSN）を激減。"},"nextGenInnovation":"全画素同時露光や120fps読み出しに伴う急峻な過渡電流を安定供給するため、段付きセラミックシェルフと超低ループボンディング（大電流ピンへの複数並列ボンド併用）が採用されている。","specs":[{"label":"ワイヤー材質・純度","value":"99.99% 純金（4N Au）"},{"label":"線径 / ループ高","value":"φ 20–25 μm / 低ループ 55–80 μm"},{"label":"接続方式","value":"熱圧着超音波（サーモソニック）接合"},{"label":"ピン構成","value":"GSG 差動高速信号 + 多系統分離電源"}],"diagramType":"wirebond"},{"id":"ceramic-package","order":14,"swatchColor":"#3e424c","groupKey":"S14_精密パッケージ・平坦度維持","assembledPos":[0,0,-0.55],"explodeOffset":[0,0,-27],"integratedExplodeOffset":[0,0,-43],"edgeOpacity":0.22,"title":"高剛性アルミナ12層 HTCC セラミック LGA パッケージ","subtitle":"High-Flatness HTCC Alumina Ceramic Cavity Package & CuW Slug","category":"S14 / 精密パッケージ・平坦度維持","plainAnalogy":"センサーチップを1ミクロンも反らせず真っ平らに寝かせて支える「超高精度な焼き物（セラミック）の器」です。F1.2の極薄ピントではセンサーが髪の毛の1/10反るだけで四隅がボケてしまうため、プラスチックではなく極めて硬いアルミナセラミックを使い、底には熱を逃がす金属プレートを埋め込んでいます。","summary":"フルサイズ大判シリコンダイをミクロン単位の平坦度で支え、3次元多層配線と高効率背面放熱を担う高温同時焼成アルミナセラミック（HTCC）キャビティパッケージ。","opticsAndPhysics":["光学像面平坦度：大口径 F1.2 レンズの焦点深度（DoF）はセンサー面上でわずか数ミクロンしかない。樹脂基板では吸湿・熱膨張で数十μm反ってしまうため、ヤング率 約310 GPa の極めて高剛性なアルミナ（Al₂O₃）セラミックが必須となる。","3次元多層配線：12層のアルミナグリーンシート間にタングステン／モリブデン導体パターンを印刷し一体焼成することで、上面ワイヤーボンド棚から背面LGA（Land Grid Array）金めっきパッド群へ低インピーダンス・等長配線を引き回す。","サーマルスラグ：ダイ直下のキャビティ底面に、シリコンに近い低熱膨張かつ高熱伝導（~200 W/m·K）のタングステン-銅複合合金（CuW）ヒートスラグを埋め込み、ダイ発熱を即座に背面へ逃がす。"],"formula":{"expression":"δ_focus ≈ ±2 · F · c_blur  (F1.2 で焦点深度はわずか ±5–8 μm)","description":"パッケージ全体の反りを数μm以下に抑える高平坦焼成技術が画面四隅のシャープネスを保証する。"},"nextGenInnovation":"最新世代のセラミックパッケージは無研磨高平坦焼成技術により、研磨加工由来のセラミック微粉（ダスト発生源）を根本排除し、クリーンルーム組立歩留まりと長期信頼性を飛躍的に高めている。","specs":[{"label":"セラミック基材","value":"高強度アルミナ HTCC（12層一体焼成）"},{"label":"平坦度 / ヤング率","value":"< 5 μm（36×24 mm域） / ~310 GPa"},{"label":"背面放熱スラグ","value":"タングステン-銅合金（CuW）"},{"label":"表面電極めっき","value":"電解 Ni / Au 金めっき LGA パッド"}],"diagramType":"ceramic_pkg"},{"id":"sensor-cuw-slug","order":15,"swatchColor":"#92400e","groupKey":"S15_チップ直下放熱コア・シリコン熱膨張完全整合","assembledPos":[0,0,-1.1],"explodeOffset":[0,0,-35],"integratedExplodeOffset":[0,0,-46.8],"edgeOpacity":0.22,"title":"タングステン銅 (CuW80) 熱膨張整合ヒートスラッグ ＆ ナノ銀焼結接合層","subtitle":"CTE-Matched Tungsten-Copper (CuW80) Thermal Slug & Nano-Silver Sintered Die-Attach","category":"S15 / チップ直下放熱コア・シリコン熱膨張完全整合","plainAnalogy":"薄いシリコンセンサーのすぐ裏にビタッと張り付いた「熱を素早く吸う重い金属の座布団」。温まってもシリコンとほぼ同じ割合でしか伸び縮みしない特殊な合金なので、長時間の8K動画撮影でもセンサーが反りません。","summary":"HTCCセラミックパッケージの中央貫通キャビティへロウ付け一体化されたタングステン銅合金（W 80% / Cu 20%）製ヒートスラッグと、シリコンダイ裏面を直結する高熱伝導ナノ銀焼結（220 W/m·K）ダイアタッチ層。シリコンとセラミックの線膨張係数を精密に整合させつつ、3層積層CMOSの発熱（4〜6W）を真後ろのTIM/グラファイト経路へ垂直排出します。","opticsAndPhysics":["線膨張係数（CTE）の完璧なマッチング：純銅（CTE ≈ 17 ppm/K）へ直接フルサイズ40×28mmの巨大なシリコンダイ（CTE ≈ 2.6 ppm/K）を接着すると、温度変化によるバイメタル反りでセンサー平面度が崩れ、画面四隅がボケます。CuW80合金はCTE ≈ 6.5–7.2 ppm/Kに調整されており、アルミナセラミック（7.0 ppm/K）と一致し反りを極限まで抑えます。","ナノ銀（Ag）加圧焼結ダイアタッチ：従来の銀ペースト樹脂接着剤（k ≈ 3–8 W/m·K）に代わり、ナノ銀粒子を低温焼結した金属接合層（k ≈ 180–220 W/m·K）を採用することで、チップ直下の界面熱抵抗を1/20以下へ低減しています。","センサー平面度 ±3μm の剛性基準：高いヤング率（約290 GPa、鉄の1.4倍）を持つタングステン骨格が、大面積フルサイズセンサーの完全な光学平面性を長期維持します。"],"formula":{"expression":"κ_warp ∝ (α_slug − α_Si) · ΔT / t   (CuW80 + ナノ銀焼結で反り < 2 μm ＆ 低熱抵抗!)","description":"高ヤング率・低CTEのCuW80ヒートスラッグが、8K録画時の発熱下でもフルサイズセンサー面のミクロン平面度を守り抜く。"},"nextGenInnovation":"積層グローバルシャッターや8K60p対応センサーではセンサー自体の発熱密度が従来比2倍以上に増大しており、CuWスラッグ＋ナノ銀焼結接合の組み合わせが暗電流ノイズ抑制の最重要基盤となっています。","specs":[{"label":"材質 / 組成","value":"タングステン銅複合合金 CuW80（W80% / Cu20%）"},{"label":"熱伝導率 / CTE","value":"約 200 W/(m·K) / 線膨張係数 7.0 ppm/K"},{"label":"ダイ接合層","value":"圧力焼結ナノ銀（Ag, k ≈ 220 W/m·K）"},{"label":"センサー平面度維持","value":"全温度域（−20〜+65℃）にて ± 2 〜 3 μm 以内"}],"diagramType":"sensor_cuw_slug"},{"id":"sensor-pcb","order":16,"swatchColor":"#1b5649","groupKey":"S16_低ノイズ電源・信号整合","assembledPos":[0,0,-2.45],"explodeOffset":[0,0,-44],"integratedExplodeOffset":[0,0,-50.5],"edgeOpacity":0.22,"title":"高多層センサーリジッド基板 ＆ 分離アナログ電源回路網","subtitle":"High-Density Build-Up Sensor PCB & Ultra-Low-Noise Power Stage","category":"S16 / 低ノイズ電源・信号整合","plainAnalogy":"セラミック容器（S12）のすぐ裏側にくっついて、ノイズの一切ない「超きれいな電気」をセンサーへ供給する専用ミニ基板です。デジタル回路の電気ノイズが混ざると写真に横縞が出てしまうため、専用の静かな電源ICと数十個のコンデンサで電気を丁寧にろ過してからセンサーへ渡します。","summary":"セラミックLGAパッケージを実装し、極めて清浄なアナログ電源供給、水晶基準クロック生成、および100 Gbps級高速差動データ伝送のインピーダンス整合を担うセンサー直結基板。","opticsAndPhysics":["アナログ／デジタル電源の厳密分離：画素フォトダイオード駆動（2.8V）およびアナログADC基準電源（2.2V）に微小なリップルが混入すると、画像全体に横縞ノイズ（バンディング）が発生する。超高PSRRの専用LDOレギュレータと数十個のMLCCをダイ直下に配置し、高周波インピーダンスを極小化。","高速差動等長配線：SLVS-EC差動信号ペアの特性インピーダンスを 100 Ω ±5% に制御し、メアンダ配線で配線長をサブミリ単位で揃えることでスキュー（位相差）を排除。","サーマルビアアレイ：基板中央のパッケージ直下に高密度の銅めっきサーマルビア貫通穴を配列し、センサーの発熱を背面のシリコーンTIMパッド（S24）・Σ字型グラファイト（S25）へ直通させる。"],"formula":{"expression":"Z_diff = 2 Z₀ (1 − k_coupling) = 100 Ω,   PSRR = 20 log₁₀(ΔV_in / ΔV_out)","description":"差動特性インピーダンス整合と高PSRR電源設計が、暗部16bit相当の低ノイズ階調を支える。"},"nextGenInnovation":"120fpsフルサイズRAWや8K 60p RAW出力ではセンサー消費電力が数ワットに達するため、低ESR薄膜コンデンサと多層厚銅グラウンドプレーンを併用し、高速スイッチング時の電圧降下と発熱の双方を抑えている。","specs":[{"label":"基板構造","value":"8〜10層 高密度ビルドアップ（FR-4高Tg材）"},{"label":"分離電源系統","value":"Analog 2.8V / 2.2V, Digital 1.2V, I/O 1.8V"},{"label":"差動インピーダンス","value":"100 Ω 制御（等長メアンダ配線）"},{"label":"直近バイパス","value":"超小型 0402/0201 MLCC アレイ実装"}],"diagramType":"sensor_pcb"},{"id":"slvs-fpc","order":17,"swatchColor":"#c96b1c","groupKey":"S17_超高速インターフェース・可動配線","assembledPos":[0,0,-2.45],"explodeOffset":[0,0,-52],"integratedExplodeOffset":[0,0,-55.8],"edgeOpacity":0.22,"title":"SLVS-EC v3 超高速シールド・フレキシブル伝送基板","subtitle":"Impedance-Controlled SLVS-EC v3 U-Loop Shielded Flex Harness","category":"S17 / 超高速インターフェース・可動配線","plainAnalogy":"手ぶれ補正（IBIS）で空中をフワフワ動くセンサーと、固定されたメイン基板を結ぶ「超やわらかくて超高速なデータの架け橋」です。硬いケーブルだと手ぶれ補正の邪魔になるため、左右対称のU字カーブでしなやかに曲がりつつ、1秒間にブルーレイ映画何本分もの写真データを送ります。","summary":"5軸IBISで空中浮上・高速移動するセンサー基板と、固定されたメイン画像処理エンジン基板を繋ぐ、超低剛性U字ループ構造の高速シールドフレキシブル基板（FPC）。","opticsAndPhysics":["SLVS-EC（Scalable Low-Voltage Signaling with Embedded Clock）：200 mVの極めて低い差動電圧振幅と 8b/10b エンベデッドクロック符号化により、外部クロック線を廃しレーン間スキュー問題を解消。1レーン最大10.0 Gbps × 16レーンで128 Gbps級の圧倒的帯域を実現。","U字ループ低復元剛性設計：IBISがサブミクロン精度でセンサーを動かす際、ケーブルの曲げ反力とヒステリシスは外乱トルクになる。ポリイミド基材を左右対称に大きくU字湾曲させることで可動反力を極限まで減らし、数億回の微小屈曲疲労にも耐える。","EMI電磁シールドフィルム：高速差動信号から周囲の無線回路やアナログ回路への放射ノイズを抑えるため、極薄導電シールド層をラミネート。"],"formula":{"expression":"Throughput = N_lanes × R_baud × (8/10)  ⇒  16 × 10 Gbps × 0.8 = 128 Gbps","description":"200 mV 低振幅差動伝送により高速転送と低消費電力・低EMIを両立。"},"nextGenInnovation":"従来のSub-LVDS（~0.6 Gbps/lane）の約16倍に達するSLVS-EC v3の超広帯域により、フルサイズ24–50MPセンサーからの120fps連写RAWや8K 60p RAWのリアルタイム無圧縮転送が可能となった。","specs":[{"label":"伝送規格","value":"SLVS-EC v3（8b/10b 埋込クロック）"},{"label":"レーン速度 / 振幅","value":"最大 10.0 Gbps/lane / 200 mV 差動"},{"label":"基材・シールド","value":"ポリイミド（カプトン）+ 極薄EMI遮蔽膜"},{"label":"機械形状","value":"左右対称 U字低剛性フレキシャルループ"}],"diagramType":"slvs_fpc"},{"id":"sensor-temp-ntc-board","order":18,"swatchColor":"#22c55e","groupKey":"S18_リアルタイム温度監視・暗電流減算_熱保護制御","assembledPos":[0,0,-2.55],"explodeOffset":[-36,14,-44],"integratedExplodeOffset":[-44,18,-50.5],"edgeOpacity":0.22,"title":"高精度 NTC センサー温度計測サブ基板 ＆ 暗電流リアルタイム補正ブリッジ","subtitle":"Precision ±0.1°C NTC Die-Temperature Sensor Sub-Board & Dark-Current Calibration","category":"S18 / リアルタイム温度監視・暗電流減算＆熱保護制御","plainAnalogy":"イメージセンサーのすぐ隣にピタッと貼られた「超高精度なデジタル体温計」。センサーの体温を0.1℃単位でつねに測り、熱で増えるザラザラノイズ（暗電流）を計算でキレイに引き算してくれます。","summary":"センサーメイン基板の左肩へ熱結合された超高精度NTCサーミスタ（負温度係数抵抗素子）および24bit Σ-Δ ADC温度監視サブ基板。CMOSダイ直近の温度を±0.1℃精度で常時サンプリングし、長秒露光ノイズリダクション、黒レベル（オプティカルブラック）温度ドリフト補正、および8K録画時のサーマルスロットリング制御へリアルタイム供給します。","opticsAndPhysics":["暗電流の温度指数法則（アレニウス則）の厳密補正：シリコンの暗電流は温度が約6〜8℃上昇するごとに2倍へ急増します。NTCサーミスタが計測する精密温度プロファイルと工場キャリブレーションLUT（ルックアップテーブル）を連動させ、ダークフレーム撮影なしでも高感度・長秒露光の暗電流ムラを補正します。","IBISボイスコイル発熱との熱分離計測：すぐ近傍のVCM駆動コイルが発熱しても誤検知しないよう、セラミックパッケージ縁部へ高熱伝導接着で直接ブリッジし、シリコンダイ温度を忠実に追従します。","安全な温度保護制御：高温環境での4K120p/8K連続収録時に、チップ接合部温度が上限へ達する前に段階的に通知・安全停止を行い、永久的なホットピクセル劣化を防ぎます。"],"formula":{"expression":"R(T) = R_0 · exp[ B · (1/T − 1/T_0) ]   ⇒   ΔT精度 ± 0.1 ℃ で暗電流 I_dark(T) を予測補正","description":"NTCサーミスタの急峻な抵抗変化からダイ温度を精密検出し、ISPの黒レベル補正および熱管理アルゴリズムへ直結。"},"nextGenInnovation":"2025–2026年モデルでは、オンチップ内蔵ダイオード温度計とパッケージ外周の複数点NTCサブ基板を組み合わせ、画面左右の温度勾配（片側だけ熱カブリするアンプグロー現象）まで空間マップ補正する技術が普及しています。","specs":[{"label":"感温素子","value":"高精度薄膜 NTC サーミスタ（B定数誤差 ±0.5%）"},{"label":"計測分解能 / 精度","value":"0.01 ℃ 分解能 / ± 0.1 ℃ 絶対精度"},{"label":"主な用途","value":"暗電流ムラ補正・黒レベル安定化・8K録画熱保護"},{"label":"配置","value":"センサーPCB左肩・HTCCパッケージ熱結合ブリッジ"}],"diagramType":"sensor_temp_ntc"},{"id":"ibis-carrier","order":19,"swatchColor":"#94a3b8","groupKey":"S19_5軸手ぶれ補正・可動骨格","assembledPos":[0,0,-4.3],"explodeOffset":[0,0,-60],"integratedExplodeOffset":[0,0,-61],"edgeOpacity":0.22,"title":"5軸IBIS可動マグネシウム合金ステージ（フローティングキャリア）","subtitle":"5-Axis IBIS Topology-Optimized Die-Cast Magnesium Movable Stage","category":"S19 / 5軸手ぶれ補正・可動骨格","plainAnalogy":"イメージセンサー一式を背負って、手ぶれと逆向きに空中をビュンビュン滑る「超軽量な空飛ぶソリ」です。重たいと素早く動けず、柔らかいと振動でブレてしまうため、レーシングカーのフレームのようにコンピューターで肉抜き最適化されたマグネシウム合金で作られています。","summary":"光学フィルター群・CMOSダイ・センサー基板（S01–S13）を一体保持し、光軸直交平面内でX・Y並進およびRoll回転の3自由度（5軸手ぶれ補正）へ高速駆動される、トポロジー最適化マグネシウム可動ステージ。","opticsAndPhysics":["比剛性最大化と低慣性モーメント：8.5段クラスの5軸手ぶれ補正では、シャッターショックや手ぶれの角加速度に対しミリ秒未満で応答する必要がある。マグネシウム合金（密度 1.8 g/cm³）を中央放熱窓・肉抜きトラス構造にすることで、高固有振動数（> 500 Hz）と超軽量を両立。","4点ステンレス精密ボス：センサー基板（S13）との結合面に高剛性ステンレスボスを配置し、IBISの激しい加減速でも像面（センサー面）の傾き・共振を防ぐ。","空芯ボイスコイル（S16）とホール位置センサー（S17）を搭載し、背面3点のセラミックボール（S18）上を摩擦ほぼゼロで滑走する。"],"formula":{"expression":"f_natural = (1 / 2π) · √(K_stage / M_moving),    a_IBIS = F_VCM / M_moving","description":"可動質量 M_moving を極限まで削りつつ剛性 K を高めることで、手ぶれ補正サーボ帯域を広帯域化。"},"nextGenInnovation":"同じサブミクロン精密ステージを応用し、センサーを0.5画素または1画素ずつ厳密にシフトさせて4〜16枚合成する「ピクセルシフトマルチショット（超高解像・真RGB色再現）」や星景自動追尾も実現している。","specs":[{"label":"ステージ材質","value":"トポロジー肉抜き マグネシウム合金ダイキャスト"},{"label":"制御自由度","value":"X並進・Y並進・Roll回転（5軸8.5段補正）"},{"label":"中央開口構造","value":"Σ字グラファイト放熱橋用サーマルウィンドウ"},{"label":"固有共振周波数","value":"> 500 Hz（サーボ帯域外へ高剛性化）"}],"diagramType":"ibis_vcm"},{"id":"sensor-front-yoke-plate","order":20,"swatchColor":"#475569","groupKey":"S20_閉磁気回路・磁束密度1_7倍化_8_5段IBIS高推力化","assembledPos":[0,0,-3.35],"explodeOffset":[0,0,-68],"integratedExplodeOffset":[0,0,-64.8],"edgeOpacity":0.22,"title":"IBIS 磁気回路・前面軟鉄フラックス閉鎖ヨークプレート（両面磁気ギャップ）","subtitle":"IBIS Dual-Sided Magnetic Circuit Front Soft-Iron Flux-Closing Yoke Plate","category":"S20 / 閉磁気回路・磁束密度1.7倍化＆8.5段IBIS高推力化","plainAnalogy":"手ブレ補正モーターの磁石とコイルを「前後からサンドイッチ」する鉄のふた。磁力が外へ逃げないようにギュッと閉じ込めることで、同じ電気でも手ブレを止める力が約1.7倍にパワーアップします。","summary":"3基のIBIS空芯ボイスコイル（S21）と背面N52ネオジム磁石（S27）の前方（+Z側）へ精密クリアランスで固定配置された、高透磁率パーマロイ／電磁軟鉄製フロントヨークプレート。背面ヨークと合わせて「閉磁気回路（クローズド・エアギャップ）」を形成し、コイル断面を貫く磁束密度Bを約1.7倍へ高めると同時に、漏洩磁場によるシャッターや電子回路への悪影響を遮断します。","opticsAndPhysics":["磁気抵抗（リラクタンス）の劇的低減：片側ヨーク開放型では磁束が空中で大きく広がって弱まりますが、前面に軟鉄ヨークプレートを対向させることで磁力線がボイスコイルを垂直に貫通する高密度・均一な磁場空間が生まれます。","ローレンツ推力 F = B·I·L の飛躍的増強：磁束密度 B が向上することで、同じ手ブレ補正加速度を得るのに必要なコイル電流 I が約60%で済み、結果としてジュール発熱（I²R）を約1/3（約65%削減！）へ劇的に抑制できます。","シャッター幕・レンズ側への磁気シールド：強力なN52ネオジム磁石（1.4テスラ級）の漏洩磁束を前面ヨーク内で還流させるため、直前わずか数mmにあるフォーカルプレーンシャッターの駆動アクチュエーターと磁気干渉を起こしません。"],"formula":{"expression":"F = B · I · L,   P_heat = I² R ∝ 1 / B²   (B が 1.7× ⇒ コイル発熱が 1/2.9 へ激減!)","description":"前面軟鉄ヨークによる閉磁気回路化が、強力な8.5段手ブレ補正推力とIBIS発熱の劇的低減を同時に叶える。"},"nextGenInnovation":"8.0〜8.5段クラスの手ブレ補正と動画アクティブ手ブレ補正を長時間駆動する最新ミラーレスでは、3基のVCMすべてを閉磁気回路化する両面ヨーク構造と高飽和磁束密度軟鉄材の採用が不可欠となっています。","specs":[{"label":"材質","value":"高飽和磁束密度 電磁軟鉄 / SPCC・パーマロイ積層"},{"label":"磁気回路効果","value":"エアギャップ磁束密度 約 1.65 〜 1.75 倍向上"},{"label":"省電力・低発熱","value":"同一推力時のVCM発熱を約 65% 削減"},{"label":"副次効果","value":"直前のシャッター機構に対する磁気シールド遮蔽"}],"diagramType":"sensor_front_yoke"},{"id":"sensor-vcm-coils","order":21,"swatchColor":"#c86432","groupKey":"S21_ローレンツ力アクチュエータ","assembledPos":[0,0,-5.08],"explodeOffset":[0,0,-76],"integratedExplodeOffset":[0,0,-68.4],"edgeOpacity":0.22,"title":"3軸独立・空芯平面銅ボイスコイルモーター群（VCMコイル）","subtitle":"3x Independent Air-Core Flat Copper Voice Coils (Y1 / Y2 / X1) & Flex Bus","category":"S21 / ローレンツ力アクチュエータ","plainAnalogy":"スピーカーの音を鳴らす仕組みと同じ「磁石と電気の押し引き」でセンサーを動かす、3つの平らな銅線コイルです。歯車もネジも一切使わないためガタつきがゼロで、下にある2つのコイルが同時に動くと上下（Y）、逆向きに動くと回転（ロール）、右のコイルが左右（X）を一瞬で動かします。","summary":"可動マグネシウムステージ（S15）の背面に実装された3基の空芯平面銅線ボイスコイル（Y1・Y2・X1）と駆動フレキバス。背面の固定N52ネオジム磁石（S21）の磁場中で電流に応じたローレンツ力を発生し、非接触・ゼロバックラッシュ駆動を行う。","opticsAndPhysics":["ローレンツ力ダイレクトドライブ：磁束密度 B の均一な磁場中を走る導線に制御電流 I を流すと、フレミングの左手の法則により F = N·I·(L × B) の推力が瞬時に発生。鉄芯を持たない「空芯（Air-Core）」構造のため、鉄芯のヒステリシスやコギング（引っかかり）が一切存在しない。","3コイルによる5軸手ぶれ補正合成：下辺の左右2基（Y1, Y2）を同相駆動すればY軸上下並進、逆相駆動すればRoll回転 θ_z、右辺の1基（X1）でX軸左右並進を生成。さらに焦点距離に応じた微小XYシフトでPitch/Yawの角度ブレを光学的に打ち消し、レンズISとの協調制御で最大8.5段補正を実現。","高占積率平角銅線：断面が四角い平角エナメル銅線を高密度に整列巻きすることで、薄いスペースでも高い推力定数（N/A）と低発熱を両立。"],"formula":{"expression":"F_Y = F₁ + F₂,   τ_Roll = (F₂ − F₁) · r_arm,   F_i = N · I_i · L_eff · B_gap","description":"電流に厳密線形比例する3基の推力合成により、X・Y・Rollの全方向へサブミクロン応答を実現。"},"nextGenInnovation":"最新の8.5段IBISでは、シャッター連写中の反動ショック予測フィードフォワード電流と、広角レンズ周辺で目立つ回転ブレ（Roll）＋周辺歪みを同時に打ち消す協調制御アルゴリズムが各VCMコイルを毎秒数千回PWM駆動している。","specs":[{"label":"アクチュエータ構成","value":"3基独立 空芯平面ボイスコイル（Y1, Y2, X1）"},{"label":"巻線仕様","value":"高占積率 平角無酸素銅線（コギングゼロ）"},{"label":"制御ループ周波数","value":"数 kHz クローズドループ PWM 電流駆動"},{"label":"手ぶれ補正性能","value":"5軸 最大 8.5段（CIPA 2024規格準拠）"}],"diagramType":"sensor_vcm_coils"},{"id":"sensor-hall-pcb","order":22,"swatchColor":"#16a34a","groupKey":"S22_非接触磁気センシング・精密帰還制御","assembledPos":[0,0,-5.05],"explodeOffset":[0,30,-76],"integratedExplodeOffset":[0,42,-68.4],"edgeOpacity":0.22,"title":"3軸サブミクロン・ホール効果位置センサー基板 ＆ 検出IC群","subtitle":"3-Axis Sub-Micron Hall-Effect Position Feedback PCB & Sensing ICs","category":"S22 / 非接触磁気センシング・精密帰還制御","plainAnalogy":"手ぶれ補正で動くセンサーが「今ちょうど何ミクロンの場所にいるか」を、触れずに磁力のわずかな変化から読み取る超精密な「磁気の目」です。なんと0.006度（100m先の髪の毛の揺れレベル）の手ぶれすら見逃さず、1秒間に数千回も現在位置を報告して完璧なピタ止めを支えます。","summary":"3基の空芯ボイスコイル（S16）の中央空間に配置された高感度ホール効果磁気センサーIC×3と、微小なアナログホール電圧を低ノイズ増幅・伝送する専用フレキシブル帰還基板。","opticsAndPhysics":["ホール効果（Hall Effect）：半導体薄片に一定のバイアス電流 I_sense を流した状態で垂直に磁場 B が貫くと、キャリアがローレンツ力で偏り、電流と磁場の両方に直交する方向へホール起電力 V_H = (I_sense · B) / (n · e · t) が発生する。","サブミクロン位置検出：固定側の2極N52ネオジム磁石（S21）のN極とS極の境界（ゼロクロス近傍）では磁束密度 B(x) が位置に対して直線的に急勾配変化するため、ホールICの電圧を読むだけで接触ゼロ・摩耗ゼロのままサブミクロン（< 0.1 μm）分解能で絶対位置を把握できる。","5軸ジャイロとのセンサフュージョン：ボディ内の超低ノイズ角速度ジャイロ＋加速度センサーが検出した手ぶれ量（目標座標）と、ホールICが検出した実位置（現在座標）の誤差をPID制御器で毎秒数千回ゼロへ収束させる。"],"formula":{"expression":"V_H = (I_sense · B(x,y)) / (n · e · t),    Δx_res < 0.1 μm  (≈ 0.006° 検出)","description":"2極磁石の線形磁束勾配をホール電圧で読み取り、0.1 μm以下の超高分解能でクローズドループ制御。"},"nextGenInnovation":"2024–2026年のフラッグシップIBIS（Sony α1 II / Nikon Z9 / Canon EOS R1等）では、温度ドリフト補償内蔵のデジタル出力ホールICと高精度ジャイロの組み合わせにより、8.5段補正と1画素未満の厳密なピクセルシフト合成を両立している。","specs":[{"label":"センサー素子","value":"高感度 InSb / GaAs ホール効果IC × 3軸"},{"label":"位置検出分解能","value":"< 0.1 μm（角度換算 ~0.006° 検出）"},{"label":"温度補正","value":"オンチップ温度ドリフト補償回路内蔵"},{"label":"配線基材","value":"低ノイズシールド・ポリイミド帰還FPC"}],"diagramType":"sensor_hall_pcb"},{"id":"ceramic-balls","order":23,"swatchColor":"#2c3240","groupKey":"S23_キネマティック機械力学","assembledPos":[0,0,-5.7],"explodeOffset":[0,0,-86],"integratedExplodeOffset":[0,0,-73.8],"edgeOpacity":0.22,"title":"3点窒化ケイ素（Si₃N₄）セラミックボール ＆ 焼入れレース","subtitle":"Kinematic 3-Point Si₃N₄ Ceramic Ball Bearings & Hardened Stainless Races","category":"S23 / キネマティック機械力学","plainAnalogy":"3本脚のイスがどんな床でも絶対にガタつかないのと同じ原理で、センサーのソリを3粒の「超ツルツルで磁石にくっつかないセラミックの玉」で支える仕組みです。油を差さなくてもスーッと滑るため、センサー室に油が飛び散る心配ゼロで、ピント面の傾きを1ミクロン以下に保ちます。","summary":"可動センサーキャリア（S15）を光軸方向（Z軸）の傾き・ガタ一切ゼロのまま、XY並進およびRoll回転方向へ超低摩擦で滑らせる3点支持キネマティック・セラミックボールベアリングと焼入れステンレス転動レース。","opticsAndPhysics":["キネマティック3点平面拘束：空間内の平面は一直線上にない3点で一意かつ過剰拘束なく決定される。4点支持では微小な高さ誤差でガタやこじりが生じるが、3個の超精密セラミック球（真球度 0.1 μm級）で支えることで完全な平面追従を実現。","窒化ケイ素（Si₃N₄）セラミック球：非磁性（直近のN52ネオジム磁石の強磁場に一切吸着されない）、超軽量、高硬度（ビッカース硬度 ~1500 HV）、低摩擦係数、かつ無潤滑でも焼き付かないため、クリーンな光学室内への油分飛散リスクを完全排除できる。","鏡面焼入れステンレスレース：セラミック球が転がる上下の受け座（レース）を超鏡面ラップ仕上げとし、転がり抵抗 μ_roll ≈ 0.001 の滑らかな初動応答を実現。"],"formula":{"expression":"F_friction = μ_roll · F_preload   (μ_roll ≈ 0.001,  ΔZ_tilt < 1.0 μm)","description":"非磁性セラミック球の点接触転がり支持により、Z軸の光軸チルトを1 μm未満に封じ込めながら滑走。"},"nextGenInnovation":"最新の8.5段クラスIBISでは、3球の配置三角形をセンサー重心に対して最適設計し、激しい縦横パン撮影や望遠レンズ装着時の慣性モーメントでもボール浮き上がり（片ボケ）が一切起きない構造となっている。","specs":[{"label":"ボール材質","value":"窒化ケイ素ファインセラミック (Si₃N₄)"},{"label":"真球度 / 硬度","value":"0.1 μm級 / 約 1,500 HV（非磁性・無潤滑）"},{"label":"支持幾何","value":"キネマティック 3点平面拘束"},{"label":"光軸チルト誤差","value":"< 1.0 μm（全ストローク域）"}],"diagramType":"ceramic_balls"},{"id":"sensor-preload-plates","order":24,"swatchColor":"#64748b","groupKey":"S24_磁気予圧・重心力学設計","assembledPos":[0,0,-4.75],"explodeOffset":[0,-32,-86],"integratedExplodeOffset":[0,-40,-74.5],"edgeOpacity":0.22,"title":"磁気プリロード強磁性吸引プレート ＆ 重心バランスウェイト","subtitle":"Ferromagnetic Preload Attraction Plates & Tungsten-Copper Counterbalance","category":"S24 / 磁気予圧・重心力学設計","plainAnalogy":"カメラを真下に向けて撮ってもセンサーが重力で前に垂れ下がらないよう、裏のネオジム磁石（S21）と引っ張り合って3粒のセラミック球へ優しく押し付け続ける「見えない磁気の吸盤プレート」と、左右の重さをヤジロベエのように釣り合わせる「おもり」のセットです。","summary":"可動ステージ（S15）に配置された3枚の強磁性軟鉄プリロードプレートと、左端のタングステン-銅合金バランスウェイト。固定側N52磁石との磁気吸引力で常に一定のZ軸予圧を与え、あらゆるカメラ姿勢で焦点面を維持する。","opticsAndPhysics":["磁気プリロード（Magnetic Preload）：コイルが右辺・下辺に非対称配置されているため、軟磁性鋼板（SPCC等）を対向配置することで固定側N52ネオジム磁石との間に安定した法線吸引力 F_preload を生み出す。これにより可動ステージが常に3個のセラミック球へ確実に押し付けられ、カメラを下向き・上向き・縦位置に傾けても焦点面のZ軸ガタ（片ボケ）がゼロになる。","非接触予圧の優位性：機械的な引張バネで押し付けるとXY方向へ動かした際にバネの横復元力（外乱）が発生するが、均一な磁気吸引力なら平面移動に対する抵抗を増やさずZ方向だけを高剛性に拘束できる。","タングステン-銅（CuW）重心カウンターウェイト：右辺のX軸コイル質量と釣り合わせるため左辺に高密度CuWウェイトを配置し、ステージ全体の重心（CoG）を光学中心および3球支持三角形の中心へ一致させてロール慣性ズレを最小化。"],"formula":{"expression":"F_preload = (B² · A_plate) / (2 μ₀) > m_stage · g_shock,   CoG → (0, 0)","description":"磁気予圧が衝撃加速度下でもボール離脱を防ぎ、重心一致が姿勢変化による消費電力偏りを解消。"},"nextGenInnovation":"磁気予圧プレートの面積と板厚を3次元磁界FEM解析で最適化することで、ボイスコイルの推力磁束を奪わずかつ全可動ストローク端でも予圧が一定に保たれる洗練された磁気バランス設計が採用されている。","specs":[{"label":"吸引板材質","value":"高透磁率 強磁性軟鉄プレート × 3"},{"label":"カウンターウェイト","value":"高密度 タングステン-銅合金（CuW）"},{"label":"機能","value":"全姿勢Z軸ゼロガタ磁気予圧＋重心一致"},{"label":"横方向外乱","value":"機械バネレスにより横復元抵抗 極小"}],"diagramType":"sensor_preload_plates"},{"id":"sensor-ibis-stopper-bumper","order":25,"swatchColor":"#ef4444","groupKey":"S25_5_5mm_可動限界緩衝・落下衝撃吸収・無音エンドストッ","assembledPos":[0,0,-5.85],"explodeOffset":[34,-22,-86],"integratedExplodeOffset":[44,-28,-76.5],"edgeOpacity":0.22,"title":"IBIS 4隅プログレッシブ・エラストマー可動域ストッパー ＆ 耐衝撃バンパー群","subtitle":"4-Corner Progressive Shore-A Elastomer IBIS Travel-Limit Stoppers & Shock Bumpers","category":"S25 / ±5.5mm 可動限界緩衝・落下衝撃吸収・無音エンドストップ","plainAnalogy":"浮いているセンサーが端っこまで大きく動いたときに「コツン！」と金属同士がぶつかって壊れないよう、四隅で見守る4つの専用ゴムクッション。急な衝撃や揺れをソフトに受け止めます。","summary":"IBIS固定ベースシャーシの四隅に精密配置された、段階剛性（プログレッシブ）テーパー断面を持つ高減衰ブチル／シリコーンエラストマー製エンドストップバンパー群。±5.5mmのX/Y並進および±3°ロール可動域の終端で可動ステージをソフトに減速停止させ、落下衝撃・搬送振動・極限手ブレ時のセラミック球脱輪や金属衝突音を防ぎます。","opticsAndPhysics":["テーパー断面による非線形プログレッシブ緩衝：接触初期は先端の細いリブが柔らかくたわんで打音（動画マイクへのコツン音混入）を防ぎ、強い落下衝撃時には根元の肉厚部が急激に剛性を高めてセンサー破損を食い止めます。","高ヒステリシス減衰ゴム（高 tan δ）：通常の反発ゴムだと衝突後に跳ね返って（バウンスして）IBISサーボ制御が発振してしまいます。衝撃エネルギーを熱へ変換して跳ね返りを抑える高減衰特殊エラストマーを選定しています。","無アウトガス・無発塵グレード：センサー直近の密閉光学室内に配置されるため、長期使用でもシロキサンガス（光学面曇り原因）やゴム摩耗粉を一切放出しない光学グレード材が使用されています。"],"formula":{"expression":"F_stop(δ) = k_1 · δ + k_3 · δ³ + c_damp · δ̇   (高減衰・跳ね返りゼロのソフト終端停止)","description":"3次非線形剛性と高粘性減衰により、通常作動端の静音化と不意の落下衝撃（数十G）からのセンサー保護を両立。"},"nextGenInnovation":"動画アクティブIBISで可動ストロークが従来比2倍近くまで拡大した最新世代では、ストッパー接触直前にソフトウェア側で電子ブレーキをかける「仮想ソフトエンドストップ」と物理バンパーの協調保護が導入されています。","specs":[{"label":"配置 / 数量","value":"IBIS固定フレーム4隅 対称配置（計 4 個）"},{"label":"材質 / 硬度","value":"光学グレード無アウトガス高減衰エラストマー（Shore A 45）"},{"label":"保護ストローク","value":"X/Y ± 5.5 mm / ロール ± 3.0° 終端ハードガード"},{"label":"特徴","value":"テーパー非線形緩衝・低反発・静音動画対応"}],"diagramType":"sensor_ibis_stoppers"},{"id":"sensor-ibis-lock","order":26,"swatchColor":"#f59e0b","groupKey":"S26_機械保護・衝撃フェイルセーフ","assembledPos":[-30.5,21.5,-6.1],"explodeOffset":[-28,24,-96],"integratedExplodeOffset":[-46,34,-79.5],"edgeOpacity":0.22,"title":"電源OFF時メカニカルIBISロック機構（ソレノイド＆ロックピン）","subtitle":"Power-Off Mechanical IBIS Park-Lock Solenoid, Return Spring & Latch Arm","category":"S26 / 機械保護・衝撃フェイルセーフ","plainAnalogy":"カメラの電源を切った瞬間、宙に浮いていた手ぶれ補正ステージを「カチッ！」と中央で物理的に固定するシートベルト＆駐車ブレーキです。カバンに入れて持ち歩くときや飛行機での輸送中に、電源オフのセンサーが中でカタカタ暴れて故障するのを防ぎます。","summary":"電源OFF時に電磁制御が失われた可動IBISステージ（S15）を中央ホームポジションへ機械的にクランプ固定する、超小型ソレノイドアクチュエータ、ステンレスロックレバー、および復帰ばねから成るフェイルセーフロック機構。","opticsAndPhysics":["電源OFF時の輸送保護：IBISは電源ON時にボイスコイル電流で空中保持されるため、電源OFF時に無拘束のままだと持ち運び時の振動や落下衝撃でステージが端ストッパーへ激突し、セラミックボールやフレキ配線（S14）にダメージを与える恐れがある。","双安定ラッチ動作：電源OFFシーケンスでVCMがステージを中央原点へ位置決めした直後、小型ソレノイド（またはステッピングカム）が一瞬だけパルス通電してロックピンをステージのテーパー穴へ差し込む。一度ロックすれば通電ゼロ（消費電力0 mW）のまま機械的に保持される。","電源ON時には瞬時にソレノイドが解除され、数ミリ秒以内に8.5段アクティブ手ぶれ補正が立ち上がる。"],"formula":{"expression":"P_hold(OFF) = 0 mW (機械ラッチ),    F_clamp > m_stage · 50 G (耐衝撃保持)","description":"無通電で数十Gの持ち運び衝撃から繊細なIBIS可動部を保護する高信頼フェイルセーフ機構。"},"nextGenInnovation":"Nikon Z9 / Z8 や Canon EOS R5 II / R1 などの最新フラッグシップ機では、電源OFF時の自動IBISメカニカルロックに加え、レンズ交換時にホコリを防ぐセンサーシールドと連動することで、過酷な報道・ネイチャー現場でのタフネス性能を飛躍的に高めている。","specs":[{"label":"ロック方式","value":"無通電保持型 メカニカルテーパーピンラッチ"},{"label":"駆動アクチュエータ","value":"超小型パルスソレノイド + 復帰スプリング"},{"label":"待機消費電力","value":"0 mW（電源OFF時 完全機械保持）"},{"label":"解除応答時間","value":"電源ON時 < 15 ms で即時解放"}],"diagramType":"sensor_ibis_lock"},{"id":"sensor-n52-magnets","order":27,"swatchColor":"#3b82f6","groupKey":"S27_強磁界磁気回路設計","assembledPos":[0,0,-6.05],"explodeOffset":[0,0,-98],"integratedExplodeOffset":[0,0,-80.5],"edgeOpacity":0.22,"title":"N52 2極ネオジム永久磁石アレイ ＆ 閉磁気回路軟鉄ヨーク","subtitle":"3x Dual-Pole N52 NdFeB Permanent Magnet Arrays & Soft-Iron Back Yokes","category":"S27 / 強磁界磁気回路設計","plainAnalogy":"手ぶれ補正コイル（S16）に強力なパワーを与えるための「世界最強クラスの磁石（N52ネオジム磁石）」のペア×3組です。N極とS極をぴったり隣り合わせに並べ、裏側を鉄板（ヨーク）でつなぐことで、磁力が外へ逃げず全部コイルだけに集中する強力な磁気エンジンになっています。","summary":"固定ベース（S22）上に配置され、3基のボイスコイル（S16）へ高密度な磁束を供給する6ブロック（3ペア）の2極着磁N52ネオジム永久磁石と、高透磁率軟磁性鉄バックヨーク群。","opticsAndPhysics":["最強クラス希土類磁石（N52 Nd₂Fe₁₄B）：残留磁束密度 B_r ≈ 1.43 T、最大エネルギー積 (BH)_max ≈ 400 kJ/m³ を誇るネオジム鉄ボロン磁石を、各VCMコイルに対してN極・S極の2極ペアで精密隣接配置。コイルの往路と復路の導線に逆向きの磁束を貫通させることで、両辺のローレンツ力を同方向へ2倍加算する。","閉磁気回路（Closed Magnetic Circuit）：磁石背面に高透磁率の軟磁性鋼板バックヨークを密着させることで、磁気抵抗 R_m を大幅に低減。磁束をコイル空隙 B_gap へ極限集中させると同時に、背面のメイン基板や周辺電子部品への漏洩磁束を徹底遮蔽する。","ニッケル-銅-ニッケル3層防錆めっきにより、湿度の高い過酷環境でもネオジム合金の酸化劣化を防ぐ。"],"formula":{"expression":"B_gap = B_r · l_m / (l_m + μ_r · l_gap),    F_total = 2 · N · I · L · B_gap","description":"2極着磁ペア＋軟鉄ヨークによる閉磁気回路が、限られた薄さの中で最大のVCM推力定数を引き出す。"},"nextGenInnovation":"最新の高推力IBISでは、高温環境（8K長時間撮影時のボディ内温度上昇）でも減磁しにくい高保磁力重希土類拡散ネオジム磁石（N52H/N48SHクラス）を採用し、炎天下でも8.5段の補正性能を維持する。","specs":[{"label":"永久磁石グレード","value":"N52 / 高耐熱 ネオジム磁石 (Nd₂Fe₁₄B, ~1.43 T)"},{"label":"磁気配列","value":"2極（N/S隣接）× 3モジュール（計6磁石）"},{"label":"バックヨーク材","value":"高透磁率 軟磁性鋼板（閉磁気回路）"},{"label":"防錆表面処理","value":"Ni-Cu-Ni 3層高耐食めっき"}],"diagramType":"sensor_n52_magnets"},{"id":"ibis-base-magnets","order":28,"swatchColor":"#96a0ae","groupKey":"S28_剛性基準フレーム・振動遮断","assembledPos":[0,0,-7.4],"explodeOffset":[0,0,-109],"integratedExplodeOffset":[0,0,-86.2],"edgeOpacity":0.22,"title":"IBIS固定マグネシウム・ベースシャーシ（基準骨格フレーム）","subtitle":"Stationary Die-Cast Magnesium IBIS Base Chassis & Thermal Window","category":"S28 / 剛性基準フレーム・振動遮断","plainAnalogy":"手ぶれ補正機構全体をカメラ本体の骨格へガッチリ固定する「頑丈な土台プレート」です。強力なネオジム磁石（S21）を受け止めながら、真ん中に大きな窓を開けてあり、そこから放熱用のグラファイトシート（S25）を通してセンサーの熱を後ろへ逃がす巧みな作りになっています。","summary":"カメラ本体のマグネシウムモノコック骨格へ3点校正ボルト（S23）で締結され、N52磁石ヨーク（S21）・セラミック球レース（S18）・ロック機構（S20）すべての機械基準面となる高剛性固定ベースシャーシ。","opticsAndPhysics":["光学基準面の高剛性化：IBIS可動ステージが激しく逆加速する際、その反作用力（作用・反作用の法則）はすべてこの固定ベースシャーシへ加わる。ベースがわずかでもたわむとサーボ制御が発振してしまうため、肉厚リブ付きマグネシウムダイキャストで極めて高い曲げ剛性を確保している。","中央サーマルウィンドウ：背面の純銅ヒートシンク（S26）へΣ字型グラファイトシート（S25）を最短距離で貫通させる大型開口を設け、剛性と放熱経路を両立。","外周3箇所の校正耳（トライポッドラグ）：フランジバックとセンサー平行度をミクロン調整するための3点スプリング座面（S23）を備える。"],"formula":{"expression":"F_reaction = −F_VCM,    δ_base = F · L³ / (48 E · I) < 0.2 μm","description":"高い断面二次モーメント I とマグネシウム合金剛性により、VCM反力によるベース変形をサブミクロン以下に抑制。"},"nextGenInnovation":"最新フラッグシップ機では、シャッターユニット固定座面とIBISベース固定座面を同一のフロントマグネシウム骨格へ直接マウントすることで、光軸に対する機械公差の積み上げ（トレランススタック）を劇的に削減している。","specs":[{"label":"フレーム材質","value":"高剛性マグネシウム合金（AZ91D）ダイキャスト"},{"label":"中央放熱窓","value":"38.0 × 28.0 mm Σグラファイト貫通開口"},{"label":"取付点構成","value":"外周3点トライポッド校正座面"},{"label":"役割","value":"N52ヨーク・レース・ロック機構の剛性基準台"}],"diagramType":"magnet_yoke"},{"id":"sensor-tilt-springs","order":29,"swatchColor":"#ca8a04","groupKey":"S29_工場レーザー干渉計校正・像面平行度","assembledPos":[0,0,-7.4],"explodeOffset":[0,0,-120],"integratedExplodeOffset":[0,0,-91.8],"edgeOpacity":0.22,"title":"3点フランジバック＆像面傾き（片ボケ）ミクロン校正ばね・ねじ群","subtitle":"3-Point Micron Flange-Back & Optical Plane Tilt Calibration Springs / Bolts","category":"S29 / 工場レーザー干渉計校正・像面平行度","plainAnalogy":"レンズの取り付け面とセンサーの距離・傾きを「1ミクロン単位で完璧に水平出しする3本のバネ付き微調整ネジ」です。工場の最終検査でレーザー光線を当てながらこの3本のネジをわずかに回すことで、大口径F1.2レンズでも画面の四隅まできっちりピントが合う「片ボケゼロ」を実現します。","summary":"固定ベースシャーシ（S22）のトライポッド3頂点に配置された高剛性ヘリカル圧縮ばね・精密微調ねじ・スラスト座金群。工場出荷時にレンズマウント基準面に対するフランジバック距離と像面平行度（チルト）をミクロン精度でキャリブレーションする。","opticsAndPhysics":["3点キネマティック平面調整：平面の「Z高さ（フランジバック）」と「X傾き（Yawチルト）」「Y傾き（Pitchチルト）」の3パラメータは、3本の独立した調整ボルトで一意に調整できる。各ボルト周囲の強力なヘリカル圧縮スプリングがねじ山のバックラッシュ（遊び）を常に一方向へ押し潰す。","F1.2時代のシビアな公差：開放F1.2のレンズでは、像面がわずか10 μm（0.01 mm）傾いただけで画面左右の片側だけピントが甘くなる「片ボケ」が顕在化する。そのため組立最終工程で実写チャートまたはレーザー干渉計を用いて3本のねじをサブミクロン単位で追い込み、調整完了後に緩み止め樹脂でロックする。","背面アクセス構造：ねじ頭をカメラ背面側（-Z）へ向けているため、ボディ組立後の光学ベンチ上で精密ドライバーにより直接微調が可能。"],"formula":{"expression":"Δz_flange = (P_thread / 360°) · Δθ_bolt,   θ_tilt < ±0.005°  (片ボケ < 3 μm)","description":"細目ピッチねじ（P ≈ 0.35 mm）と予圧スプリングにより、角度1°の回転で約1 μmの超微細Z調整を実現。"},"nextGenInnovation":"近年の高画素機（50–61MP）と超大口径F1.2レンズの普及を受け、自動光学アライメントロボットがMTFをリアルタイム測定しながら3本の校正ボルトを全自動トルク・角度制御するスマート工場校正が標準化している。","specs":[{"label":"調整構成","value":"3点独立 細目ピッチ微調ボルト + 圧縮ばね"},{"label":"調整パラメータ","value":"フランジバック長 (Z) + Pitch / Yaw 平行度"},{"label":"校正精度","value":"±2–3 μm 以内（レーザー干渉計／MTF計測）"},{"label":"緩み止め","value":"工場校正完了後 低収縮UVロック樹脂封止"}],"diagramType":"sensor_tilt_springs"},{"id":"sensor-tim-pad","order":30,"swatchColor":"#60a5fa","groupKey":"S30_界面伝熱工学・接触熱抵抗低減","assembledPos":[0,0,-3.75],"explodeOffset":[0,0,-131],"integratedExplodeOffset":[0,0,-96.8],"edgeOpacity":0.22,"title":"高熱伝導シリコーン放熱界面パッド（TIMパッド）","subtitle":"High-Conductivity Compliant Silicone Thermal Interface Pad (TIM)","category":"S30 / 界面伝熱工学・接触熱抵抗低減","plainAnalogy":"発熱するセンサー基板（S13）の裏面と、熱を運ぶグラファイトシート（S25）の間の目に見えないミクロの空気のすき間を埋める「熱をめちゃくちゃよく通す、もちもちのシリコーン座布団」です。空気は熱を通しにくいため、このパッドが密着することで熱が一気に逃げるようになります。","summary":"センサーリジッド基板（S13）背面のサーマルビア直下に密着し、微細な表面凹凸や空気層による接触熱抵抗を解消してΣ字型グラファイト熱橋（S25）へ熱を効率受け渡しする高熱伝導シリコーンTIMパッド。","opticsAndPhysics":["接触熱抵抗（Contact Thermal Resistance）の克服：一見平らに見える基板や金属同士を押し当てても、ミクロに見れば95%以上は熱伝導率の極めて低い空気層（k_air ≈ 0.026 W/m·K）で隔てられている。窒化ホウ素（BN）やアルミナ微粒子を高充填した柔軟なシリコーンエラストマー（k ≈ 6–12 W/m·K）が微小凹凸へ追従充填することで接触熱抵抗を1/10以下へ激減させる。","応力吸収と電気絶縁：可動IBIS基板の微小変形や熱膨張差を吸収するクッション機能と同時に、背面のコンデンサや配線パターンと導電性グラファイトシート間の確実な電気絶縁（耐電圧 > 5 kV/mm）を担う。","低シロキサン・低アウトガス仕様：高温の8K録画時でも光学室内部のガラス面を曇らせる揮発ガスを出さないカメラ専用クリーン配合。"],"formula":{"expression":"R_TIM = (t_pad / k_TIM) + R_contact1 + R_contact2   ≪   R_air_gap","description":"熱伝導率 k ≈ 8–12 W/(m·K) の柔軟TIM層が空気断熱層を排除し、ダイ温度 ΔT を大幅に引き下げる。"},"nextGenInnovation":"8K 60p RAWや4K 120p長時間収録に対応する最新ミラーレスでは、低硬度（アスカーC < 30）で基板への反発ストレスが極めて小さく、かつ10 W/(m·K)超の高熱伝導を両立した次世代セラミックフィラーTIMシートが採用されている。","specs":[{"label":"熱伝導率","value":"約 8.0 – 12.0 W/(m·K)（セラミック高充填）"},{"label":"厚み・硬度","value":"約 1.0 – 1.1 mm / 低硬度柔軟エラストマー"},{"label":"電気特性","value":"高電気絶縁性（> 5 kV/mm）・低アウトガス"},{"label":"密着位置","value":"S13 センサー基板背面サーマルビア直下"}],"diagramType":"sensor_tim_pad"},{"id":"sigma-graphite","order":31,"swatchColor":"#334155","groupKey":"S31_異方性伝熱・フローティング放熱","assembledPos":[0,0,-7.3],"explodeOffset":[0,0,-142],"integratedExplodeOffset":[0,0,-99.2],"edgeOpacity":0.22,"title":"Σ（シグマ）字型・異方性人工グラファイトフレキシブル熱橋","subtitle":"Sigma-Folded Pyrolytic Graphite Sheet (PGS) Flexible Thermal Bridge","category":"S31 / 異方性伝熱・フローティング放熱","plainAnalogy":"手ぶれ補正で空中に浮くセンサーの熱を、動きを一切邪魔せずに後ろの放熱板へ運ぶ「Σ（シグマ）の形に折りたたまれた、銅の4倍も熱を運ぶ魔法のカーボンリボン」です。紙のようにペラペラに柔らかいため手ぶれ補正に負担をかけず、8K動画でも熱暴走を防ぎます。","summary":"IBISで空中浮上しているセンサーの発熱（S24経由）を、手ぶれ補正のサブミクロン動作を一切阻害せずに固定側純銅ヒートシンク（S26）へ高速輸送する、最新フラッグシップ特有のΣ（シグマ）字型折り畳みグラファイト熱橋。","opticsAndPhysics":["温度と暗電流（Dark Current）：シリコン半導体内部では熱励起によって光がなくても電子が発生する（暗電流）。この暗電流はセンサー温度が約6〜8℃上昇するごとに約2倍に指数増加するため、放熱性能は高感度画質と8K動画連続録画時間に直結する。","異方性人工グラファイトシート（PGS）：ポリイミドフィルムを約3,000℃で黒鉛化して結晶配向させた人工グラファイトは、面内方向の熱伝導率が 1,500〜1,700 W/(m·K) に達する（純銅 400 W/(m·K) の約4倍、アルミの約7倍）。","Σ字型フレキシブルベンド：極薄シートを独自のΣ字型に二重折り返しすることで、X・Y・Roll全方向への曲げバネ定数を極限まで低減。IBISの追従精度を一切損なわずに従来比約5倍の熱輸送能力を発揮する。"],"formula":{"expression":"I_dark(T) ∝ T^(3/2) · exp(−E_g / 2k_B T),     q = −k_∥ · A · (dT / dx)","description":"面内熱伝導率 k_∥ ≈ 1,600 W/(m·K) でセンサー温度上昇を抑え、暗電流ノイズの指数増加を食い止める。"},"nextGenInnovation":"最新世代ミラーレスで確立されたΣ字型グラファイト熱橋は、防塵防滴の完全密閉ボディ内部で「8.5段IBIS完全フローティング」と「長時間の8K/4K 120p録画」という二律背反をブレイクスルーした象徴的熱設計である。","specs":[{"label":"面内熱伝導率","value":"1,500 – 1,700 W/(m·K)（純銅の約4倍）"},{"label":"熱橋構造","value":"低剛性 Σ（シグマ）字型フレキシブルベンド"},{"label":"結晶構造","value":"高配向 sp² 炭素六角網面 人工黒鉛"},{"label":"暗電流倍増温度","value":"約 +6〜8 ℃ ごとに暗電流 2 倍"}],"diagramType":"sigma_graphite"},{"id":"sensor-heat-transfer-tapes","order":32,"swatchColor":"#4b5563","groupKey":"S32_1_II・_7R_VI系_実機分解由来・4辺筐体バイパス","assembledPos":[0,0,-8.65],"explodeOffset":[36,18,-148],"integratedExplodeOffset":[46,22,-100.5],"edgeOpacity":0.22,"title":"センサー周囲 銅箔ラミネート・グラファイト熱伝達ブリッジテープ群","subtitle":"Perimeter Copper-Graphite Laminated Thermal-Transfer Bridge Tapes (Chassis Link)","category":"S32 / α1 II・α7R VI系 実機分解由来・4辺筐体バイパス放熱路","plainAnalogy":"センサーユニットの周りを囲むように貼られた「熱を逃がす特別な黒い銅テープ」。最新カメラの実機分解でも確認されている、センサーの熱をカメラ本体のマグネシウム骨格へ広く分散させるためのヒートハイウェイです。","summary":"Sony α1 II や α7R VI 等の最新フルサイズミラーレス実機分解で明らかになった、センサーフレーム外周4辺からボディ骨格・RFシールドブラケットへ熱を逃がす銅箔＋人工グラファイト複合熱伝達テープ群。中央のΣグラファイト熱橋（S31）に加えて外周からも並列放熱することで、8K長時間収録時の局所ホットスポットを徹底解消します。","opticsAndPhysics":["並列マルチパス放熱ネットワーク：中央の純銅ヒートシンク1か所だけでは熱流束が集中して温度勾配が生じます。周囲4辺へ薄型銅-グラファイトラミネートテープを張り巡らせることで、IBIS固定枠・マウント側マグネシウム・リアシェル側へ熱抵抗を並列低減させます。","銅箔＋グラファイト＋導電粘着の3層複合構造：グラファイトの超高面内熱伝導（~1,500 W/m·K）と銅箔の厚み方向熱拡散・引裂強度を組み合わせ、さらに導電性アクリル粘着層でEMIグラウンドシールド補強も同時にこなします。","狭小ギャップへの立体追従：わずか0.15mm厚の柔軟テープが、立体的なマグネシウムリブやRFシールドの段差へ密着し、空気層（熱の絶縁体）を排除してダイレクトに熱を運びます。"],"formula":{"expression":"1 / R_th,total = 1 / R_copper_sink + Σ ( 1 / R_tape,i )   ⇒   平衡センサー温度 −4 〜 −6 ℃","description":"中央ヒートシンクと外周4辺の熱伝達テープを並列結合することで、ファンレス密閉ボディの放熱限界を大幅に底上げ。"},"nextGenInnovation":"2025–2026年世代のカメラ実機分解（Kolari Vision等）では、センサー枠全周を隙間なく覆う多重熱伝達テープとマグネシウム背面シェル内面の大型サーマルパッド連携が、連続動画記録時間を飛躍的に伸ばす決め手となっています。","specs":[{"label":"構造","value":"人工グラファイト＋電解銅箔＋導電粘着 3層ラミネート"},{"label":"総厚み","value":"約 0.15 mm（立体段差密着・EMI遮蔽兼用）"},{"label":"配置","value":"センサーベース外周4辺 ＆ RFシールド橋渡し"},{"label":"冷却効果","value":"8K/4K60p連続撮影時のセンサー平衡温度を約 4–6 ℃ 低減"}],"diagramType":"sensor_heat_tapes"},{"id":"sensor-b2b-rf-bracket","order":33,"swatchColor":"#94a3b8","groupKey":"S33_128Gbps高速ケーブル脱落防止・高周波シールド_耐衝","assembledPos":[0,0,-11.35],"explodeOffset":[-36,-16,-150],"integratedExplodeOffset":[-48,-18,-101.8],"edgeOpacity":0.22,"title":"SLVS-EC B2Bコネクタ固定クランプ板・RF EMIシールドブラケット ＆ 防振スポンジ","subtitle":"SLVS-EC B2B Retention Clamp Plate, RF EMI Shield Bracket & Shock Sponge","category":"S33 / 128Gbps高速ケーブル脱落防止・高周波シールド＆耐衝撃圧着","plainAnalogy":"センサーからメイン基板へつながる超高速データケーブルの差し込み口を、上からスポンジ付きの金属プレートでギュッと押さえてネジ止めする「抜け止め＆電波よけカバー」。カメラを落としても絶対にケーブルが抜けません。","summary":"左右のSLVS-EC v3高速フレキシブルケーブル（S17）の基板対基板（B2B）コネクタ背面を機械的に押さえ込むステンレス製クランプブラケット、高反発ウレタン緩衝スポンジ、およびRF EMI接地シールドの一体抑え板。落下衝撃によるコネクタ浮きを物理的に根絶しつつ、128Gbps級高速差動伝送路からの高周波放射ノイズを遮断します。","opticsAndPhysics":["0.35mmピッチ超狭ピッチB2Bコネクタの耐衝撃保持：高密度B2Bコネクタは嵌合高さがわずか0.6mmほどしかなく、強い落下衝撃で外れるリスクがあります。ブラケット裏のウレタン弾性スポンジが一定圧力でコネクタを押し続け、衝撃下でも接触を完全維持します。","高周波RFシールド兼サーマルブリッジ：ステンレスブラケットが複数のグランドネジでボディシャーシへ接地され、直下の16Gbps/レーン差動信号からWi-Fi/Bluetoothや音声回路への電波干渉（RFI）を遮断すると同時に、熱伝達テープの受け面としても機能します。","サービス整備性の確保：接着剤で固めるのではなく精密M1.4ネジで固定する構造により、工場調整や修理時のセンサーユニット交換を安全・確実に行えます。"],"formula":{"expression":"F_clamp = E_foam · ε · A_conn > m_plug · 500 G   (500G級衝撃でもB2Bコネクタ脱落ゼロ)","description":"弾性スポンジの予圧クランプと金属シールドの一体化により、超高帯域SLVS-EC接続の機械的・電磁的信頼性を万全化。"},"nextGenInnovation":"Sony α7R VI や α1 II 等の最新構造では、折り畳み巻き付け型のセンサーFPCコネクタを専用RFシールドブラケットで保護し、その上から熱伝達テープを橋渡しする高密度・多機能実装が採用されています。","specs":[{"label":"材質","value":"SUS304ステンレス絞り加工＋高反発緩衝スポンジパッド"},{"label":"保護対象","value":"左右 SLVS-EC v3 128Gbps 高速B2Bコネクタ群"},{"label":"EMI機能","value":"シャーシ多点GND接地によるGHz帯RF放射遮蔽"},{"label":"締結","value":"精密M1.4ステンレスビス 4点トルク管理固定"}],"diagramType":"sensor_b2b_bracket"},{"id":"sensor-copper-sink","order":34,"swatchColor":"#c86b3c","groupKey":"S34_熱拡散・筐体最終放熱ステージ","assembledPos":[0,0,-10.85],"explodeOffset":[0,0,-156],"integratedExplodeOffset":[0,0,-103.5],"edgeOpacity":0.22,"title":"背面・純銅マイクロフィンヒートシンク ＆ グラファイト拡散板","subtitle":"Stationary Pure-Copper Micro-Fin Heatsink & Chassis Thermal Spreader","category":"S34 / 熱拡散・筐体最終放熱ステージ","plainAnalogy":"Σ字のカーボンリボン（S25）が運んできた熱をドンと受け止め、背面のギザギザの銅フィンとカメラ本体全体へ一気に散らして冷ます「最終放熱ラジエーター」です。高い熱容量を持つ純銅プレートが急激な発熱ショックを吸い込み、長時間の高画質撮影を涼しく支えます。","summary":"Σ字型グラファイト熱橋（S25）の終端に熱結合され、輸送されてきたセンサー熱を面方向へ均一拡散したうえ、背面のマイクロフィン群とボディ外装マグネシウムシャーシへ放散する純銅ヒートスプレッダー。","opticsAndPhysics":["高い体積熱容量と熱伝導率：無酸素純銅（C1020, k ≈ 398 W/(m·K), ρ·c_p ≈ 3.45 MJ/(m³·K)）の厚板プレートが「サーマルマス（熱のバッファ）」として機能し、120fpsバースト連写や8K RAW開始直後の急激な温度スパイクを吸収平滑化する。","マイクロフィン放熱＆輻射冷却：背面に17条の精密マイクロフィンを設け表面積を約2.4倍に拡大。隣接するメイン基板シールドおよびマグネシウム外装フレームへ向けて対流・熱伝導・赤外線放射で熱を逃がす。","前面ラミネートグラファイト箔：Σ熱橋の接触点（ホットスポット）の熱を純銅プレート全面へ瞬時に広げることで、ヒートシンク全体の放熱効率を最大化している。"],"formula":{"expression":"Q_diss = h · A_fin · (T_sink − T_body) + ε σ A (T_sink⁴ − T_amb⁴)","description":"マイクロフィンによる表面積拡大 A_fin と高熱伝導純銅スプレッダーでセンサーユニット最終熱抵抗を極小化。"},"nextGenInnovation":"ハイブリッド静止画／動画フラッグシップ機では、この背面純銅ヒートシンクをボディのマグネシウム骨格および背面LCD裏の放熱グラファイト層へ熱結合させ、ファンレス防塵防滴のまま1時間超の4K 60p/8K連続収録を実現している。","specs":[{"label":"プレート材質","value":"無酸素純銅 C1020（k ≈ 398 W/m·K）"},{"label":"放熱フィン構造","value":"背面 17条 精密マイクロフィン（表面積 2.4×）"},{"label":"前面拡散層","value":"ラミネート人工グラファイト拡散箔"},{"label":"最終放熱先","value":"マグネシウム外装シャーシ ＆ 背面放熱経路"}],"diagramType":"sensor_copper_sink"},{"id":"sensor-wrap-fpc-bracket","order":35,"swatchColor":"#94a3b8","groupKey":"S35_5軸IBIS高速フレキ折返し保護_A1_II_A7R_V","assembledPos":[0,0,-12.2],"explodeOffset":[0,-26,-162],"integratedExplodeOffset":[0,-30,-105],"edgeOpacity":0.22,"title":"S35. センサー背面回り込みSLVS-ECフレキガイド＆SUS応力緩和ブラケット","subtitle":"Wrap-Around Fold-Over Sensor FPC Routing Guide & Stainless Stress-Relief Bracket","category":"S35 / 5軸IBIS高速フレキ折返し保護（A1 II / A7R VI構造）","plainAnalogy":"手ブレ補正で1秒間に何百回も小刻みに揺れるセンサーからメイン基板の裏側へ回り込む高速ケーブルが、折れ曲がって断線しないよう、なだらかなカーブで支える「ステンレス製のケーブル滑り台ガイド」です。","summary":"Kolari VisionのSony A1 II／A7R VI実機分解で特徴的に確認された、センサー側高速SLVS-ECフレキシブル基板がメイン基板背面下へU字折返し配線される経路を一定曲率半径（R ≥ 1.8 mm）で保持するSUS304ガイド＆応力緩和ブラケット。","opticsAndPhysics":["5軸IBISステージが最大±4.5 mm移動してもポリイミドFPC内の差動マイクロストリップ銅箔が疲労破断（金属疲労）しないよう、最小曲げ半径R ≥ 1.8 mmを保ったまま屈曲運動を分散させます。","ガイド表面には低摩擦フッ素コート／マイラー保護フィルムが貼られ、何百万回もの手ブレ補正往復動作によるフレキ表面の擦過摩耗とEMI被膜剥がれを防ぎます。"],"formula":{"expression":"ε_bend = t_Cu / (2 · R_guide) < 0.15 %  (R_guide ≥ 1.8 mm → 屈曲寿命 > 10⁷ サイクル)","description":"厳密な最小曲率ガイドにより、高速SLVS-EC差動インピーダンス維持と1,000万回超のIBIS耐屈曲性を両立。"},"nextGenInnovation":"最新世代の超高画素・高速機では、メイン基板の薄型化と引き換えにフレキを基板裏面へ回り込ませる高密度立体ルーティングが標準化しており、専用応力緩和ブラケットが長期信頼性を支えています。","specs":[{"label":"構造材質","value":"SUS304 R曲げガイドブラケット ＋ 低摩擦保護ライナー"},{"label":"最小曲率","value":"R ≥ 1.8 mm（SLVS-EC 16Gbps 差動銅箔疲労防止）"},{"label":"屈曲耐久","value":"> 1,000万回（5軸IBIS連続シフト＆ロール運動対応）"},{"label":"実機出典","value":"Sony A1 II / A7R VI センサー背面回り込みFPC構造"}],"diagramType":"sensor_wrap_fpc_bracket"},{"id":"sensor-torx-spring-cal","order":36,"swatchColor":"#2563eb","groupKey":"S36_2_m_撮像面平行度_片ボケ防止_精密校正座","assembledPos":[0,0,-8.2],"explodeOffset":[38,28,-124],"integratedExplodeOffset":[48,32,-93],"edgeOpacity":0.22,"title":"S36. 工場レーザー干渉計3点フランジバック傾き校正トルクス座＆封印樹脂","subtitle":"Factory Laser-Interferometer 3-Point Torx Flange-Back Tilt Calibration Collars & Seal","category":"S36 / ±2μm 撮像面平行度（片ボケ防止）精密校正座","plainAnalogy":"工場の出荷検査でレーザー光を当てながら「撮像面がレンズに対して髪の毛の1/30も傾いていないか（片ボケがないか）」を3本のトルクスねじで追い込み、完璧に決まった瞬間に青い封印ボンドでロックする超精密アジャスターです。","summary":"S29の3点校正スプリングポストへ組み合わされる、工場レーザー干渉計調整専用のTorx-T6微細ピッチ校正ねじカラー、摺動真鍮スラスト座金、および調整完了後の振動緩みを永久ロックする青色エポキシ封印（タンパーシール）ドット群。","opticsAndPhysics":["50mm F1.2開放撮影時の焦点深度は撮像面上でわずか約±15 μm。センサーが左右で10 μm傾くだけで画像の片側がボケる「片ボケ」が発生します。3点精密ねじ（ピッチ0.35 mm）を回転角1°（約1 μm）単位でレーザー校正し、撮像面チルト誤差を±2 μm以内へ追い込みます。","校正完了後に紫外線硬化／エポキシ封印樹脂を塗布することで、極寒地と熱帯の往復や落下衝撃でも工場校正値が狂わないよう永久固定します。"],"formula":{"expression":"Δz_cal = (p_thread / 360°) · Δθ ≈ 0.97 μm/deg   →   面平行度公差 ≤ ±2.0 μm","description":"極細ピッチ3点トルクス校正と封印樹脂により、F1.2開放・60MP超高画素時代の片ボケゼロを保証。"},"nextGenInnovation":"実機分解調査（Kolari VisionのIR改造記事等）でも「絶対にマーキングせず回してはいけない3本のスプリング付きトルクスねじ」として知られる、プロカメラ光学精度の心臓部です。","specs":[{"label":"調整方式","value":"3点レーザー干渉計校正 Torx-T6 極細ピッチ（P = 0.35 mm）"},{"label":"調整分解能","value":"約 1.0 μm / 回転1°（撮像面チルト誤差 ±2 μm以内）"},{"label":"ロック材","value":"工場校正封印用 青色高剛性エポキシ・タンパーシール"},{"label":"摺動支持","value":"低摩擦真鍮スラスト座金 ＋ 高直線性予圧コイルバネ連携"}],"diagramType":"sensor_torx_spring_cal"},{"id":"sensor-perimeter-graphite","order":37,"swatchColor":"#334155","groupKey":"S37_可動センサー直結・低剛性フレキシブル熱拡散翼","assembledPos":[0,0,-2.2],"explodeOffset":[-42,24,-46],"integratedExplodeOffset":[-48,26,-54],"edgeOpacity":0.22,"title":"S37. IBIS可動ステージ追従型・25μm極薄ペリメーターグラファイト放熱翼","subtitle":"IBIS Moving-Stage Ultra-Flexible 25µm Perimeter Pyrolytic Graphite Thermal Wings","category":"S37 / 可動センサー直結・低剛性フレキシブル熱拡散翼","plainAnalogy":"手ブレ補正で宙に浮いて動くセンサー自身に直接貼り付けられた「羽毛のように軽くて柔らかい超薄型グラファイトの羽」です。手ブレ補正の動きを邪魔せずにセンサーの熱をいち早く周囲へ逃がします。","summary":"浮遊IBIS可動ステージ（セラミックセンサー基板背面周辺）へ直結され、8.5段IBISの軽快な応答性を妨げない厚さ25 μmの超柔軟アコーディオン折り高配向グラファイト（PGS）放熱翼アセンブリ。","opticsAndPhysics":["IBIS可動部に硬い金属ヒートシンクを繋ぐとバネ定数が増加して手ブレ補正消費電力と応答遅延が悪化します。厚さ25 μmの単結晶級グラファイト箔を蛇腹折り翼とすることで、機械的反力 < 0.02 Nのままセンサー端部の熱を高速輸送します。","可動ステージ自身の面内温度ムラ（右端だけ熱くてダークノイズが偏る現象）を±0.5℃以内へ均熱化する重要な役割も担います。"],"formula":{"expression":"k_flex ∝ E · t³ (t = 25 μm で極小剛性)   ＆   k_thermal ≈ 1,650 W/m·K","description":"厚み3乗則を活かした25μm極薄設計により、IBIS負荷ゼロに保ちつつセンサー面内の温度均一性を確保。"},"nextGenInnovation":"8K60p／4K120pの長時間手持ち動画撮影では、アクティブIBIS駆動と撮像素子自身の高速ADC発熱が同時に起こるため、可動ステージ追従型グラファイト翼が画質劣化（熱かぶり）を防ぎます。","specs":[{"label":"材料厚み","value":"t = 25 μm 超柔軟・高配向熱分解グラファイト箔（PGS）"},{"label":"面内熱伝導","value":"約 1,650 W/m·K（銅の約4倍の水平熱拡散速度）"},{"label":"IBIS干渉","value":"蛇腹折り低反力構造（復元反力 < 0.02 N・8.5段追従維持）"},{"label":"効果","value":"センサー面内温度ムラ ±0.5℃以内均熱化（熱シェーディング防止）"}],"diagramType":"sensor_perimeter_graphite"},{"id":"sensor-analog-ldo-rail","order":38,"swatchColor":"#eab308","groupKey":"S38_1e_超低読出ノイズを支える直近クリーン電源","assembledPos":[0,0,-1.65],"explodeOffset":[40,-18,-32],"integratedExplodeOffset":[48,-20,-48],"edgeOpacity":0.22,"title":"S38. センサー基板直載・超低ノイズアナログLDO電源レギュレータ＆星形GNDバー","subtitle":"On-Sensor-PCB Ultra-Low-Noise Analog 2.8V/1.8V LDO Regulators & Star-Ground Rail","category":"S38 / 1e⁻超低読出ノイズを支える直近クリーン電源","plainAnalogy":"イメージセンサーのすぐ隣に置かれた「電気の超高性能浄水器（LDO）」です。メイン基板から届いた電気に含まれる微細なノイズの波を完全にろ過し、澄み切った2.8Vの電気だけを画素アンプへ届けます。","summary":"セラミックセンサー基板（S15）の背面エッジに直載実装される、PSRR > 85 dB・出力雑音密度 < 4 μV_rms の撮像素子アナログ専用超低ノイズLDOレギュレータIC群、低ESRタンタルフィルタ、およびアナログ／デジタル分離スターグラウンド銅バー。","opticsAndPhysics":["フルサイズセンサーの1電子（1 e⁻）はフローティングディフュージョン上でわずか約50〜100 μVの微小電圧変化にしかなりません。メイン基板PMICのスイッチングノイズ（数mV）がそのままセンサー電源に乗ると即座に横縞バンディングノイズが発生します。","センサーダイのわずか5 mm直下に超高PSRRのアナログ専用LDOとスターグラウンド銅バーを配置することで、ISO 51200以上の暗所でも縞ノイズゼロのクリアなシャドウ階調を生み出します。"],"formula":{"expression":"V_noise_out < 4 μV_rms,   PSRR(100 kHz) > 85 dB  →  電源起因バンディング < 0.05 e⁻","description":"撮像素子直近でのクリーンアナログ再安定化により、高ISO暗部の横縞ノイズを物理的に根絶。"},"nextGenInnovation":"グローバルシャッター機や16-bit ADC世代では、画素ピクセル電源（V_PIX）・アナログADC基準電圧（V_REF）・デジタル出力電源（V_DDIO）を完全に独立LDO系統で分離する設計が画質差を生んでいます。","specs":[{"label":"雑音密度","value":"超低出力ノイズ < 4 μV_rms（10 Hz – 100 kHz帯域）"},{"label":"電源除去比","value":"高周波 PSRR > 85 dB（PMICスイッチングリップル完全遮断）"},{"label":"分離系統","value":"V_PIX(2.8V) / V_ANA(1.8V) / V_REF 独立アナログ電源＋星形GND"},{"label":"搭載位置","value":"S15 セラミックセンサー基板直下（最短5 mm低インダクタンス配線）"}],"diagramType":"sensor_analog_ldo_rail"},{"id":"sensor-antistatic-ring","order":39,"swatchColor":"#d9a326","groupKey":"S39_静電気ダスト吸着防止・SSWF連携光学清浄環","assembledPos":[0,0,7.1],"explodeOffset":[0,32,74],"integratedExplodeOffset":[0,36,4],"edgeOpacity":0.22,"title":"S39. 撮像室前面ITO導電帯電防止ダストリペラー環＆金接地タブ","subtitle":"Front Chamber ITO Conductive Antistatic Dust-Repelling Shield Ring & Gold Ground Tab","category":"S39 / 静電気ダスト吸着防止・SSWF連携光学清浄環","plainAnalogy":"レンズ交換のときに空気中のホコリが静電気でセンサーのガラスへ吸い付かないよう、ガラスのフチから静電気をボディの金属へ常に逃がし続ける「帯電防止の金色アース枠」です。","summary":"SSWF超音波ダストリダクションガラス（S04）前面周囲に密着し、透明導電ITOコーティング層の表面電荷をボディ基準グラウンドへ常時放電する導電エラストマー＋金メッキばね接地リング。","opticsAndPhysics":["レンズ着脱や高速メカシャッター（毎秒10m/s超の羽根摺動）は撮像室内部に静電気（数百V）を発生させます。絶縁ガラス表面が帯電するとクーロン力で微細ダストが強力に張り付き、超音波振動でも落ちにくくなります。","SSWFガラス表面の透明ITO膜と外周導電リングを1 kΩ以下の低抵抗でシャーシ接地することで帯電電位を常に0 V近傍に保ち、フッ素撥水コート＋70 kHz超音波振動とのトリプル効果でホコリ付着を極小化します。"],"formula":{"expression":"F_coulomb = q · E_static → 0   (R_ITO→GND < 1 kΩ で静電時定数 τ < 1 μs 瞬時除電)","description":"透明ITO帯電防止膜を導電リングで確実接地することで、シャッター摩擦静電気によるゴミ吸着を根本防止。"},"nextGenInnovation":"電源OFF時のメカシャッター閉じ保護（ダストガード）と、帯電防止ITO接地環・フッ素コート・超音波SSWFの4段構えが現代ミラーレスの標準防塵アーキテクチャです。","specs":[{"label":"構造材質","value":"導電カーボン充填シリコーン環 ＋ 金メッキBeCu接地ばねタブ"},{"label":"放電抵抗","value":"SSWF ITO透明導電膜 → ボディシャーシ間 < 1 kΩ"},{"label":"防塵連携","value":"静電除去 × フッ素防汚コート × 70kHz超音波振動の複合防御"},{"label":"配置位置","value":"光学ローパス／SSWF前面フレーム直周（光束非干渉開口）"}],"diagramType":"sensor_antistatic_ring"},{"id":"sensor-ibis-optical-ref","order":40,"swatchColor":"#0ea5e9","groupKey":"S40_起動時光軸ゼロ点校正・ホール素子温度ドリフト補正","assembledPos":[0,0,-6.4],"explodeOffset":[-38,-28,-98],"integratedExplodeOffset":[-46,-32,-82],"edgeOpacity":0.22,"title":"S40. IBIS原点絶対位置検証用 光学フォトインタラプタ＆微細基準スリット標的","subtitle":"Secondary Optical IBIS Home-Index Photo-Interrupter & Calibration Slit Target","category":"S40 / 起動時光軸ゼロ点校正・ホール素子温度ドリフト補正","plainAnalogy":"手ブレ補正の磁気センサーは寒い日や暑い日にわずかに目盛りがズレることがあるため、電源を入れた瞬間に「ここが本当のど真ん中（光軸ゼロ点）だよ！」と光ビームで正確に確認する光学チェックポイントです。","summary":"S22の3軸ホール効果位置センサーを補完し、カメラ起動時や長時間露光（ピクセルシフトマルチ撮影）前に可動IBISステージの絶対機械原点（光軸中心）をサブミクロン精度でキャリブレーションする透過型赤外フォトインタラプタ＆ステンレス微細スリット標的。","opticsAndPhysics":["ネオジム磁石（N52）は温度が1℃上がると磁束密度が約−0.12%低下する温度係数を持つため、ホール素子だけでは低温−10℃〜高温+50℃で数ミクロンの原点オフセットが生じます。","温度ドリフトの影響を受けない光学式原点スリット通過エッジを起動時に参照することで、4〜16枚合成のピクセルシフトマルチ撮影（0.5画素＝1.8 μmステップ移動）でも完璧なサブピクセル精度を維持します。"],"formula":{"expression":"ΔB_N52 / B ≈ −0.12 %/K  →  光学原点エッジ校正で絶対位置再現性 ≤ ±0.4 μm","description":"磁気センサーの温度ドリフトを光学原点リファレンスで校正し、16枚ピクセルシフト超高解像撮影を保証。"},"nextGenInnovation":"2.4億画素（16ショット）ピクセルシフトや天体自動追尾（アストロトレーサー）など、サブミクロンの絶対位置再現性が求められる最新IBIS機能の精度基盤を担います。","specs":[{"label":"検出方式","value":"赤外LED＋高分解能フォトダイオード透過型スリットエッジ検出"},{"label":"原点精度","value":"絶対機械原点再現性 ≤ ±0.4 μm（ホール素子温度補正基準）"},{"label":"標的材質","value":"低熱膨張ステンレス・エッチング微細基準スリットフラグ"},{"label":"対応機能","value":"16枚ピクセルシフトマルチ撮影・天体追尾・起動時ゼロ点校正"}],"diagramType":"sensor_ibis_optical_ref"},{"id":"sensor-glass-retainer-plate","order":41,"swatchColor":"#334155","groupKey":"個別微細層_S41_光学フィルターを歪ませずに固定する極薄バネ枠","assembledPos":[0,0,6.55],"explodeOffset":[44,18,78],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S41. 光学フィルター押さえバネ板 IM PLATE GLASS RETAINER（SONY Ref.502: 455838602）","subtitle":"Uniform-Pressure Stainless Optical Filter Retaining Leaf-Spring Frame (Sony Ref.502)","category":"個別微細層 S41 — 光学フィルターを歪ませずに固定する極薄バネ枠","plainAnalogy":"写真立てのガラスを裏から「金属のツメ」でやさしく均等に押さえる仕組みの超精密版です。もしネジでガラスを直接ギュッと締めると、ガラスがわずかに歪んで写真がピンボケしてしまいます。この薄いバネ板が四方からふわっと同じ力で押さえることで、激しい手ブレ補正で揺れてもガラスがズレず、しかも全く歪まない状態を保ちます。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.502: 455838602 IM PLATE (5000), GLASS RETAINER）に実在する、薄いステンレス鋼製のフィルター押さえバネ枠です。センサー前に重なる光学フィルターブロック（OFB-01-187）の4辺を均一なバネ圧で保持します。","opticsAndPhysics":["ガラスを硬いネジで直接押すと内部に応力（力のかたより）が生まれ、光が二重に曲がる「光弾性複屈折」が起きて画質が落ちます。バネ板の柔らかな面接触がこれを防ぎます。","手ブレ補正（IBIS）が最大数Gの加速度でセンサーを素早く揺らしても、フィルターが1μm（1000分の1mm）もカタつかない適度な押さえ力（約4〜6N）を維持します。","表面は黒色酸化処理（つや消し黒）されており、レンズから斜めに入ってきた余計な光が枠に反射して写真に白いモヤ（フレア）が出るのを防ぎます。"],"formula":{"expression":"F_clamp = k_leaf · δ_pre ≈ 4.5 N  (Δn_stress < 10⁻⁶)","description":"バネ板の押し付け力（約4.5N）。ガラスをガッチリ固定しつつ、光の歪み（屈折率変化）は100万分の1以下に抑えます。"},"nextGenInnovation":"α7R Vやα1 IIなどの8.5段手ブレ補正機では、激しいセンサー移動でも共振（ビビり）が起きないよう、バネ板の角に段差ビード（補強の溝）を入れた高剛性プロファイルへ進化しています。","specs":[{"label":"Sony純正品番","value":"Ref.502 / 455838602 (IM PLATE GLASS RETAINER)"},{"label":"材質・板厚","value":"SUS301-CSP ばね用ステンレス / t = 0.25 mm"},{"label":"表面処理","value":"低反射つや消し黒色化学発色（反射率 < 2%）"},{"label":"固定方式","value":"4辺均一バネ押圧＋精密爪係合（非接着交換対応）"}],"diagramType":"sensor_glass_retainer_plate"},{"id":"sensor-im-mask-plate","order":42,"swatchColor":"#0f172a","groupKey":"個別微細層_S42_画面のフチからの迷光を絶つ極薄黒マスク","assembledPos":[0,0,5.45],"explodeOffset":[-44,16,66],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S42. 撮像室・超薄黒色遮光マスク板 IM MASK PLATE（SONY Ref.503: 457543001）","subtitle":"Ultra-Thin Matte-Black Optical Aperture Baffle Mask Plate (Sony Ref.503)","category":"個別微細層 S42 — 画面のフチからの迷光を絶つ極薄黒マスク","plainAnalogy":"映画館のスクリーンの周りが真っ黒なカーテンで縁取られているのと同じ役割です。レンズから入った光のうち、写真の枠（36×24mm）の外側に当たった不要な光は、ガラスのフチで跳ね返って写真に「謎の赤いスジや白っぽいカブリ」を作ってしまいます。この極薄の真っ黒な額縁が、余計な光をピシャリと遮断します。","summary":"Sony ILCE-7M4 サービスマニュアル（Ref.503: 457543001 IM MASK PLATE (5100)）に明記された、光学フィルターブロックの直前に重ねる極薄の遮光額縁プレートです。有効撮像領域の外周に飛ぶ迷光（ゴーストの原因）をカットします。","opticsAndPhysics":["フィルターガラスの切断面（端面）に強い逆光が当たると、ガラス内部を光が反射しながら横走りして「端面ゴースト」が出ます。マスク板がガラスの端面をきっちり隠します。","開口のフチ（エッジ）を極限まで薄く（約0.12mm）仕上げることで、フチ自体が光を跳ね返す「エッジ回折・反射」を極小に抑えています。","光学濃度 OD > 5.0（光を10万分の1以下に遮断）のつや消し黒樹脂/金属ラミネートで、太陽が画面ギリギリにあってもコントラストを守ります。"],"formula":{"expression":"T_mask = 10^(−OD) < 10⁻⁵  (可視・近赤外 400–1000 nm)","description":"マスク板を通り抜ける光の割合は10万分の1以下。画面のフチからの光漏れをほぼ完全にシャットアウトします。"},"nextGenInnovation":"広角大口径レンズ（F1.2〜F1.4）ほど光が斜めからセンサーのフチに当たりやすいため、最新機ではマスク開口の内壁に微細なギザギザ（マイクロマット処理）を施して反射を吸収します。","specs":[{"label":"Sony純正品番","value":"Ref.503 / 457543001 (IM MASK PLATE 5100)"},{"label":"有効開口窓","value":"36.4 × 24.4 mm（フルサイズ有効域を厳密規定）"},{"label":"板厚・遮光性","value":"t ≈ 0.12 mm / 光学濃度 OD > 5.0"},{"label":"役割","value":"フィルター端面反射・斜入射迷光（フレア）の根絶"}],"diagramType":"sensor_im_mask_plate"},{"id":"sensor-dust-catcher-tape","order":43,"swatchColor":"#f59e0b","groupKey":"個別微細層_S43_ふるい落としたホコリを閉じ込める粘着ゴミ箱","assembledPos":[0,-17.2,6.5],"explodeOffset":[-32,-32,72],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S43. 超音波落下ホコリ捕獲・粘着ダストキャッチャーシート（SSWF下部トラップ帯）","subtitle":"Non-Outgassing Silicone Adhesive Dust-Trap Strip Below SSWF Chamber","category":"個別微細層 S43 — ふるい落としたホコリを閉じ込める粘着ゴミ箱","plainAnalogy":"掃除機の「ダストボックス」や「ゴキブリホイホイ（粘着シート）」と全く同じです！超音波クリーニングでセンサー表面からホコリをブルブル震わせて振り落としても、受け皿がなければホコリがカメラの中を舞い戻ってまたセンサーにくっついてしまいます。下のスキマに貼られた粘着シートが、落ちたホコリを二度と放さないようペタッと捕まえます。","summary":"超音波ダストリダクション（SSWF）やアンチダスト振動で振り落とされた微細なゴミ・チリ・シャッター摩耗粉を重力方向（下側）で永久捕獲する、低アウトガス型の専用粘着ダストトラップシートです。","opticsAndPhysics":["超音波振動がゴミを弾き飛ばす加速度は数千Gに達し、表面の静電気を振り切ったゴミは下側のダストトラップ帯へ落下して粘着層に固定されます。","普通のセロハンテープでは接着剤からガス（揮発成分）が出てセンサーのガラスが白く曇ってしまいます。カメラ用は10年以上ガスを出さず粘着力を保つ特殊アクリル/シリコーンゲルを使用します。","カメラを縦位置・逆さまにしても、一度くっついた5〜50μmのホコリが再浮遊しない高いタック力（初期粘着力）を持ちます。"],"formula":{"expression":"F_adhesion(trap) ≫ m_dust · a_shock  (再飛散率 < 0.1%)","description":"粘着シートがゴミを掴む力は、カメラを振ったときの衝撃より圧倒的に強く、一度捕まえたホコリを逃がしません。"},"nextGenInnovation":"最新世代では、帯電防止コーティング＋超音波振動＋電源OFF時シャッター閉鎖＋下部粘着ダストキャッチャーの「4段構え」で、レンズ交換時のゴミ写り込みを劇的に減らしています。","specs":[{"label":"配置位置","value":"撮像室最下部（SSWF振動ガラス直下の重力落下帯）"},{"label":"粘着材","value":"無揮発（低アウトガス）光学グレード・シリコーンゲル"},{"label":"捕獲粒径","value":"3 μm 〜 200 μm（花粉・繊維・シャッター摩耗粉）"},{"label":"耐久寿命","value":"10年以上（乾燥硬化・ガス曇りゼロ設計）"}],"diagramType":"sensor_dust_catcher_tape"},{"id":"sensor-optical-cement-layers","order":44,"swatchColor":"#38bdf8","groupKey":"個別微細層_S44_ガラス同士の反射を消す透明な光学ノリ","assembledPos":[0,0,4.1],"explodeOffset":[46,-14,46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S44. 光学フィルター積層・屈折率整合UV光学接着層（OCA / 光学セメント 3層膜）","subtitle":"Index-Matched UV-Curable Optical Cement Adhesive Layers (n ≈ 1.52, 3x Inter-Glass Bonds)","category":"個別微細層 S44 — ガラス同士の反射を消す透明な光学ノリ","plainAnalogy":"窓ガラスを3枚ただ重ねただけだと、ガラスとガラスの間の「空気のスキマ」で光が何度も鏡のように反射して、夜景の街灯のまわりに幽霊のような光の玉（ゴースト）が何重にも写ってしまいます。この「ガラスと全く同じ光の曲がり方をする透明なノリ」で隙間なく貼り合わせることで、3枚のガラスを「光の通り道としては1枚のガラス」に変えてしまいます。","summary":"センサー前の光学フィルターブロック（OFB-01-187）を構成する水晶ローパスフィルター・1/4波長板・赤外線カットガラスの境界面を隙間なく接合する、屈折率整合型（n ≈ 1.52）のUV硬化光学セメント（OCA）層です。","opticsAndPhysics":["光は「屈折率（光の進みにくさ）」が急変する境目で反射します。ガラス（n≈1.52）と空気（n=1.00）の境目では約4%反射しますが、間に n≈1.52 の光学セメントを挟むと境目反射が 0.01% 未満まで消滅します。","厚さはわずか約15〜25μm（ラップフィルム並み）に均一塗布し、真空脱泡でミクロの気泡を完全に抜いてから紫外線（UV）を当てて硬化させます。","夏場の炎天下（+60℃）から雪山（-20℃）までガラス同士の伸び縮みの差を吸収し、剥離や白濁を防ぎます。"],"formula":{"expression":"R = [(n₁ − n_cem) / (n₁ + n_cem)]² ≈ 0.00001  (n₁ ≈ n_cem ≈ 1.52)","description":"ガラスと接着剤の屈折率（n）をピタリと揃えると、引き算がゼロに近づき、境目の反射（ゴースト）がほぼ消えます。"},"nextGenInnovation":"最新の高画素フルサイズ機では、フィルター全体の厚みを約1.8〜2.0mmに抑えつつ（周辺画質向上のため）紫外線でも黄変しないフッ素変性アクリル系光学セメントが採用されています。","specs":[{"label":"屈折率整合","value":"n_d = 1.515 〜 1.525（水晶・青板ガラスに一致）"},{"label":"塗布膜厚","value":"約 18 μm × 3界面（気泡・異物ゼロの真空貼合）"},{"label":"透過率","value":"> 99.8%（400〜700 nm 可視光全域）"},{"label":"硬化方式","value":"UV紫外線硬化＋低温熱ポストベーク（低収縮）"}],"diagramType":"sensor_optical_cement_layers"},{"id":"sensor-filter-spacer-sheet","order":45,"swatchColor":"#475569","groupKey":"個別微細層_S45_フィルターとセンサーの距離と気密を守る枠","assembledPos":[0,0,2.65],"explodeOffset":[-46,-16,30],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S45. フィルター〜カバーガラス間・防塵ギャップスペーサー SHEET SPACER（SONY Ref.505: 457676103）","subtitle":"Micron-Tolerance Dust-Sealing Optical Gap Spacer Sheet (Sony Ref.505)","category":"個別微細層 S45 — フィルターとセンサーの距離と気密を守る枠","plainAnalogy":"窓ガラスの「二重サッシの枠」のような部品です。外側のフィルターガラスとセンサーのカバーガラスの間を、決まった隙間だけ空けつつ周囲をグルッと密閉します。隙間をピッタリ空けることで、たとえフィルター表面に小さなホコリがついてもボケて写真に写りにくくなり、さらに「ガラスとガラスの間（掃除できない場所）」にゴミが絶対入らないように守ります。","summary":"Sony ILCE-7M4 サービスマニュアル（Ref.505: 457676103 SHEET (5100), SPACER）に実在する、光学フィルターブロック（OFB-01-187）とセンサーパッケージのカバーガラスを精密間隔で密閉隔離する防塵スペーサー枠シートです。","opticsAndPhysics":["フィルター前面から撮像面までの光学距離を設計値通りに保つことで、センサー表面のゴミの影をぼかし（デフォーカス効果）、F8〜F11でもゴミが目立ちにくくなります。","光学フィルターとカバーガラスの隙間はユーザーがブロワーでも掃除できない「聖域」のため、このスペーサーシートが360度ぐるりとホコリの侵入を遮断します。","厚みの誤差が数μmあるだけでレンズのピント位置（フランジバック光学長）が変わるため、極めて平坦な精密フィルムを打ち抜いて作られます。"],"formula":{"expression":"d_blur ≈ D_gap / (n · N_f)  (隙間が大きいほどゴミの影がボケる)","description":"フィルターとセンサーの隙間（D_gap）を適正に保つことで、絞り値 N_f に対してホコリの影を薄くぼかせます。"},"nextGenInnovation":"近年の高画素機ではフィルター厚を薄くして周辺部の色収差・非点収差を減らす設計が進んでおり、スペーサーシートにも±10μm以下の厚み管理と通気防塵フィルター機構が求められます。","specs":[{"label":"Sony純正品番","value":"Ref.505 / 457676103 (SHEET 5100, SPACER)"},{"label":"役割","value":"フィルター〜カバーガラス間の気密防塵＋光学距離規定"},{"label":"厚み精度","value":"t ≈ 0.35 mm（公差 ±0.01 mm）"},{"label":"構造","value":"遮光PET/発泡エラストマー積層・全周密閉リング"}],"diagramType":"sensor_filter_spacer_sheet"},{"id":"sensor-piezo-drive-fpc","order":46,"swatchColor":"#ea580c","groupKey":"個別微細層_S46_超音波ゴミ落とし専用の独立電源リボン","assembledPos":[15.5,-14.2,6.4],"explodeOffset":[34,-32,64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S46. 超音波PZT圧電バー専用・高電圧フレキシブル給電リボン＆半田ランド","subtitle":"Dedicated High-Voltage AC Piezoelectric Ultrasonic Drive Flex Ribbon","category":"個別微細層 S46 — 超音波ゴミ落とし専用の独立電源リボン","plainAnalogy":"超音波ゴミ落とし装置（PZT圧電バー）は、普通の電池の数十倍（30〜60ボルト）という強い電気を1秒間に数万回もオン・オフしてガラスを震わせます。もしこの電線を「写真データを送る繊細な電線」と一緒に束ねたらノイズだらけになってしまいます。だから専用の細いオレンジのリボンケーブル1本に独立させて、遠くの電源回路から直接つないでいます。","summary":"センサー前面の超音波ダストリダクション用PZT圧電セラミックバー（S04）へ、30〜70 kHz・数十Vppの高周波交流駆動電圧を独立供給する専用の2極フレキシブル配線リボンです。","opticsAndPhysics":["圧電セラミックに交流電圧をかけると「逆圧電効果」でセラミックが伸び縮みし、ガラス板に定在波（たわみ振動）を起こします。専用リボンが共振周波数に追従した電力をロスなく届けます。","リボン自体も非常に柔らかく軽量（ポリイミド厚25μm）に作られており、超音波振動や5軸IBISの動きを邪魔せず、数万回の振動でも金属疲労で断線しません。","センサーの超微弱なアナログ信号線（SLVS-EC）とは完全に別ルートで引き回すことで、高電圧パルスによる電磁ノイズ飛び込みを防止します。"],"formula":{"expression":"P_drive = π · f_res · C_pzt · V_pp² · tan δ  (f ≈ 50 kHz)","description":"超音波クリーニング1回あたりの消費電力。電圧は高いものの時間が短く、バッテリー消費はほんのわずかです。"},"nextGenInnovation":"最新世代では、圧電バーの電極へ直接導電性接着剤または低温半田で接合し、IBISの激しい振動下でも接続ランドが剥がれない曲線応力緩和（ミアンダ）パターンを採用しています。","specs":[{"label":"駆動信号","value":"高周波正弦波 / 矩形波 30〜60 Vpp（30〜70 kHz）"},{"label":"配線構成","value":"2極独立（駆動HOT / 基準GND）＋絶縁カバーレイ"},{"label":"基材・導体","value":"25 μmポリイミド ＋ 12 μm圧延銅箔（耐屈曲仕様）"},{"label":"分離目的","value":"撮像アナログ信号線への高電圧ノイズ混入を完全遮断"}],"diagramType":"sensor_piezo_drive_fpc"},{"id":"sensor-hermetic-frit-n2","order":47,"swatchColor":"#06b6d4","groupKey":"個別微細層_S47_真冬でもセンサーが曇らない気密シール_窒素ガ","assembledPos":[0,0,1.52],"explodeOffset":[46,22,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S47. カバーガラス気密低融点ガラスフリット封止環＆乾燥窒素（N₂）封入キャビティ","subtitle":"Hermetic Low-Temp Glass-Frit / Epoxy Seal Ring & Dry-Nitrogen (N₂) Cavity Fill","category":"個別微細層 S47 — 真冬でもセンサーが曇らない気密シール＆窒素ガス","plainAnalogy":"冬の寒い日にメガネをかけて温かい部屋に入ると、レンズが一瞬で真っ白に曇りますよね？もしカメラの心臓部（CMOSチップ）の表面が結露したら大惨事です！そこで、セラミック容器と透明なカバーガラスのフチを「溶かしたガラスの糊（フリット）」で缶詰のように完全密閉し、中に「湿気ゼロの乾燥した窒素ガス」を詰めて、極寒でも絶対に曇らないようにしています。","summary":"セラミックパッケージ（S14）と低α線カバーガラス（S08）の間を全周気密封止する封止環と、内部の密閉中空キャビティに封入された超乾燥窒素ガス（Dry N₂）空間です。","opticsAndPhysics":["工場のクリーンルーム（湿度数％以下のドライボックス内）でカバーガラスを封着するため、内部の露点（結露が始まる温度）は−50℃以下。−20℃の極寒撮影でも内部結露しません。","酸素や水分をシャットアウトすることで、チップ表面の超微細な有機カラーフィルター（RGB色素）やマイクロレンズが10年以上経っても酸化・劣化・カビ発生しません。","熱膨張率をガラス・セラミックに精密一致させた封止樹脂/ガラスフリットを使うことで、温度変化によるカバーガラスの歪みや剥離を防ぎます。"],"formula":{"expression":"T_dew < −50 °C  (RH_cavity < 0.5% @ 25 °C)","description":"密閉室内の露点温度はマイナス50℃以下。カメラが凍るような真冬でもセンサー表面は絶対に曇りません。"},"nextGenInnovation":"高発熱な8K動画・120fps高速センサーでは、チップの熱膨張サイクル（−20℃〜+85℃）を数千回繰り返してもヘリウムリーク試験に合格する超高気密ハイブリッド封止が使われます。","specs":[{"label":"封入ガス","value":"超高純度 乾燥窒素（Dry N₂ / 水分量 < 100 ppm）"},{"label":"封止方式","value":"コバール環 / 低融点ガラスフリット・光学エポキシ全周気密封止"},{"label":"防曇性能","value":"露点 −50℃以下（寒冷地・急激な温度変化対応）"},{"label":"保護対象","value":"有機カラーフィルター・マイクロレンズ・Auワイヤー酸化防止"}],"diagramType":"sensor_hermetic_frit_n2"},{"id":"sensor-ob-shield-border","order":48,"swatchColor":"#1e293b","groupKey":"個別微細層_S48_完全な黒_を毎回測るセンサー外周の遮光基準帯","assembledPos":[0,0,1.06],"explodeOffset":[-46,22,10],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S48. 撮像ダイ外周・オプティカルブラック（OB）完全遮光基準ピクセル帯","subtitle":"Perimeter Metal-Shielded Optical Black (OB) Dark-Level Reference Pixel Border","category":"個別微細層 S48 — 「完全な黒」を毎回測るセンサー外周の遮光基準帯","plainAnalogy":"料理のデジタルはかりで「お皿を乗せてから０（ゼロ）ボタン（風袋引き）」を押しますよね？センサーは温度が上がると光がなくても勝手に電気（暗電流＝お皿の重さ）が少し溜まってしまい、真っ暗なはずの夜空が白っぽく浮いてしまいます。そこでセンサーのフチに「わざと金属のフタで真っ暗にした基準の画素」をぐるっと並べて、シャッターを切るたび「今の真っ黒はこれくらい！」と自動計測して引き算しています。","summary":"フルサイズCMOSシリコンダイの有効撮像領域（35.9×24.0mm）のすぐ外周を取り囲む、不透明なタングステン／アルミ遮光膜で完全に光を遮った「オプティカルブラック（OB）画素」ゾーンです。","opticsAndPhysics":["OB画素にはレンズからの光が一切届かないため、「その瞬間のチップ温度による暗電流」と「読み出し回路のオフセット電圧」だけを純粋に測定できます。","行ごと（水平OB）と列ごと（垂直OB）に配置されており、全行の横スジノイズ（バンディング）や長時間露光時の黒浮きをリアルタイムで精密に差し引きます（OBクランプ）。","カタログ上の「総画素数（例：約3,410万画素）」と「有効画素数（約3,300万画素）」の差（約110万画素分）の多くが、このOB基準帯や周辺ダミー画素です！"],"formula":{"expression":"S_clean(x,y) = S_raw(x,y) − Mean(OB_row(y)) − Offset_dark(T)","description":"生の画像信号から「真っ暗なOB画素の平均値」を毎回引き算することで、夜空や黒服がいつでも引き締まった本物の黒になります。"},"nextGenInnovation":"最新世代では、強い逆光がOB領域へ斜め漏れして「黒基準が狂う（黒沈み現象）」のを防ぐため、OB画素と有効画素の間にダミー隔離帯と二重タングステン遮光壁を設けています。","specs":[{"label":"配置領域","value":"有効撮像面（36×24mm）の上下左右外周（数百行・列分）"},{"label":"遮光膜材質","value":"不透明アルミニウム／タングステン多層遮光シールド"},{"label":"総画素との差","value":"総画素数 − 有効画素数（約100万〜200万画素分の基準帯）"},{"label":"主な機能","value":"リアルタイム黒レベル補正（OBクランプ）・横スジノイズ除去"}],"diagramType":"sensor_ob_shield_border"},{"id":"sensor-lga-solder-underfill","order":49,"swatchColor":"#cbd5e1","groupKey":"個別微細層_S49_センサーと基板を繋ぐ320個のハンダ球_耐衝","assembledPos":[0,0,-1.55],"explodeOffset":[-48,-14,-22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S49. セラミックパッケージ底面 320ピンLGA/BGAハンダボール群＆コーナー補強アンダーフィル樹脂","subtitle":"320-Pin Ceramic Package LGA/BGA Solder Interconnect Array & Corner Epoxy Underfill","category":"個別微細層 S49 — センサーと基板を繋ぐ320個のハンダ球＆耐衝撃樹脂","plainAnalogy":"センサー本体（セラミックの箱）の裏側には、ミクロの金属の粒（ハンダボール）が将棋盤のように300個以上びっしり並んでいて、これが下の緑の基板と電気＆熱をつなぐ「数百本の足」になっています。さらに四隅を丈夫な接着樹脂（アンダーフィル）で固めてあるため、カメラをうっかり落としたり手ブレ補正で激しく揺れても、ハンダの足が1本も折れないよう守られています。","summary":"12層アルミナセラミックパッケージ（S14）の底面電極とセンサーリジッド基板（S16）を電気・熱的に一括接続する320ピン級の鉛フリーLGA/BGAハンダ接合群と、4隅の耐衝撃エポキシ・コーナーボンド補強層です。","opticsAndPhysics":["中央部の広面積サーマルパッド（放熱ハンダ面）はシリコンチップの熱を基板裏側のヒートシンクへ逃がす「熱の太いパイプ」として機能します。","セラミックとガラスエポキシ基板（FR-4）は熱膨張率が違うため、四隅に低応力エポキシ樹脂（コーナーアンダーフィル）を充填し、長年の温度変化によるハンダ亀裂を防ぎます。","電源・GND・高速SLVS-EC差動ペアを最短距離（高さ0.25mm）で垂直接続することで、高周波信号の波形乱れ（インダクタンス損失）を最小化しています。"],"formula":{"expression":"L_ball ≈ 0.15 nH/pin  (極短垂直接続 → 12.5 Gbps/lane 対応)","description":"ハンダの足がわずか0.25mmと超短いため電気のブレーキ（寄生インダクタンス）がほぼゼロになり、超高速データ通信ができます。"},"nextGenInnovation":"120fps連写対応の最新積層センサー（IMX947等）では320ピン超のセラミックLGAパッケージが採用され、鉛フリーSAC305合金＋X線ボイド検査で全ピン気泡率10%未満を保証しています。","specs":[{"label":"端子数・形式","value":"約 320ピン LGA/BGA ペリフェラル配列＋中央放熱パッド"},{"label":"ハンダ合金","value":"RoHS準拠 鉛フリー SAC305（Sn-3.0Ag-0.5Cu）"},{"label":"補強構造","value":"4隅エポキシ・コーナーアンダーフィル（落下・IBIS振動耐性）"},{"label":"接続高さ","value":"スタンドオフ約 0.25 mm（極低インピーダンス接続）"}],"diagramType":"sensor_lga_solder_underfill"},{"id":"sensor-mlcc-decoupling-bank","order":50,"swatchColor":"#d97706","groupKey":"個別微細層_S50_センサー直下に並ぶ48個の超高速_電気のミニ","assembledPos":[0,0,-2.95],"explodeOffset":[46,20,-34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S50. センサー基板裏・超低ESL積層セラミックコンデンサ群（MLCC バイパス電源タンク ×48）","subtitle":"48x Ultra-Low-ESL Backside Decoupling MLCC Capacitor Bank Under CMOS Die","category":"個別微細層 S50 — センサー直下に並ぶ48個の超高速「電気のミニタンク」","plainAnalogy":"マンションの屋上にある「給水タンク」と同じ仕組みです！シャッターを切った瞬間、センサー内の数千万画素が一斉に電気をゴクッと飲み込みます。もし遠くのバッテリーから細い水道管で水を引くだけだと一瞬水圧が落ちて（電圧降下）、写真に横ジマやノイズが出てしまいます。そこでセンサーの真裏に48個もの小さな「電気タンク」をびっしり並べて、一瞬の電気不足をゼロにしています。","summary":"センサーリジッド基板（S16）の裏面、CMOSチップの直下エリアに高密度実装された48個の超小型・低ESL積層セラミックコンデンサ（MLCC：0402/0201サイズ）デカップリング群です。","opticsAndPhysics":["アナログ2.8V（画素用）・デジタル1.05V（ADC用）・I/O 1.8Vの3系統それぞれに、異なる容量（0.1μF / 1μF / 10μF）を組み合わせて広い周波数帯のノイズを吸収します。","チップの真裏に配置して配線距離を1mm以下に縮めることで、100MHz〜数GHzの超高速スイッチング電流のスパイクを瞬時に平らにします。","音響ノイズ（鳴き）や温度による容量低下が少ないX7R / C0Gグレードの高級セラミック誘電体を選別使用しています。"],"formula":{"expression":"ΔV = L_ESL · (di / dt) + ΔQ / C_bank  (< 2 mV リップル)","description":"コンデンサをセンサーのすぐ裏にたくさん並べるほど電圧のブレ（ΔV）が2ミリボルト未満に抑えられ、クリアな画質になります。"},"nextGenInnovation":"グローバルシャッター機や30〜120fps連写機では、全画素同時リセット時の瞬間電流（数アンペア級）を支えるため、3端子貫通型・超低ESLのMLCCが基板裏を埋め尽くします。","specs":[{"label":"実装個数","value":"48個超（CMOSダイ直下キャビティ高密度配置）"},{"label":"部品サイズ","value":"EIA 0201（0.6×0.3mm）＆ 0402（1.0×0.5mm）MLCC"},{"label":"電源系統","value":"VAA 2.8V（画素） / VDD 1.05V（ロジック） / VIO 1.8V"},{"label":"電圧安定度","value":"電源リップルノイズ < 2 mVpp（120fps同時読出時）"}],"diagramType":"sensor_mlcc_decoupling_bank"},{"id":"sensor-isl-fpc","order":51,"swatchColor":"#f97316","groupKey":"個別微細層_S51_手ブレ補正の_位置センサー専用_やわらか配線","assembledPos":[-22,2,-4.4],"explodeOffset":[-54,4,-64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S51. IBIS位置検知・ホール制御専用フレキ ISL-2009 FLEXIBLE BOARD（SONY Ref.506: 198242411）","subtitle":"Dedicated IBIS Hall-Sensor & Feedback Logic Flexible Circuit (Sony Ref.506 ISL-2009)","category":"個別微細層 S51 — 手ブレ補正の「位置センサー専用」やわらか配線","plainAnalogy":"手ブレ補正（IBIS）を動かすとき、「今センサーが何ミクロンずれたか」を測る繊細なセンサーの声を聴くための専用イヤホンケーブルです。隣にはモーターを力強く動かす大電流のケーブルが走っていますが、同じ電線に混ぜるとモーターの雑音で小さな声が聞き取れなくなります。そこでソニーは「聴く専用のISL-2009」を完全に別ケーブルに分離しています。","summary":"Sony ILCE-7M4 / ILCE-7RM4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.506: 198242411 ISL-2009 FLEXIBLE BOARD）に実在する、手ブレ補正用3軸ホール素子の微小位置信号を伝送する専用フレキシブル配線板です。","opticsAndPhysics":["ホール素子が出力する数ミリボルトの繊細なアナログ位置信号を、ボイスコイルのPWM駆動ノイズ（数アンペアの電流変化）から物理的に分離してメイン基板のIBISマイコンへ届けます。","IBISステージは1秒間に数千回も微細に動くため、屈曲の抵抗（バネ反力）が極めて小さい薄肉ポリイミド＋湾曲S字ループ形状に設計されています。","表裏に黒色のシールド保護層を持ち、シャッターやメイン基板からの外来ノイズ混入を抑えます。"],"formula":{"expression":"Δx_res = V_noise / (S_Hall · dB/dx) < 0.2 μm","description":"位置センサー専用ケーブルで雑音（V_noise）を極限まで減らすことで、髪の毛の300分の1以下の細かさでセンサー位置を把握できます。"},"nextGenInnovation":"8.5段補正（α7R V / α1 II）では、1画素（数μm）以下の超微細な位置ズレを10kHz超の高速サンプリングで読み取るため、ISL系フレキの差動ペア等長配線とノイズ遮蔽がさらに徹底されています。","specs":[{"label":"Sony純正品番","value":"Ref.506 / 198242411 (ISL-2009 FLEXIBLE BOARD)"},{"label":"担当信号","value":"3軸ホール位置フィードバック（X / Y1 / Y2）・NTC温度検知"},{"label":"分離設計","value":"大電流駆動用 ISD-2002 と完全別経路でノイズゼロ化"},{"label":"屈曲耐久","value":"1億回以上のIBIS微小変位サイクルに耐える圧延銅箔"}],"diagramType":"sensor_isl_fpc"},{"id":"sensor-isd-fpc","order":52,"swatchColor":"#c2410c","groupKey":"個別微細層_S52_手ブレ補正の_モーター駆動専用_太銅パワー配","assembledPos":[22.5,-2,-4.6],"explodeOffset":[54,4,-64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S52. IBIS大電流ボイスコイル駆動専用フレキ ISD-2002 FLEXIBLE BOARD（SONY Ref.507: 100999411）","subtitle":"Dedicated High-Current IBIS VCM Actuator Drive Flexible Circuit (Sony Ref.507 ISD-2002)","category":"個別微細層 S52 — 手ブレ補正の「モーター駆動専用」太銅パワー配線","plainAnalogy":"こちらは先ほどのISL-2009とペアになる「筋肉を動かす太いパワーケーブル」です。重たいフルサイズセンサーと金属枠を一瞬でグイッと逆方向に動かして手ブレを打ち消すには、瞬間的に大きな電気（最大1.5アンペア以上）を流す必要があります。太めの銅の道を通しつつ、センサーの滑らかな動きを妨げないようクルッと優雅なカーブを描いています。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.507: 100999411 ISD-2002 FLEXIBLE BOARD）に実在する、3軸ボイスコイルモーター（VCM）へ大電流PWM駆動電力を供給する専用パワーフレキシブル基板です。","opticsAndPhysics":["3つの独立コイル（Y1 / Y2 / X1）へ低抵抗で大電流を流すため、信号線用フレキより導体幅が太く厚い圧延銅箔を採用し、発熱と電圧ロスを抑えています。","センサー可動部と固定部を跨ぐ箇所は「ゼロテンションU字カーブ」で配線され、IBISが±3mm動いても引っ張り力（バネ荷重）がほぼ変わりません。","ISL-2009（検知側）およびSLVS-EC（画像データ側）と物理的に完全に分けることで、モーター駆動時の電流スパイクによる画質劣化を防ぎます。"],"formula":{"expression":"F_IBIS = B · I_ISD · L_coil  (I_peak ≈ 1.5 A, R_trace < 0.15 Ω)","description":"配線抵抗を0.15Ω以下に抑えてたっぷりの電流（I_ISD）をコイルへ届けることで、力強く素早い手ブレ補正パワー（F_IBIS）を生み出します。"},"nextGenInnovation":"望遠レンズや歩きの大きな揺れに対応する最新8.5段IBISでは、大きなストロークと大電流に同時に耐える多層屈曲銅フレキが採用されています。","specs":[{"label":"Sony純正品番","value":"Ref.507 / 100999411 (ISD-2002 FLEXIBLE BOARD)"},{"label":"担当電力","value":"3軸VCMコイル大電流PWM駆動（最大 1.5 A ピーク）"},{"label":"配線抵抗","value":"< 0.15 Ω（厚銅圧延箔による低発熱・高応答設計）"},{"label":"対応変位","value":"XY ±3.0 mm・ロール ±3.5°の滑らか追従ループ"}],"diagramType":"sensor_isd_fpc"},{"id":"sensor-tex-module","order":53,"swatchColor":"#64748b","groupKey":"個別微細層_S53_5軸手ブレ補正を1つにまとめる中枢ユニット骨","assembledPos":[0,0,-6.5],"explodeOffset":[0,44,-92],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S53. IBIS手ブレ補正統合モジュール骨格 TEX-5810（SONY Ref.510: A5033412A）","subtitle":"Integrated 5-Axis Anti-Shake Stator Core Module Sub-Frame (Sony Ref.510 TEX-5810)","category":"個別微細層 S53 — 5軸手ブレ補正を1つにまとめる中枢ユニット骨格","plainAnalogy":"手ブレ補正の磁石・コイル・セラミック球・ロック機構のすべてを、ミクロン単位のズレもなく1つのユニットに組み上げる「精密な時計の地板（土台）」です。ソニーα7 IVの実機では、この `TEX-5810` という独立した部品ブロックとして工場で精密に組み立て・検査されてからカメラ本体に載せられます。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.510: A5033412A TEX-5810）に実在する、5軸IBIS機構の固定側磁気枠・案内ガイド・フレキ保持爪を統合した中枢サブフレームユニットです。","opticsAndPhysics":["センサーユニット（IMAGER UNIT ASSY）とマウント骨格の間に挟まり、3つのセラミック球と強力なネオジム磁石の磁気ギャップを±15μm以内で平行維持します。","金属とガラス繊維強化樹脂（PPS/LCP）のハイブリッド構造により、軽量化しつつ強い磁力（約10N超のプリロード吸引力）で歪まない高剛性を実現しています。","周囲にISL-2009 / ISD-2002フレキのガイド溝とストッパー座面を備え、修理時にはセンサー本体と切り分けて交換できるモジュール設計です。"],"formula":{"expression":"δ_parallel < 10 μm  (全可動域 ±3 mm での像面傾き < 0.01°)","description":"センサーが端まで動いても「前後への傾き」を0.01度未満に抑えることで、画面の四隅までピントがクッキリ合います。"},"nextGenInnovation":"α7 IV世代のTEX-5810からα7R V / α1 II世代では、さらに広いロール回転角と高い固有振動数（共振しにくさ）を両立した次世代IBISモジュールへ進化しています。","specs":[{"label":"Sony純正品番","value":"Ref.510 / A5033412A (IBIS MODULE TEX-5810)"},{"label":"構成材質","value":"ダイカスト軽合金＋GF強化PPS高精度インサート骨格"},{"label":"平面平行度","value":"全ストローク域で 10 μm 以内"},{"label":"整備性","value":"撮像素子側（Ref.512）と独立交換可能なサービスユニット"}],"diagramType":"sensor_tex_module"},{"id":"sensor-imager-fix-shafts","order":54,"swatchColor":"#94a3b8","groupKey":"個別微細層_S54_一度外したら新品交換必須の超精密_芯出し柱","assembledPos":[0,0,-4.2],"explodeOffset":[-50,26,-68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S54. センサー芯出し・非再利用段付き固定ガイド軸 IM IMAGER FIX SHAFT（SONY Ref.501: 459775001 ×3本）","subtitle":"Single-Use Precision Stepped Imager-to-IBIS Alignment Shafts (Sony Ref.501, 3x)","category":"個別微細層 S54 — 一度外したら新品交換必須の超精密「芯出し柱」","plainAnalogy":"家具の組み立てで使う「木ダボ（位置決めのピン）」の究極版です！しかもソニー公式の修理マニュアルに『一度外したら絶対に再利用せず、新品に交換すること！』と赤字レベルの注意書きがあるほど超シビアな部品。わずか0.005mmのガタつきも許さず、センサー本体を手ブレ補正の可動枠にピタッと1ミリの狂いもなく固定する3本の精密ガイド柱です。","summary":"Sony ILCE-7M4 / ILCE-7RM4 サービスマニュアル（Ref.501: 459775001 IM IMAGER FIX SHAFT (5300) — Note 1: 非再利用指定）に実在する、撮像素子ユニットとIBIS可動フレームを3点位置決め締結する精密段付きガイドシャフトです。","opticsAndPhysics":["「3点支持」は幾何学的にガタつき（過拘束）が一切起きない最も理想的な平面決定法です。3本の段付き軸がセンサーの前後位置（Z）・上下左右（XY）・回転（θ）を一発で決めます。","微細な圧入・締結で表面のミクロのなじみ層が変形してガタをゼロに殺す設計のため、分解して再使用すると位置精度が落ちます（公式マニュアル非再利用指定の理由）。","高強度ステンレス鋼をセンターレス研削仕上げしており、シャッター衝撃や落下Gでもセンサーがズレません。"],"formula":{"expression":"Δθ_tilt = Δz_shaft / L_span < 0.003°  (Δz < 3 μm)","description":"3本の軸の高さ誤差を3μm以下に揃えることで、画面の右だけボケる「片ボケ」を防ぎます。"},"nextGenInnovation":"6100万画素（α7R V）やF1.2大口径レンズでは像面が数μm傾いただけで「片ボケ」が視認されるため、この3本固定軸の真円度・段差公差はサブミクロン級に厳格化されています。","specs":[{"label":"Sony純正品番","value":"Ref.501 / 459775001 (IM IMAGER FIX SHAFT 5300)"},{"label":"配置本数","value":"3本（三角形3点支持・非再利用サービス指定部品）"},{"label":"加工精度","value":"焼入れステンレス・段差高さ公差 ±3 μm"},{"label":"役割","value":"撮像素子ユニット〜IBIS可動ステージ間の無ガタ芯出し固定"}],"diagramType":"sensor_imager_fix_shafts"},{"id":"sensor-ball-retainer-cage","order":55,"swatchColor":"#e2e8f0","groupKey":"個別微細層_S55_セラミック球が迷子にならないための案内ケージ","assembledPos":[0,0,-5.7],"explodeOffset":[48,-10,-84],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S55. セラミック球脱落防止・低摩擦POMボールリテーナーケージ＆フッ素グリス溜めポケット","subtitle":"Low-Friction Acetal (POM) 3-Ball Retainer Cage Sheet & Fluorinated Grease Pockets","category":"個別微細層 S55 — セラミック球が迷子にならないための案内ケージ板","plainAnalogy":"手ブレ補正のセンサーは、3つの極小セラミック球（パチンコ玉の超ミニ版）の上を氷の上のようにスルスル滑っています。でも玉だけ挟んでおくと、カメラを振った拍子に玉が端っこへ転がって偏ったり、最悪ズレて引っかかったりしますよね？この極薄の「穴あきプレート（リテーナー）」が3つの玉をちょうどいい距離に保ち、小さなポケットに潤滑グリスを蓄えて一生スムーズに転がします。","summary":"5軸IBIS可動ステージを支える3個の窒化ケイ素（Si₃N₄）セラミックボール（S23）の相互位置と転がり軌道を規制し、衝撃時の球の偏り・脱線を防ぐ自己潤滑POM樹脂製ボールリテーナーケージです。","opticsAndPhysics":["ボールが転がるとき、ボールの中心はステージの移動量の「ちょうど半分（1/2）」だけ動きます。リテーナー板がこの1/2追従運動を3球同時に同期させ、引きずり摩擦を防ぎます。","自己潤滑性の高いポリアセタール（POM）またはPTFEコーティング薄板製で、各ポケット内周に微細なフッ素系グリス（PFPE）溜めを設けています。","フッ素グリスは揮発してセンサーガラスを曇らせる恐れがゼロ（超低蒸気圧）かつ−30℃でも固まらない航空宇宙グレードです。"],"formula":{"expression":"x_ball = ½ · x_stage  (μ_roll ≈ 0.0015 — ほぼ無摩擦)","description":"ボールはステージの半分の距離を純粋に転がるため、摩擦係数はわずか0.0015。指で触れた羽根のように軽く動きます。"},"nextGenInnovation":"最新の8.5段IBISではストローク拡大に合わせてボールポケットを楕円・円形複合形状に最適化し、高速連写時の急激な加減速でも「ボールの空転（スキッド）」を完全に抑えています。","specs":[{"label":"材質","value":"自己潤滑ポリアセタール（POM）/ PTFEコート極薄板"},{"label":"保持構造","value":"3球同期保持ポケット＋微細グリス溜め（リザーバ）"},{"label":"潤滑剤","value":"超低蒸気圧フッ素グリス（PFPE：アウトガス・曇りゼロ）"},{"label":"転がり摩擦","value":"μ ≈ 0.0015（極低ヒステリシス応答）"}],"diagramType":"sensor_ball_retainer_cage"},{"id":"sensor-vcm-coil-bobbins","order":56,"swatchColor":"#78350f","groupKey":"個別微細層_S56_細い銅線をピシッと巻いて支える耐熱ボビン枠","assembledPos":[0,0,-5.08],"explodeOffset":[50,26,-74],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S56. ボイスコイル巻線ボビン（耐熱ポリイミド枠）＆ エナメル銅線引き出しターミナル","subtitle":"High-Temp Polyimide/LCP VCM Coil Winding Formers (Bobbins) & Strain-Relieved Terminals","category":"個別微細層 S56 — 細い銅線をピシッと巻いて支える耐熱ボビン枠","plainAnalogy":"裁縫の「糸巻き（ボビン）」を想像してください！手ブレ補正のモーターは髪の毛ほどの細い銅線を何百回もグルグル巻いて作りますが、糸だけだとグニャッと崩れてしまいますし、電流で熱くなると溶けてしまいます。この耐熱プラスチックの極薄糸巻き枠が、銅線を1本も乱れずギュッと支え、端の細い線も断線しないよう金属端子でしっかり中継しています。","summary":"3軸IBIS用空芯ボイスコイル（S21）の巻線形状を高密度・平坦に保持し、極細エナメル銅線の引き出し端を半田ターミナルへ安全に中継する耐熱LCP/ポリイミド製コイルボビン枠群（×3個）です。","opticsAndPhysics":["ボイスコイルに大電流が流れると100℃近くまで発熱し、同時に急激なローレンツ力が銅線にかかります。耐熱260℃のLCP（液晶ポリマー）枠がコイルの膨らみや変形を防ぎます。","線径約0.08〜0.12mmの極細自己融着エナメル銅線を「整列巻き」にすることで、同じ体積に約15%多く銅を詰め込み、手ブレ補正パワーを底上げします。","引き出し線の根元をボビン一体の銅合金ターミナルに絡げて半田付けし、振動による「付け根の金属疲労断線」を完全に防ぎます。"],"formula":{"expression":"F_max ∝ N_turns · I · B  (整列巻き占積率 ≈ 78%)","description":"ボビンに隙間なくキレイに銅線を巻く（占積率を上げる）ほど、同じ大きさのモーターでも手ブレ補正の力が強くなります。"},"nextGenInnovation":"最新世代では、コイルの厚みを0.1mmでも薄くして磁石との隙間（エアギャップ）を狭めるため、ボビンの壁厚をわずか0.20mmまで薄肉成形しつつ剛性を保つ超流動LCPが使われます。","specs":[{"label":"数量・配置","value":"3組（Y1 / Y2 / X1 各VCM空芯コイル専用ボビン）"},{"label":"材質・耐熱","value":"超薄肉 LCP液晶ポリマー / 耐熱260℃・低反り成形"},{"label":"巻線構造","value":"自己融着ポリウレタン銅線（φ0.10mm）高密度整列巻き"},{"label":"中継端子","value":"金メッキリン青銅・耐振巻付け半田ターミナル"}],"diagramType":"sensor_vcm_coil_bobbins"},{"id":"sensor-hall-bias-magnets","order":57,"swatchColor":"#2563eb","groupKey":"個別微細層_S57_センサー位置を正確に測るための専用_磁気もの","assembledPos":[0,0,-5.4],"explodeOffset":[-44,34,-84],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S57. ホールセンサー専用・直線磁場発生サブマグネット＆磁気シールド仕切り板","subtitle":"Linear-Gradient Sensing Sub-Magnets & Permalloy Cross-Talk Flux Baffles (3x)","category":"個別微細層 S57 — センサー位置を正確に測るための専用「磁気ものさし」","plainAnalogy":"暗闇の中で手探りせず「今右に0.003mm動いた！」と知るための「磁石のものさし」です。駆動用の大きな磁石やコイルの磁気が混ざると目盛りが狂ってしまうため、位置計測専用の小さな2極磁石と、余計な磁気を遮る鉄の仕切り板（磁気シールド）をセットにして、1ミクロン以下の正確さでセンサーの現在地を読み取れるようにしています。","summary":"3軸ホール効果位置センサー（S22）に対向配置され、可動域全域で理想的な直線磁場勾配（リニア出力）を発生させる位置検出専用サブマグネット（または検出磁極帯）とパーマロイ磁気仕切り板です。","opticsAndPhysics":["ホール素子は「通過する磁力の強さ」を電圧に変えます。N極とS極を精密な間隔で隣り合わせた専用磁気ターゲットにより、変位と電圧がきれいな直線比例（リニア）になります。","周囲をパーマロイ（高透磁率合金）の磁気仕切り板で囲むことで、すぐ隣でオン・オフするVCMコイルの磁場ノイズが位置計測に混ざる「磁気クロストーク」を遮断します。","温度が上がっても磁力がほとんど弱まらないサマリウムコバルト（SmCo）系または高温安定ネオジム磁石を用い、長時間動画撮影でも手ブレ補正の基準点がズレません。"],"formula":{"expression":"V_Hall(x) = K_H · I_bias · (dB/dx) · x  (直線性誤差 < 0.2%)","description":"磁場の傾き（dB/dx）が均一なほど、電圧を見ただけでセンサーの位置（x）が誤差0.2%以内でズバリ分かります。"},"nextGenInnovation":"ピクセルシフトマルチ撮影（4枚・16枚合成）ではセンサーを「ちょうど1画素（約3.7〜5.9μm）または0.5画素」だけ完璧にズラす必要があり、この直線磁気ものさしが超高解像合成の命綱です。","specs":[{"label":"構成","value":"3軸専用2極リニア磁場ターゲット＋パーマロイ遮蔽仕切り"},{"label":"位置分解能","value":"< 0.2 μm（1画素の約1/20以下の超微細位置決め）"},{"label":"温度安定性","value":"温度係数 −0.03%/℃（長時間4K/8K撮影でのドリフト抑制）"},{"label":"活用機能","value":"8.5段IBIS・16枚ピクセルシフトマルチ撮影の基準スケール"}],"diagramType":"sensor_hall_bias_magnets"},{"id":"sensor-im-radiation-sheet-b","order":58,"swatchColor":"#1e293b","groupKey":"個別微細層_S58_センサー裏面の熱を逃がすソニー純正グラファイ","assembledPos":[0,0,-9.4],"explodeOffset":[0,38,-138],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S58. センサー背面・主放熱グラファイトシート IM RADIATION SHEET B（SONY Ref.508: 500949701）","subtitle":"Primary Rear Imager Anisotropic Graphite Radiation Sheet B (Sony Ref.508)","category":"個別微細層 S58 — センサー裏面の熱を逃がすソニー純正グラファイト放熱シートB","plainAnalogy":"4K60pの動画をずっと撮っていると、センサーは小さなカイロのように熱くなります。熱くなると写真にザラザラしたノイズ（熱ノイズ）が増えたり、カメラが熱暴走して止まってしまいます。この真っ黒な紙のように薄いシートは、実は「銅の約3倍も熱を速く運ぶ」特殊な炭素（グラファイト）製！センサーの背中にペタッと貼って熱を瞬時に横へ広げます。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.508: 500949701 IM RADIATION SHEET B (5800)）に実在する、撮像素子ユニット背面全体を覆う主放熱グラファイトシートです。","opticsAndPhysics":["人工グラファイトシート（PGS）は横方向（面内）の熱伝導率が約1,000〜1,500 W/(m·K)と純銅（400）の3倍以上！局所的なホットスポット（熱い点）を瞬時に均一化します。","表面には極薄の絶縁PETラミネートと粘着層が貼られており、センサー基板裏のコンデンサや電極に触れても絶対にショート（短絡）しません。","重さはわずか0.3g程度と羽のように軽いため、手ブレ補正（IBIS）でセンサーと一緒に動いても慣性負荷になりません。"],"formula":{"expression":"q_spread = −k_xy · t · ∇T  (k_xy ≈ 1,300 W/m·K ≈ 銅の3.2倍)","description":"紙のように薄いのに熱を横に運ぶ力（k_xy）が銅の3倍以上あり、センサー中央の熱を一気に外周へ逃がします。"},"nextGenInnovation":"α7 IVでは Ref.508（SHEET B）と Ref.509（SHEET D）、さらにΣ型グラファイト（S31）を多段連携させることで、冷却ファン無しの防塵防滴ボディで4K60p長時間録画を実現しています。","specs":[{"label":"Sony純正品番","value":"Ref.508 / 500949701 (IM RADIATION SHEET B 5800)"},{"label":"面内熱伝導率","value":"約 1,300 W/(m·K)（異方性高配向グラファイト）"},{"label":"絶縁処理","value":"両面絶縁PET保護ラミネート（耐電圧 > 1 kV）"},{"label":"質量・板厚","value":"約 0.3 g / 総厚 ≈ 0.08 mm（IBIS無負荷設計）"}],"diagramType":"sensor_im_radiation_sheet_b"},{"id":"sensor-im-radiation-sheet-d","order":59,"swatchColor":"#334155","groupKey":"個別微細層_S59_センサー側面の熱を金属骨格へ橋渡しする補助シ","assembledPos":[28.5,0,-7.8],"explodeOffset":[54,-22,-124],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S59. センサー側面・補助放熱ブリッジシート IM RADIATION SHEET D（SONY Ref.509: 503217411）","subtitle":"Secondary Side-Flank Imager Thermal Bridge Sheet D (Sony Ref.509)","category":"個別微細層 S59 — センサー側面の熱を金属骨格へ橋渡しする補助シートD","plainAnalogy":"先ほどの「シートB」がセンサーの背中に貼る大判の冷えピタだとすると、こちらの「シートD」は、センサーの横っ腹からカメラの金属ボディ骨格へと熱を受け渡す「放熱の橋渡しテープ」です。IBISで揺れても突っ張らないよう、しなやかに折り曲げて貼られています。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.509: 503217411 IM RADIATION SHEET D (5510)）に実在する、撮像素子ユニットの側面からメインフレーム側へ熱を逃がす第2の補助グラファイト放熱シートです。","opticsAndPhysics":["センサーは前後に空間があり（前面はシャッター室、背面はメイン基板）、熱の逃げ道が限られます。シートDが横方向の「第2の放熱ルート」を開通させて温度上昇を抑えます。","IBISの左右移動（±3mm）に合わせてソフトにたわむスリット入り薄型グラファイト構造で、手ブレ補正のバネ抵抗になりません。","センサー温度を5℃下げるだけでも、熱による暗電流ノイズ（ざらつき）は約半分（半減則）に減るため、高感度画質にも直結します。"],"formula":{"expression":"I_dark(T) ∝ 2^((T − T₀) / 6°C)  (6℃冷やすと暗電流ノイズ半減)","description":"センサーは6℃冷やすだけで暗所ノイズの原因（暗電流）が約半分になります。補助放熱シート1枚が夜景画質を守ります。"},"nextGenInnovation":"Kolari Visionの分解調査（α1 II / α7R V）でも、センサー周辺に合計4枚もの熱伝達テープ／放熱シートが張り巡らされていることが確認されており、現代ミラーレス熱設計の要となっています。","specs":[{"label":"Sony純正品番","value":"Ref.509 / 503217411 (IM RADIATION SHEET D 5510)"},{"label":"配置位置","value":"撮像素子ユニット側面〜メイン骨格（熱ブリッジ経路）"},{"label":"構造","value":"フレキシブル複合グラファイト＋高熱伝導アクリル粘着"},{"label":"効果","value":"連続4K動画撮影時のセンサー平衡温度を約 3〜4℃ 低減"}],"diagramType":"sensor_im_radiation_sheet_d"},{"id":"sensor-as-heat-plate-top","order":60,"swatchColor":"#0ea5e9","groupKey":"個別微細層_S60_手ブレ補正の上部から熱を逃がす3層アルミ放熱","assembledPos":[0,25.4,-6.2],"explodeOffset":[0,52,-118],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S60. IBIS上部・アルミ放熱プレート AS HEAT PLATE TOP ＆ トップグラファイトシート（SONY Ref.453/454/470）","subtitle":"Anti-Shake Top Aluminum Heat Plate (Ref.453), Graphite Sheet Top A (Ref.454) & Top Spacer (Ref.470)","category":"個別微細層 S60 — 手ブレ補正の上部から熱を逃がす3層アルミ放熱ブリッジ","plainAnalogy":"熱い空気や熱は上へ昇る性質があります。そこで手ブレ補正ユニットの「天井部分」に、アルミの板＋黒いグラファイトシート＋高さ合わせスペーサーの3点セットを載せて、センサーとIBISコイルの熱をカメラ上部（軍艦部の金属ボディ）へ吸い上げる「放熱の煙突フタ」を作っています。","summary":"Sony ILCE-7M4 サービスマニュアル「MECHA DEVICE SECTION」（Ref.453: 474824101 AS HEAT PLATE TOP / Ref.454: 500490202 MB GRAPHITE SHEET TOP A / Ref.470: 503058201 AS HEAT PLT SPACER TOP）の3点一体・上部放熱アセンブリです。","opticsAndPhysics":["アルミ放熱プレート（Ref.453）が高い熱容量（ヒートマス）で瞬間的な発熱を受け止め、上面のグラファイトシート（Ref.454）が広い面積へ素早く拡散します。","下側に挟むトップスペーサー（Ref.470）がIBIS可動ステージとの接触を防ぎつつ、一定の熱伝導ギャップを確保します。","センサー本体だけでなく、IBISの3つのボイスコイルが発するジュール熱（I²R発熱）も上方向へ逃がして連続手ブレ補正時の熱ドリフトを抑えます。"],"formula":{"expression":"R_th,top = (t_sp / k_sp + t_Al / k_Al) / A  (上面放熱経路を増設)","description":"背面だけでなく上面にも熱の逃げ道（並列の熱抵抗）を増やすことで、センサー全体の冷却スピードを大幅に高めます。"},"nextGenInnovation":"最新のα7 IV / α7 V系では、センサー〜メイン基板〜トップ骨格を立体的な3D放熱ネットワークで繋ぐことで、長時間の4K60p収録でも熱停止を大幅に遅らせています。","specs":[{"label":"Sony純正品番","value":"Ref.453 (474824101) / Ref.454 (500490202) / Ref.470 (503058201)"},{"label":"3層構成","value":"アルミ放熱板 ＋ トップグラファイトシートA ＋ ギャップスペーサー"},{"label":"配置","value":"アンチシェイク（IBIS）ユニット最上部ブリッジ"},{"label":"冷却対象","value":"CMOS撮像素子熱 ＋ 5軸IBISボイスコイル発熱"}],"diagramType":"sensor_as_heat_plate_top"},{"id":"sensor-new-truster-screws","order":61,"swatchColor":"#cbd5e1","groupKey":"個別微細層_S61_1億回の振動でも絶対に緩まない三角形の特殊小","assembledPos":[0,0,-8.4],"explodeOffset":[-52,-2,-118],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S61. センサー固定専用・緩み止め特殊小ねじ M1.7 NEW TRUSTER P2（SONY Ref.511: 398973512 ×6本）","subtitle":"Tri-Lobular Self-Locking Micro Screws M1.7×2.5 NEW TRUSTER P2 (Sony Ref.511, 6x)","category":"個別微細層 S61 — 1億回の振動でも絶対に緩まない三角形の特殊小ねじ","plainAnalogy":"普通のネジは丸い形をしていますが、カメラのセンサー周りは超音波クリーニングや手ブレ補正、シャッター衝撃で何十万回もブルブル震える過酷な場所です。このソニー純正の `NEW TRUSTER` ネジは、断面がわずかに「おにぎり型（三角形）」になっていて、締め込むとネジ山が3方向からギュッと噛み合い、振動で勝手に緩んで外れるのを防ぐ特別なネジです。","summary":"Sony ILCE-7M4 サービスマニュアル「ANTI SHAKE UNIT」（Ref.511: 398973512 SCREW (M1.7), NEW TRUSTER, P2, L = 2.5 mm）に指定された、撮像素子・IBISプレート締結用の高精度トライロビュラ（おにぎり断面）緩み止め小ねじ群です。","opticsAndPhysics":["ネジ軸の断面が真円ではなく緩やかな3角（トライロビュラ）断面になっており、相手側のめねじと3点で弾性密着して強い耐振動ロック効果を生みます。","金属の切り粉（コンタミ）が出にくい塑性転造ネジ山形状のため、センサー直近の超クリーン空間に金属粉が落ちるリスクを極小化しています。","長さわずか 2.5 mm・呼び径 M1.7 の精密小ねじで、締結トルク（約0.12 N·m）を厳密管理してフレームの歪みを防ぎます。"],"formula":{"expression":"T_prevailing > T_vib  (無接着・無ガスで振動緩みゼロ)","description":"化学接着剤を使わずに「形」だけで緩みを防ぐため、センサーガラスを曇らせるガスを一切出さずにガッチリ固定できます。"},"nextGenInnovation":"センサーユニット周辺は緩み止め接着剤（液体ロックタイト）を使うと揮発ガスでガラスが曇る危険があるため、ガスを一切出さない機械式トライロビュラネジが必須となっています。","specs":[{"label":"Sony純正品番","value":"Ref.511 / 398973512 (SCREW M1.7 NEW TRUSTER P2)"},{"label":"寸法仕様","value":"呼び径 M1.7 × 首下長さ L = 2.5 mm（6点締結）"},{"label":"緩み止め原理","value":"トライロビュラ（3葉おにぎり断面）機械式ロック"},{"label":"クリーン性","value":"無接着（ガス曇りゼロ）・低発塵転造ねじ山"}],"diagramType":"sensor_new_truster_screws"},{"id":"sensor-esd-ground-leaf","order":62,"swatchColor":"#eab308","groupKey":"個別微細層_S62_宙に浮いたセンサーの静電気を逃がす極薄アース","assembledPos":[-28,-14,-5.8],"explodeOffset":[-52,-30,-112],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S62. IBIS可動ステージ〜固定シャーシ間・極薄ベリリウム銅アース接地リーフスプリング","subtitle":"Ultra-Compliant Beryllium-Copper (CuBe2) Floating IBIS-to-Chassis ESD Ground Leaf","category":"個別微細層 S62 — 宙に浮いたセンサーの静電気を逃がす極薄アース板バネ","plainAnalogy":"5軸手ブレ補正のセンサーは、電気を通さない「セラミックの玉」の上に乗って宙に浮いています。そのままだと、シャッターが高速で擦れたりレンズ交換したときの静電気がセンサーの金属枠に溜まってしまい、写真にノイズの線が入ったり、最悪パチッと放電してチップが壊れます！この羽根のように柔らかい金色の極薄バネが、動きを一切邪魔せずに静電気だけをボディへ逃がし続けます。","summary":"絶縁体の窒化ケイ素（Si₃N₄）セラミックボールで機械的に浮遊支持されているIBIS可動ステージと、固定側マグネシウムベースシャーシを常時同電位（0V GND）に結ぶ極薄ベリリウム銅（CuBe2）接地リーフスプリングです。","opticsAndPhysics":["窒化ケイ素セラミック球は電気を通さないため、専用アース路がないと可動フレームが「電気的に浮いたアンテナ（フローティング導体）」になり、周囲の電波ノイズを拾ってしまいます。","板厚わずか 0.04 mm のS字折り曲げベリリウム銅リーフは、ばね定数が極めて低く（< 0.05 N/mm）IBISの8.5段微細制御に悪影響を与えません。","接触抵抗を数ミリオームに抑え、シャッター幕やレンズ着脱時の静電気（ESD：数kV）を即座にボディの基準グラウンドへバイパス逃がしします。"],"formula":{"expression":"R_gnd < 20 mΩ,  k_spring < 0.05 N/mm  (低抵抗 かつ 無抵抗の柔らかさ)","description":"電気はスッと通すのに、動かす力はほぼゼロという絶妙な柔らかさで、手ブレ補正と静電気対策を両立します。"},"nextGenInnovation":"高周波のSLVS-EC通信（数十Gbps）が飛び交う最新センサーでは、可動枠のインピーダンス接地を複数点で行うことでEMI放射ノイズも同時に6〜10dB低減させています。","specs":[{"label":"材質・板厚","value":"金メッキベリリウム銅（CuBe2）/ 極薄 t = 0.04 mm"},{"label":"接地抵抗","value":"< 20 mΩ（可動ステージ〜固定シャーシ常時同電位）"},{"label":"ばね反力","value":"< 0.05 N/mm（IBIS追従を妨げない超柔軟S字構造）"},{"label":"保護役割","value":"フローティング帯電防止・ESD静電破壊＆ノイズ筋対策"}],"diagramType":"sensor_esd_ground_leaf"},{"id":"sensor-dra-qr-plate","order":63,"swatchColor":"#f8fafc","groupKey":"個別微細層_S63_そのセンサー専用の_カルテ_が刻まれた工場Q","assembledPos":[18,-15.5,-11.4],"explodeOffset":[48,-32,-156],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S63. 工場個体校正QR識別プレート（Imager DRA Data 欠陥画素・感度ムラ・WB校正タグ）","subtitle":"Factory Individual Sensor Calibration 2D QR Tag Plate (Sony \\"Imager DRA Data\\")","category":"個別微細層 S63 — そのセンサー専用の「カルテ」が刻まれた工場QRタグ","plainAnalogy":"実は3,300万〜6,100万個もの画素を作ると、どんな高級センサーでも「ほんの数個だけ明るすぎたり反応が鈍い画素（ホクロみたいな個体差）」が必ず生まれます。そこで工場でセンサーを1枚ずつ精密検査し、「どこに何番目の癖があるか」を全部記録した『そのセンサー専用のカルテ』をQRコードにして貼ってあります。修理でセンサーを交換したとき、技術者がこのQRを読み込んでカメラの頭脳に覚えさせるんです！","summary":"Sony公式サービスマニュアル（ILCE-7M4 / 7RM4 / 7M3）に「Imager DRA Data Write（QR_Code_Reader）」として明記されている、撮像素子1個体ごとの欠陥画素座標・シェーディング・感度ばらつき校正データ識別用レーザー刻印QRタグプレートです。","opticsAndPhysics":["工場検査ラインで暗所・明所・複数色温度の光を使って全画素の微小な個体差（白傷・黒傷・感度ムラ・色被り）を測定し、個体固有のシリアル／DRA校正ファイルと紐付けます。","カメラ起動時、メイン基板（BIONZ XR）がこの校正データを基にリアルタイムで欠陥画素補間とシェーディング補正を行うため、ユーザーには1ドットの欠点も見えない完璧な画質になります。","高温になるセンサーユニット背面でも消えたり剥がれたりしないよう、耐溶剤ポリイミドまたはレーザーマーキングアルミプレートで刻印されています。"],"formula":{"expression":"P_corr(x,y) = G_DRA(x,y) · [P_raw(x,y) − D_DRA(x,y)]","description":"1枚1枚のセンサー専用の「癖データ（ゲインGと暗オフセットD）」で全画素を自動補正し、どの個体でも完璧な均一画質にします。"},"nextGenInnovation":"最近の積層・高画素センサーでは、像面位相差AF画素の微小な光量低下（PDAF縞）の補正係数まで個体ごとに完全データベース化し、逆光やIR領域でも跡が一切出ないよう最適化されています。","specs":[{"label":"Sony公式名称","value":"Imager DRA Data 識別QRコード（SM調整工程必須項目）"},{"label":"記録内容","value":"欠陥画素座標マップ・感度シェーディング・色温度/WB個体係数"},{"label":"プレート仕様","value":"耐熱レーザー刻印2D DataMatrix / QRコード（6×6mm）"},{"label":"運用工程","value":"センサー／SYメイン基板交換時に専用治具で読込・書込"}],"diagramType":"sensor_dra_qr_plate"},{"id":"sensor-pcb-emi-shield-can","order":64,"swatchColor":"#94a3b8","groupKey":"個別微細層_S64_センサー基板の電波ノイズを閉じ込める極薄金属","assembledPos":[0,0,-3.15],"explodeOffset":[-46,-34,-52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S64. センサー基板裏面・極薄ニッケル銀（洋白）EMIシールド缶＆導電クッション","subtitle":"Ultra-Thin Nickel-Silver Rear Sensor-PCB RF/EMI Shield Can & Conductive Gasket","category":"個別微細層 S64 — センサー基板の電波ノイズを閉じ込める極薄金属フタ","plainAnalogy":"センサー基板の裏側では、撮った写真データを1秒間に何十ギガビットもの猛スピードで送り出す回路がフル回転しています。この超高速通信は目に見えない「電波ノイズ」を出してしまい、そのままではすぐ裏にある超繊細な光センサーやWi-Fiアンテナに悪さをしてしまいます。この極薄の銀色の金属ケースが「電波の防音室」としてノイズをピタッと閉じ込めます。","summary":"センサーリジッド基板（S16）裏面の高速SLVS-ECシリアライザ／クロックPLL周辺を覆う、軽量な洋白（ニッケル銀：Cu-Ni-Zn合金）製の極薄EMIシールド缶と導電ガスケットです。","opticsAndPhysics":["ニッケル銀（洋白）は「非磁性（磁石にくっつかない）」かつ導電性が高いため、すぐ近くにあるIBISの強力なN52ネオジム磁石に引き寄せられることなく純粋に高周波電波だけを遮断できます！","板厚わずか0.15mmの超軽量絞り加工で、IBIS可動ステージの質量増加を約0.6g以下に抑えています。","周囲を導電スポンジガスケットで基板GNDへ全周密着させ、100MHz〜10GHz帯の電磁干渉（EMI）を35dB以上減衰させます。"],"formula":{"expression":"SE_dB = 20·log₁₀(E_in / E_out) > 35 dB  (μ_r ≈ 1.00 非磁性)","description":"手ブレ補正の磁石には一切くっつかない特殊な金属（非磁性）でありながら、邪魔な電波ノイズだけを約98%以上カットします。"},"nextGenInnovation":"120fps読み出しや8K RAW対応の次世代センサーでは、データ線レートが1レーンあたり12Gbps超に達するため、非磁性EMIシールド缶＋導電放熱シートの一体化設計が不可欠です。","specs":[{"label":"材質・特性","value":"洋白（ニッケル銀 C7521）/ 完全非磁性（IBIS磁場無干渉）"},{"label":"板厚・質量","value":"t = 0.15 mm / 超軽量 ≈ 0.6 g"},{"label":"遮蔽性能","value":"> 35 dB（100 MHz 〜 10 GHz SLVS-EC高調波帯）"},{"label":"接地構造","value":"基板外周GNDランド半田クリップ＋導電ガスケット密着"}],"diagramType":"sensor_pcb_emi_shield_can"},{"id":"sensor-birefringent-olpf","order":65,"swatchColor":"#38bdf8","groupKey":"個別微細層_S65_スーツの細かい縞模様の_偽色モアレ_を2枚の","assembledPos":[0,0,4.1],"explodeOffset":[-42,34,82],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S65. 2軸複屈折水晶ローパスフィルター（OLPF）＆ λ/4 位相補償デポラライザー結晶板","subtitle":"Dual-Axis Birefringent Quartz OLPF Crystal Pair & λ/4 Quarter-Wave Depolarizer Plate","category":"個別微細層 S65 — スーツの細かい縞模様の「偽色モアレ」を2枚の魔法の水晶で消す光学結晶層","plainAnalogy":"細かいチェック柄の服を撮ったとき、虹色の変なウネウネ模様（モアレ）が出ることがありますよね。この水晶板は1本の光線を「ほんの1画素分だけ2本に分身」させる不思議な性質（複屈折）を持っており、横方向・縦方向それぞれに光を優しく馴染ませてモアレを防ぎます（間に挟んだλ/4板が偏光を整えます）。","summary":"センサー前面光学スタック内部の光学ローパスフィルター（OLPF）結晶構成をミクロ分解表示。水平分離用の第1複屈折水晶板（α-Quartz）、円偏光へ戻すλ/4位相差板（Quarter-Wave Plate）、垂直分離用の第2複屈折水晶板の3枚精密積層構造です。","opticsAndPhysics":["天然／人工α水晶（SiO₂）の一軸結晶を光軸45°カットすると、入射光が常光線（o-ray）と異常光線（e-ray）へ板厚に比例した微小距離（約1画素ピッチ ≒ 3.8〜5.9 μm）だけ分離されます。","1枚目の水晶で水平分離した光は直線偏光になっているため、そのまま2枚目の垂直水晶へ入れると分離バランスが崩れます。間にλ/4波長板を挟んで円偏光へ変換することで、縦横4点へ均等に光を配分します。","高解像モデルでは第2水晶の分離方向を逆位相に打ち消す「ローパスフィルターレス／キャンセル構成」とする場合もあり、用途別に最適化されます。"],"formula":{"expression":"d_split = t_quartz · (n_e² − n_o²) / (n_e² + n_o²) ≈ 0.00588 · t_quartz  (t ≈ 0.7 mm → d ≈ 4.1 μm)","description":"水晶板の厚み t_quartz をミクロン精度で研磨管理し、画素ピッチに一致するナイキスト遮断特性を実現"},"nextGenInnovation":"極薄積層光学スタック（総厚 ~1.6 mm）と超低反射マルチコートにより、50mm F1.2開放の斜光束でも球面収差悪化を極限まで抑えています。","specs":[{"label":"結晶材質","value":"光学グレード人工 α-水晶（45°カット）"},{"label":"積層構成","value":"水平分離水晶 ＋ λ/4板 ＋ 垂直分離水晶"},{"label":"分離距離","value":"約 3.8 〜 5.9 μm（画素ピッチ整合）"},{"label":"主な役割","value":"ナイキスト限界超の偽色・モアレ抑止"}],"diagramType":"sensor_birefringent_olpf"},{"id":"sensor-cm500-dichroic-ir","order":66,"swatchColor":"#06b6d4","groupKey":"個別微細層_S66_人間の目に見えない赤外線を_吸収_反射のダブ","assembledPos":[0,0,3.05],"explodeOffset":[44,32,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S66. ハイブリッドIRカット層：青色リン酸銅吸収ガラス（CM500系）＋42層誘電体ホットミラー干渉膜","subtitle":"Dual-Mechanism IR-Cut Filter — Blue Phosphate Absorptive Glass (CM500) + 42-Layer Dichroic Coating","category":"個別微細層 S66 — 人間の目に見えない赤外線を「吸収＋反射のダブル防御」で止める青いガラス","plainAnalogy":"カメラのセンサーは人間の目には見えない「赤外線」まで写してしまうため、そのままだと黒い服が赤紫っぽく変な色になります。そこで赤外線を吸い込む「青いサングラスガラス（吸収型）」の表面に、赤外線だけを跳ね返す「42層の超薄ミラー（反射型）」を重ねた二段構えで自然な肌色を守ります。","summary":"Kolari Visionのソニーα改造分解でも詳しく解析されている、センサー前面IRカットフィルターの二層光学メカニズム。赤外線を吸収する青緑色リン酸銅系ガラス基板（CM500相当）と、急峻なカットオフ特性を生む42層TiO₂/SiO₂誘電体干渉ホットミラー膜の複合構造です。","opticsAndPhysics":["誘電体干渉膜（ホットミラー）単独だと、広角レンズやF1.2レンズの斜め光で透過波長が短波長側へシフトし、画面周辺がシアン・マゼンタに色転び（角度依存性）します。","青色リン酸銅ガラス（Cu²⁺イオン吸収型）は入射角に依存せず近赤外（700〜1100 nm）を均一に吸収するため、干渉膜と組み合わせることで「急峻な赤色再現」と「画面周辺の色転びゼロ」を両立します。","紫外線（< 400 nm）も同時にカットし、ポートレートでの肌の透明感と植物の鮮やかな緑を忠実に再現します。"],"formula":{"expression":"T_total(λ, θ) = T_dichroic(λ·cos θ) × exp(−α_Cu(λ) · t_glass / cos θ)  (700 nm超をOD>3遮断)","description":"角度依存しない吸収型ガラスと急峻な干渉膜の乗算特性により、可視光650 nmまで明るく700 nm以降を鋭く遮断"},"nextGenInnovation":"吸湿劣化しやすい従来リン酸ガラスの両面をSiO₂保護層＋光学接着（S44）で完全密閉し、高温多湿環境でも白濁しない高耐候IRカットを実現。","specs":[{"label":"吸収基板","value":"青色リン酸銅系 IR吸収ガラス（CM500級）"},{"label":"表面干渉膜","value":"42層 TiO₂ / SiO₂ 誘電体ホットミラー"},{"label":"カットオフ波長","value":"約 660〜675 nm（半値透過点）"},{"label":"出典知見","value":"Kolari Vision ソニーαフィルター解析"}],"diagramType":"sensor_cm500_dichroic_ir"},{"id":"sensor-pzt-electrode-bond","order":67,"swatchColor":"#cbd5e1","groupKey":"個別微細層_S67_毎秒7万回の超音波振動をガラスへ無駄なく伝え","assembledPos":[0,0,5.25],"explodeOffset":[-56,-26,92],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S67. 超音波ダスト除去PZT圧電素子・両面焼成銀ニッケル電極膜＆音響インピーダンス整合接着層","subtitle":"SSWF Ultrasonic PZT Piezo Dual Fired Ag-Ni Electrode Films & Acoustic Impedance-Matched Bond","category":"個別微細層 S67 — 毎秒7万回の超音波振動をガラスへ無駄なく伝える「圧電スピーカーの電極＆専用ボンド」","plainAnalogy":"センサー表面のホコリをブルブル震わせて弾き飛ばす「超音波掃除機（SSWF）」の心臓部です。高電圧をかける銀とニッケルの薄い電極シートと、振動を1ミリも逃さずカバーガラスへ伝える特別な硬質接着剤（音響整合層）によって、頑固な静電気ホコリまでスッキリ落とします。","summary":"光学フィルター枠の片端に配置されたPZT（チタン酸ジルコン酸鉛）圧電アクチュエータの上下面焼成Ag-Ni電極膜と、超音波定在波を反射ロスなく最前面光学ガラスへ伝達する高弾性音響インピーダンス整合接着層。","opticsAndPhysics":["PZT圧電セラミックの両面に焼き付けた銀ニッケル電極間へ高周波AC電圧（数十V_pp・約60〜70 kHz）を印加すると、逆圧電効果によりセラミックが毎秒7万回伸縮します。","柔らかいゴム系接着剤で貼ると超音波エネルギーが熱として吸収されてしまいます。そこでガラスとPZTの中間音響インピーダンス（Z ≈ 12〜18 MRayl）を持つ薄肉硬質エポキシ接着層（厚さ < 15 μm）で結合し、ガラス全面に強い屈曲定在波を励起します。","振動加速度は数千G〜数万Gに達し、ファンデルワールス力や静電気で張り付いたミクロン級のホコリを瞬時に剥離させます。"],"formula":{"expression":"a_dust = (2π · f_US)² · A_vib ≈ (2π × 70 kHz)² × 0.4 μm ≈ 77,000 m/s² (約 7,900 G!)","description":"わずか0.4 μmの微小振幅でも70 kHz超音波により約8,000 Gの強烈な加速度を生み出しホコリを弾き飛ばす"},"nextGenInnovation":"ソニーα最新世代の超高周波70 kHz級アンチダスト振動＋帯電防止コートの組み合わせにより、屋外レンズ交換時のゴミ付着率を大幅低減。","specs":[{"label":"駆動周波数","value":"約 60 〜 70 kHz（可聴域外の超音波）"},{"label":"電極膜","value":"両面焼成 Ag-Ni 薄膜電極（低接触抵抗）"},{"label":"接着層厚","value":"< 15 μm 高弾性音響整合接着層"},{"label":"発生加速度","value":"数千〜約 8,000 G 級（ガラス表面）"}],"diagramType":"sensor_pzt_electrode_bond"},{"id":"sensor-sus440c-ball-races","order":68,"swatchColor":"#94a3b8","groupKey":"個別微細層_S68_固いセラミック球が柔らかいマグネシウム枠を凹","assembledPos":[0,0,-6.2],"explodeOffset":[56,-34,-56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S68. 焼入れSUS440C／ジルコニア製 IBISセラミック球専用「超高硬度すべり座金（レース板×3）」","subtitle":"Hardened SUS440C / ZrO₂ IBIS Ceramic-Ball Sliding Raceway Wear-Insert Plates (3x)","category":"個別微細層 S68 — 固いセラミック球が柔らかいマグネシウム枠を凹ませない「超硬スケートリンク板」","plainAnalogy":"柔らかい木の床の上で鉄のビー玉を転がすとすぐ凹んでゴロゴロしてしまいますよね。IBISの土台は軽いマグネシウム合金なので、超高硬度のセラミック球が転がる3箇所だけに、鏡のようにピカピカに磨いた「超硬ステンレス／ジルコニアの小さなスケートリンク板」を埋め込んで、何億回動いてもツルツル滑らかに保ちます。","summary":"5軸IBIS機構の3点窒化ケイ素（Si₃N₄）セラミックボール（S20）とマグネシウム固定／可動フレームの間にインサート固定される、鏡面ラップ仕上げ焼入れマルテンサイト系ステンレス（SUS440C, HRC 60+）またはジルコニアセラミック製レースウェイ座金（3対）。","opticsAndPhysics":["マグネシウム合金は軽量ですが表面硬度が低いため、磁気プリロード（数Nの吸引力）が集中する点接触（ヘルツ接触応力 > 1 GPa）を直接受けると圧痕（ブリネリング凹み）が生じて手ブレ補正が引っ掛かります。","表面粗さ Ra < 0.02 μm の超鏡面SUS440C焼入れレース板を3点に埋め込むことで、転がり摩擦係数 μ < 0.002 を実現し、8.5段手ブレ補正のサブミクロン微動でもヒステリシスゼロの滑走を支えます。","Reddit修理事例でも有名な「IBIS分解時のセラミック球脱落」の際、この3つの円形レース座金とPOMリテーナー（S55）がボールの正確な基準平面を決定しています。"],"formula":{"expression":"σ_Hertz = (1 / π) · ∛(6 · F_pre · E*² / R_ball²) ≈ 1.1 GPa  <  σ_yield(SUS440C ≈ 1.9 GPa)","description":"点接触の極大ヘルツ応力を焼入れHRC60超レース板で安全に受け止め、生涯ブリネリングゼロを保証"},"nextGenInnovation":"サブミクロン平面度（< 1 μm）の3点レース板とピクセルシフトマルチ撮影の協調により、1画素の1/2単位（~1.9 μm）の精密センサー移動を実現。","specs":[{"label":"材質・硬度","value":"焼入れ SUS440C（HRC 60〜62）鏡面ラップ"},{"label":"配置数","value":"固定側×3 ＋ 可動側×3（キネマティック3対）"},{"label":"表面粗さ","value":"Ra < 0.02 μm（転がり摩擦 μ < 0.002）"},{"label":"耐圧痕性","value":"ヘルツ応力 1.1 GPa 連続耐久"}],"diagramType":"sensor_sus440c_ball_races"},{"id":"sensor-rear-flux-shunt","order":69,"swatchColor":"#64748b","groupKey":"個別微細層_S69_強い磁石の力をムダなく閉じ込めつつ_見えない","assembledPos":[0,0,-8.4],"explodeOffset":[-54,42,-96],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S69. IBIS可動ステージ背面・低渦電流スリット入り磁気還流シャント＆磁気シールド板","subtitle":"Moving-Stage Rear Slotted Ferromagnetic Flux-Return Shunt & Anti-Eddy-Current Shield","category":"個別微細層 S69 — 強い磁石の力をムダなく閉じ込めつつ「見えない磁気ブレーキ」を防ぐスリット鉄板","plainAnalogy":"強い磁石の近くで普通の金属板を素早く動かすと「渦電流」という目に見えない磁気ブレーキが掛かって重くなってしまいます。そこでこの薄い軟鉄シールド板に細かい切れ目（スリット）を入れて渦電流の回り道を断ち切り、磁力をセンサー基板からしっかり遮断しながらIBISを軽快に動かします。","summary":"IBIS可動ステージ（コイル側）背面に配された、微細渦電流遮断スリット付き薄肉パーマロイ／ケイ素鋼磁気シャント板。強力なN52永久磁石アレイの漏れ磁束が背面の高密度センサー基板やメイン基板へ漏れるのを防ぎ、同時に可動時の渦電流制動ロスを抑えます。","opticsAndPhysics":["8.5段もの高出力IBISでは超強力なN52ネオジム磁石を使うため、背後へ漏れた磁束がセンサー基板のインダクタや高速SLVS-EC配線へ悪影響を及ぼす恐れがあります。","高透磁率シャント板が磁力線の安全な帰り道（閉磁気回路）を作って漏れ磁束を遮断しつつ、放射状スリット加工により可動ステージ急加速時の渦電流ブレーキ力（F_eddy ∝ v）を大幅に低減します。","結果として手ブレ補正アクチュエータの位相遅れが減り、望遠レンズ装着時の微細な高周波手ブレ追従性が向上します。"],"formula":{"expression":"P_eddy ∝ (B² · f² · w_strip²) / ρ  (スリット分割で有効幅 w_strip を1/4 → 渦電流損失を1/16へ激減)","description":"スリット幅の2乗に比例する渦電流損を物理的に断ち切り、8.5段IBISの機敏な応答速度を確保"},"nextGenInnovation":"高透磁率パーマロイ薄板（0.25 mm）のフォトエッチング精密スリット加工により、重量増をわずか数グラムに抑えながら磁気シールドと軽量化を両立。","specs":[{"label":"材質・板厚","value":"高透磁率パーマロイ / ケイ素鋼 0.25 mm"},{"label":"渦電流対策","value":"放射状フォトエッチング・スリット加工"},{"label":"漏れ磁束低減","value":"背面基板側で -20 dB 以上遮蔽"},{"label":"効果","value":"高周波手ブレ応答向上＆EMI干渉防止"}],"diagramType":"sensor_rear_flux_shunt"},{"id":"sensor-cavity-breather-desiccant","order":70,"swatchColor":"#e2e8f0","groupKey":"個別微細層_S70_雪山や飛行機でもセンサーのガラス内側が曇らな","assembledPos":[0,0,2.2],"explodeOffset":[56,-42,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S70. センサー光学室・極小撥水ePTFE気圧調整ベント＆内部防曇マイクロ乾燥剤ストリップ","subtitle":"Sensor Optical-Cavity Hydrophobic ePTFE Barometric Breather Vent & Micro-Desiccant Strip","category":"個別微細層 S70 — 雪山や飛行機でもセンサーのガラス内側が曇らない「呼吸シート＆ミニ乾燥剤」","plainAnalogy":"冬に寒い外から暖かい部屋へ入るとメガネが真っ白に曇りますよね。センサーのガラスの内側が曇ったら拭くこともできません！そこで光学室の隅に「空気だけ通して水とホコリは通さない極小の呼吸シート」と「湿気を吸い取るミニ乾燥剤」を仕込み、標高3,000mの雪山でも絶対に結露させません。","summary":"センサーカバーガラス（S08）〜前面フィルター枠（S05/S45）間の極小光学キャビティ周縁に設けられた、撥水多孔質ePTFE（延伸PTFE）気圧平衡マイクロベントと、微量残存水分を吸着するモレキュラーシーブ系乾燥ストリップ。","opticsAndPhysics":["密閉光学空間を飛行機内や高山へ持ち込むと内外気圧差で薄い光学フィルターがわずかに膨らみ、ピント位置（光路長）やSSWF共振周波数が微妙に変化します。","孔径0.2 μmの撥水ePTFEベントは空気分子だけをゆっくり通して気圧差をゼロに保ちつつ、水滴やミクロン級ホコリの侵入は100%阻止します。","さらに極小モレキュラーシーブ乾燥ストリップがキャビティ内の露点温度を-30°C以下へ低く保ち、急冷時の内部結露（ガラス曇り）を生涯にわたって防止します。"],"formula":{"expression":"T_dew < −30 °C  (モレキュラーシーブ吸着平衡により極寒地の急激な温度降下でも内部結露ゼロ)","description":"気圧バランス維持と極低露点の同時達成により、氷点下〜熱帯雨林の過酷なプロ撮影環境に対応"},"nextGenInnovation":"非発塵ラミネート封入型乾燥ストリップにより、超音波SSWFの8,000 G振動下でも乾燥剤粒子が光学室内へ飛散するリスクを完全ゼロ化。","specs":[{"label":"調圧膜","value":"孔径 0.2 μm 撥水多孔質 ePTFE ベント"},{"label":"防曇要素","value":"非発塵封入モレキュラーシーブ乾燥帯"},{"label":"内部露点","value":"−30 °C 以下を維持"},{"label":"適用環境","value":"高山・航空輸送・寒冷地結露対策"}],"diagramType":"sensor_cavity_breather_desiccant"},{"id":"sensor-electronic-vnd","order":71,"swatchColor":"#4f46e5","groupKey":"センサー最前光学層_S71_電圧ひとつでまぶしい真夏の光を無段階","assembledPos":[0,0,8.8],"explodeOffset":[0,56,114],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S71. 液晶「電子可変NDフィルター（e-ND）」セル＆透過率リニア制御電極","subtitle":"Liquid-Crystal Electronic Variable ND Filter (e-ND: 1/4–1/128 Stepless, Sony FX6/BURANO)","category":"センサー最前光学層 S71 — 電圧ひとつでまぶしい真夏の光を無段階に暗くできる「魔法の自動サングラス」","plainAnalogy":"屋外のまぶしい太陽の下から急に暗いトンネルへ入るとき、いちいちレンズの前にサングラスを付け替えるのは大変ですよね。電子可変NDフィルターは、センサーのすぐ前に仕込んだ「液晶のスマートサングラス」で、電圧を少し変えるだけで明るさを1/4から1/128まで一瞬・無段階に調整できます！","summary":"ソニーのシネマカメラ（FX6 / FX9 / BURANO）で革新を起こした、センサー直前配置のゲストホスト型液晶・電子可変NDフィルター（e-ND）セル。機械的なフィルター交換なしで、ダイヤルやオート制御により透過率を1/4（2段）〜1/128（7段）までシームレスに連続減光できます。","opticsAndPhysics":["2枚の超高平面ガラスの間に「二色性色素を混ぜた液晶分子」を封入し、透明電極（ITO）へかける交流電圧（0〜5V）で分子の傾きを自在に回転させます。","電圧が低いと分子が寝て光を多く通し、電圧を上げると分子が立って偏光を吸収するため、絞りを変えて背景のボケ味を崩すことなく露出だけを滑らかに調整できます。","色かぶり（カラーシフト）を極小に抑えたRGB均一吸収色素を採用し、炎天下でもF1.2の開放ボケや1/48秒の映画シャッタースピードをそのまま維持できます。"],"formula":{"expression":"T(V) = T_min + (T_max − T_min) · cos²(θ(V))  (ND 1/4〜1/128：連続 5 EV 減光)","description":"印加電圧Vで液晶分子の傾きθを精密制御し、レンズのボケ量を変えずに光量だけを最大128分の1まで無段階調整"},"nextGenInnovation":"オートNDモードにより、屋外から屋内へワンカットで歩きながら撮影しても、絞り値・ISO・シャッター速度を一切動かさず適正露出を完全自動追従。","specs":[{"label":"減光範囲","value":"1/4（ND4）〜 1/128（ND128）無段階"},{"label":"応答速度","value":"約 30〜50 ms（電圧制御）"},{"label":"採用機種知見","value":"Sony FX6 / FX9 / BURANO 系統"},{"label":"光学平面度","value":"λ/4 以下（ARマルチコート両面）"}],"diagramType":"sensor_electronic_vnd"},{"id":"sensor-partially-stacked-strips","order":72,"swatchColor":"#10b981","groupKey":"次世代チップ構造_S72_コストを抑えながら読み出し速度を約4倍","assembledPos":[0,0,-0.35],"explodeOffset":[76,46,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S72. 部分積層（Partially-Stacked）上下高速読出ロジック帯＆DGOデュアルゲイン出力","subtitle":"Partially-Stacked Top/Bottom High-Speed Readout Strips & Dual Gain Output (α7 V / Z6 III)","category":"次世代チップ構造 S72 — コストを抑えながら読み出し速度を約4倍へ跳ね上げる「上下の専用高速レーン」","plainAnalogy":"全面2階建ての超高級ビル（フル積層センサー）は最高に速いけれど建築費がとても高くなります。そこで「一番混雑する入口と出口（チップの上と下のフチ）だけを2階建て高速レジ」にしたのが部分積層！お金を賢く抑えつつ、スポーツ撮影でもゆがみにくい爆速読み出しを実現した大発明です。","summary":"2025〜2026年の次世代スタンダード（Sony α7 V・Nikon Z6 III等）で採用された「部分積層（Partially-Stacked）」アーキテクチャ。中央の受光部（画素アレイ）は単層BSIのままにし、チップ上下の周縁部だけに超高速ADC・DGO（デュアルゲイン出力）回路ウェハーを3次元積層した高効率ハイブリッド構造です。","opticsAndPhysics":["従来の非積層センサーは画素の横にA/D変換回路を平面配置していたため配線が長く遅延がありましたが、上下端の真下に高速ロジック帯を重ねることで読み出し速度を約3.5〜4.5倍（約10〜14 ms）へ高速化しました。","同時に1つの画素から「暗い場所用の高感度信号」と「明るい場所用の低感度信号」を同時出力して合成するDGO（デュアルゲイン出力）回路を統合し、16ストップ級の超広いダイナミックレンジを両立します。","中央のフォトダイオード直下に発熱するロジック層がないため、長時間動画撮影時の熱ノイズ（暗電流）を低く抑えやすいという隠れた強みもあります。"],"formula":{"expression":"t_read ≈ 11〜14 ms（従来非積層比 約4×高速）＋ DGO同時合成 DR ≈ 16 stops","description":"上下端のみのピンポイント3D積層により、低コスト・低発熱のままローリング歪み激減と超高ダイナミックレンジを同時達成"},"nextGenInnovation":"全面積層フラッグシップの半額クラスのボディで、ブラックアウトフリー30fps連写と4K 120p・16ストップ動画撮影を現実化した2025〜2026年最大のブレイクスルー。","specs":[{"label":"積層構造","value":"上下周縁デュアル高速ロジック帯（部分3D積層）"},{"label":"読出高速化","value":"従来BSI比 約 3.5〜4.5 倍高速"},{"label":"明暗同時処理","value":"DGO（高/低ゲイン同時読出合成）"},{"label":"代表採用例","value":"Sony α7 V（2025） / Nikon Z6 III 世代"}],"diagramType":"sensor_partially_stacked_strips"},{"id":"sensor-curved-substrate","order":73,"swatchColor":"#06b6d4","groupKey":"次世代光学革命_S73_人間の目の_網膜_のようにセンサー自体を","assembledPos":[0,0,-0.95],"explodeOffset":[-82,46,12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S73. 湾曲（カーブド）フルサイズCMOSシリコン基板＆球面フォーミング保持台座","subtitle":"Curved Full-Frame CMOS Silicon Wafer & Concave Spherical Forming Ceramic Bed","category":"次世代光学革命 S73 — 人間の目の「網膜」のようにセンサー自体をお椀型に曲げて画面の端までくっきり写す技術","plainAnalogy":"レンズを通った光は本来、まっすぐな板ではなく「お椀の内側」のように丸くピントが合います。人間の目の網膜も丸いですよね！従来は重いレンズを何枚も足して無理やり平らにしていましたが、センサーの板そのものを薄くしてそっと曲げれば、小さくて明るいレンズでも端までバキッと鮮明に写ります。","summary":"シリコンウェハーを厚さ約50〜100マイクロメートルまで極薄研磨し、専用の凹球面セラミック台座へ精密に湾曲固定（球面フォーミング）した次世代カーブド・フルサイズCMOS基板。レンズの像面湾曲と周辺光量落ちをセンサー側で根本解決します。","opticsAndPhysics":["平らなセンサーでは画面の四隅ほど光が斜めに差し込むため、周辺が暗くなったり色がにじんだりしますが、センサーを曲率半径約100〜150 mmのお椀型に曲げると、隅の光もほぼ垂直（テレセントリック）に画素へ飛び込みます。","ソニーの学会発表でも実証された通り、周辺部の感度が約2倍向上し、さらにシリコン結晶に適度な圧縮応力がかかることで暗電流ノイズまで低減します。","レンズ側で像面湾曲を無理に補正する大型ガラス群を減らせるため、F1.2級の超大口径レンズでも手のひらサイズへ劇的に小型・軽量化できる可能性を秘めています。"],"formula":{"expression":"1 / R_sensor ≈ 1 / R_Petzval = Σ(φ_i / n_i)  （センサー曲率とレンズ像面湾曲の完全一致）","description":"ペッツバール像面湾曲に合わせてCMOS自体を球面形成し、画面中央から四隅まで均一な超高解像と明るさを実現"},"nextGenInnovation":"極薄CMOSウェハーの割れを防ぐ応力分散ボンディング技術により、次世代コンパクト・フルサイズ機や天体・車載カメラでの実用化が進む夢の光学構造。","specs":[{"label":"シリコン板厚","value":"約 50〜100 μm（極薄フレキシブル研磨）"},{"label":"球面曲率半径","value":"約 100〜150 mm（人間の網膜に倣う設計）"},{"label":"周辺感度向上","value":"平面比 約 1.4〜2.0 倍（斜め入射ロス激減）"},{"label":"主な効果","value":"像面湾曲の根絶・レンズ大幅小型軽量化"}],"diagramType":"sensor_curved_substrate"},{"id":"sensor-im-adjust-washers","order":74,"swatchColor":"#2563eb","groupKey":"純正精密校正_S74_髪の毛の1_3の薄さで_ピント面の傾きゼロ","assembledPos":[0,0,-8.9],"explodeOffset":[-88,-32,-158],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S74. 純正フランジバック選択シムワッシャー「IM ADJUST WASHER D」12段精密セット","subtitle":"Sony OEM IM ADJUST WASHER D Precision Flange-Back & Tilt Shims (ILCE-7M4 Ref.456)","category":"純正精密校正 S74 — 髪の毛の1/3の薄さで「ピント面の傾きゼロ」へ追い込む工場の秘密ワッシャー","plainAnalogy":"テーブルがほんの少しガタつくとき、脚の下に薄いコースターを1枚挟んでピタッと水平にしますよね。カメラのセンサーもまったく同じで、工場のレーザー測定器で「左上が0.025ミリ低い」とわかると、12種類の厚みから選んだ超精密ワッシャーを3本のネジの下へ挟み、完璧な水平とピント距離を出します。","summary":"ソニー公式ILCE-7M4サービスマニュアル（Ref.456）に記載された、12種類の厚みバリエーション（部品番号 `455838701`〜`468772712`：厚さ25 µm〜600 µm）からなる純粋な金属・高安定樹脂製フランジバック＆チルト校正用選択シムワッシャー群です。","opticsAndPhysics":["ソニーEマウントのフランジバック規格（マウント面からセンサー撮像面までの距離）は厳密に 18.000 mm と決められており、F1.2レンズの浅い被写界深度ではわずか10 µmの傾き（片ボケ）も許されません。","組立工場では3点の支持ボスそれぞれに異なる厚みの `IM ADJUST WASHER D` を組み合わせて挟み込み、センサー面の前後位置（Z）と上下左右の傾き（あおり角）を数ミクロン精度で永久固定します。","サービスセンターでのセンサー交換修理でも、元のシム厚を記録・再測定して1枚単位で調整し直すプロフェッショナル整備の要です。"],"formula":{"expression":"Δz_flange = |d_actual − 18.000 mm| ≤ ±0.005 mm  （最小シム刻み 0.025 mm）","description":"3点支持のシム厚組合せにより、Eマウント基準18.000 mmからの誤差と左右片ボケ傾きをミクロン単位で追い込み"},"nextGenInnovation":"工場レーザー干渉計と連動した自動シム選定ロボットにより、手作業を超えた再現性で全数ゼロ片ボケ出荷を保証。","specs":[{"label":"ソニー純正品番","value":"Ref.456: 455838701〜468772712（12種）"},{"label":"厚みラインナップ","value":"0.025 mm 〜 0.600 mm 精密段階"},{"label":"配置箇所","value":"IBISベース固定3点キネマティックボス"},{"label":"校正精度","value":"フランジバック 18.000 ±0.005 mm"}],"diagramType":"sensor_im_adjust_washers"},{"id":"sensor-mechanical-dust-shield","order":75,"swatchColor":"#334155","groupKey":"センサー最前防塵_S75_レンズを外した瞬間にスッと下りて高価な","assembledPos":[0,0,10.2],"explodeOffset":[0,-58,128],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S75. 電源OFF自動開閉「独立メカニカル・センサー保護シールド幕」","subtitle":"Dedicated Mechanical Sensor-Protection Dust Shield Curtain (Nikon Z8/Z9 & Flagship Class)","category":"センサー最前防塵 S75 — レンズを外した瞬間にスッと下りて高価なセンサーを砂埃から守る「自動シャッター扉」","plainAnalogy":"お店が閉店すると頑丈なシャッターをガラガラと閉めて店内を守りますよね。カメラの電源を切ってレンズを交換するとき、繊細な撮影用シャッター幕ではなく「専用の頑丈な防塵カーテン」がスッと下りてセンサーをカバーし、風で舞う砂埃やうっかり触る指から大切な撮像面を守り抜きます！","summary":"メカニカルシャッターを持たない完全電子シャッター機（Nikon Z8 / Z9）や最新ハイブリッド機に採用される、撮影用フォーカルプレーンシャッターとは独立した専用センサー保護シールド幕。電源OFFに連動してセンサー直前を物理的に密閉カバーします。","opticsAndPhysics":["従来の撮影用シャッター幕（厚さ数十µmの超軽量カーボン羽根）を防塵カバー代わりに閉めると、うっかり指やブロワー先端が触れただけで破損するリスクがありました。","独立シールド幕は高速連写の軽量制約がないため、剛性の高い金属・樹脂複合ブレードと専用マイクロソレノイド駆動を採用し、耐久性と防塵性能を大幅に高めています。","撮影時は撮像開口部の外側へ完全に退避し、内面は艶消し黒塗装で有害な反射（ゴースト）を一切発生させません。"],"formula":{"expression":"t_close ≈ 40 ms（電源OFF連動） ／ 塵埃侵入率 -95% 以上（屋外レンズ交換時）","description":"電源オフと同時に0.04秒で物理バリアを展開し、強風下のフィールドレンズ交換でもセンサーゴミ付着を劇的に抑制"},"nextGenInnovation":"電源OFF時のセンサー保護だけでなく、カメラ落下検知時に瞬時クローズして万一の衝撃破片から撮像面をガードする多機能保護機構へ進化。","specs":[{"label":"駆動方式","value":"独立低消費電力マイクロソレノイド＋リンク"},{"label":"ブレード材質","value":"高剛性・艶消し黒遮光複合シート"},{"label":"開閉動作","value":"電源ON/OFF連動（メニュー設定切替可）"},{"label":"代表採用知見","value":"Nikon Z8 / Z9・プロ機防塵アーキテクチャ"}],"diagramType":"sensor_mechanical_dust_shield"},{"id":"sensor-double-roll-halbach","order":76,"swatchColor":"#ea580c","groupKey":"次世代IBIS駆動_S76_磁石のN極とS極を賢く並べて磁力を1","assembledPos":[0,0,-7.2],"explodeOffset":[92,-36,-112],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S76. 2倍ロール広ストロークIBIS＆ハルバッハ配列デュアル極VCM磁石","subtitle":"2× Wide-Stroke Roll IBIS & Flux-Focusing Halbach VCM Magnet Array (α7R VI / 8.5-Stop)","category":"次世代IBIS駆動 S76 — 磁石のN極とS極を賢く並べて磁力を1.4倍に集中させ、8.5段の手ブレをピタッと止める怪力モーター","plainAnalogy":"普通の磁石は表にも裏にも磁力が逃げてしまいますが、「ハルバッハ配列」という特別な並べ方をすると、裏側への磁力漏れをゼロにして表側のコイル方向だけに強力なパワーを1.4倍も集中できます！おかげで同じ重さのまま手ブレ補正の動く幅を2倍に広げ、手持ち夜景でも三脚みたいに止まります。","summary":"2026年フラッグシップ世代（Sony α7R VIの中央8.5段／周辺7.0段補正等）の核心技術である、回転（ロール）補正角を従来の約2倍へ拡張した広ストローク5軸IBISと、磁束を片面へ集中させるハルバッハ配列ネオジムVCM（ボイスコイルモーター）磁石ユニットです。","opticsAndPhysics":["従来の上下2極マグネットの間に90度向きを変えた補助磁石を挟む「ハルバッハ配列」により、コイル側面の磁束密度Bを約1.4倍へ高めつつ、背面基板やシャッター側への漏洩磁場を激減させます。","広角レンズでの歩き撮りや手持ち夜景で最も目立ちやすい「画面端の回転ブレ（ロール）」を吸収するため、VCM推力と可動域を従来の2倍クラスへ拡大しています。","推力定数（N/A）が高まることで同じブレ補正力をより少ない電流で発生でき、IBISコイルの自己発熱を抑えてセンサーの熱ノイズ低減にも貢献します。"],"formula":{"expression":"F_VCM = B_Halbach · I · L  （B_Halbach ≈ 1.4 × B_std ／ 補正効果 8.5段中央・7.0段周辺）","description":"磁束集中ハルバッハ配列により、省電力・低発熱のまま2倍ロール広ストロークの8.5段級5軸手ブレ補正を実現"},"nextGenInnovation":"レンズ内手ブレ補正（OSS）とボディ内広ストロークIBISを1ミリ秒単位で協調制御し、動画の歩き揺れまでジンバル級に滑らか化。","specs":[{"label":"磁気配列","value":"N52ネオジム 90°回転ハルバッハ配列"},{"label":"磁束効率","value":"従来対向磁石比 約 +40% 磁束集中"},{"label":"補正性能目標","value":"中央 8.5 段 ／ 周辺 7.0 段（2倍ロール域）"},{"label":"副次メリット","value":"コイル消費電力・発熱を約 30% 低減"}],"diagramType":"sensor_double_roll_halbach"},{"id":"sensor-pixelshift-submicron-scale","order":77,"swatchColor":"#0ea5e9","groupKey":"超解像位置決め_S77_センサーを_1画素の半分_約2マイクロメ","assembledPos":[0,0,-5.6],"explodeOffset":[-90,56,-72],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S77. ピクセルシフトマルチ撮影専用「サブミクロン光学リニアスケール」＆0.5画素基準","subtitle":"Sub-Micron Optical Linear Encoder Scale for 16-Shot 240MP Pixel-Shift Multi-Shooting","category":"超解像位置決め S77 — センサーを「1画素の半分（約2マイクロメートル）」だけ正確にズラすための超ミクロものさし","plainAnalogy":"ふつうのカメラは1つの点で赤・緑・青のどれか1色しか測れません。そこでセンサーを「髪の毛の1/30」という超極小の幅だけ上下左右に16回ずらして撮り、全部の色を重ねると2.4億画素の超高精細写真になります！その神業のズレ幅を0.1ミクロン単位で測る専用ものさしがこのスケールです。","summary":"ピクセルシフトマルチ撮影（4枚合成／16枚・最大2.4億画素超解像）において、IBIS可動ステージを1画素ピッチ（約3.76〜5.1 µm）または半画素（0.5画素：約1.9 µm）単位で誤差なく精密ステップ移動させるための、光学式サブミクロン・リニアエンコーダスケールと読み取り基準です。","opticsAndPhysics":["通常のホール素子センサーは磁場の温度ドリフトがわずかに生じるため、超高画素の0.5画素ステップでは高精度な基準スケールと多点キャリブレーションによるクローズドループ制御が欠かせません。","熱膨張がほぼゼロのインバー合金／石英基板にミクロン周期の微細スリットを刻み、X軸・Y軸の移動量をサブミクロン分解能（約0.05〜0.1 µm）でリアルタイム監視します。","16枚撮影では4×4の格子点すべてでR・G・Bのフルカラー情報を偽色（モアレ）ゼロで取得でき、美術館の絵画アーカイブや建築写真で中判を超える解像力を叩き出します。"],"formula":{"expression":"Δx_step = 0.5 × p_pixel ≈ 1.88 μm  （位置決め再現精度 σ ≤ 0.10 μm）","description":"画素ピッチのちょうど半分という極微細ステップを±0.1ミクロン以内で制御し、偽色ゼロの2.4億画素超解像を実現"},"nextGenInnovation":"手持ち撮影でも手のわずかな揺れを逆利用し、AI位置合わせと組み合わせる「手持ちハイレゾショット（手持ちピクセルシフト）」へ発展。","specs":[{"label":"ステップ刻み","value":"1.0 画素 ／ 0.5 画素（約 1.9〜2.5 μm）"},{"label":"位置決め精度","value":"±0.1 μm 以下（閉ループ制御）"},{"label":"スケール材質","value":"超低熱膨張インバー／石英光学格子"},{"label":"対応撮影機能","value":"4枚／16枚 ピクセルシフトマルチ撮影"}],"diagramType":"sensor_pixelshift_submicron_scale"},{"id":"sensor-filter-edge-sumi","order":78,"swatchColor":"#1f2937","groupKey":"極限ゴースト対策_S78_ガラスの_フチ_を真っ黒な特殊インクで","assembledPos":[0,0,3.55],"explodeOffset":[-84,-46,56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S78. 光学フィルター端面「墨塗り（エッジブラックニング）」＆45°面取り迷光トラップ","subtitle":"Optical Filter Perimeter Sumi-Nuri Edge Blackening & 45° Bevel Stray-Light Trap","category":"極限ゴースト対策 S78 — ガラスの「フチ」を真っ黒な特殊インクで塗りつぶし、夜景の変な光の輪を消す職人技","plainAnalogy":"透明なアクリル板の横からライトを当てると、端っこがピカッと光りますよね。カメラのセンサー前のガラスでも、強い街灯や星の光がガラスの端で反射すると写真に「謎の赤い輪や白いモヤ（ゴースト）」が出ます。そこでガラスの側面を特殊な艶消し黒インクで「墨塗り」して光を吸い取ってしまうんです！","summary":"センサー直前の光学ローパスフィルター（OLPF）・IRカットガラス・カバーガラスの四辺切断面および45°面取り（チャンファー）部へ施される、屈折率整合型の超低反射黒色遮光塗料（墨塗り：Sumi-nuri）エッジトラップ構造です。","opticsAndPhysics":["ガラスの側面が透明または白くすりガラス状に残っていると、画面外の強い光源（太陽・LED街灯・明るい一等星）がガラス内部で全反射を繰り返して画面端へ迷光フレアをまき散らします。","光学ガラス（屈折率 n ≈ 1.52）に近い屈折率を持つカーボンブラック配合の特殊黒色樹脂を側面全周へ塗布することで、界面反射を起こさず光線を塗料内部へ引き込んで熱として完全吸収します。","さらにエッジを45°に精密面取りすることで、仮にわずかな反射が生じてもセンサー方向へ戻らず外側の遮光バッフルへ向かうよう光学設計されています。"],"formula":{"expression":"R_edge = ((n_glass − n_ink) / (n_glass + n_ink))² < 0.05%  （屈折率整合による界面吸収）","description":"ガラスと黒インクの屈折率を揃えることで側面反射を0.05%未満へ抑え、星景・逆光撮影の迷光ゴーストを根絶"},"nextGenInnovation":"超広角大口径レンズの斜め入射光が増えたショートフランジバック時代のミラーレス機で、画面四隅のコントラストを劇的に高める隠れた名脇役。","specs":[{"label":"塗布対象","value":"OLPF / IRカット / カバーガラス全周端面"},{"label":"塗料特性","value":"屈折率整合カーボン黒（反射率 < 0.5%）"},{"label":"端面加工","value":"45° 精密面取り＋艶消し吸光コート"},{"label":"画質効果","value":"逆光・夜景・星景の画面端ゴースト消去"}],"diagramType":"sensor_filter_edge_sumi"},{"id":"sensor-sswf-fluorine-ar","order":79,"swatchColor":"#22d3ee","groupKey":"最表面ナノ保護_S79_静電気を逃がしてホコリを寄せ付けず_油汚","assembledPos":[0,0,7.35],"explodeOffset":[82,46,98],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S79. SSWF最表面・超撥水フッ素＋帯電防止マルチARコート複合ナノ膜","subtitle":"SSWF Outermost Fluorine Repellent + Anti-Static Conductive Multi-AR Nano-Coating","category":"最表面ナノ保護 S79 — 静電気を逃がしてホコリを寄せ付けず、油汚れもスルッと落ちる「テフロン級コーティング」","plainAnalogy":"下敷きをこすると静電気でホコリがピタッと張り付きますよね。センサー前のガラスも同じで、静電気が溜まるとブロワーで吹いてもゴミが取れなくなります。そこでガラスの最表面に「電気を逃がす透明膜」と「フライパンのようなツルツル撥油フッ素膜」を重ね、ゴミを弾き飛ばせるようにしてあります！","summary":"超音波ダストリダクション（SSWF）フィルターの最前面に真空蒸着された、帯電防止導電酸化物層（ITO/ATO系）＋多層反射防止ARコート＋超撥水・撥油フッ素ナノ薄膜の複合保護コーティングです。","opticsAndPhysics":["レンズ交換時の空気摩擦やシャッター動作で発生しがちな静電気を、ナノ厚の透明帯電防止膜を通じて周囲のグランド枠へ瞬時に逃がし、静電吸着によるセンサーダスト付着を防ぎます。","最外層のパーフルオロポリエーテル系フッ素膜は水接触角110°以上の超撥水・撥油性を持ち、万一シャッター微細潤滑油や水滴が付いても球状に弾き、超音波振動やセンサースワブで跡なく落とせます。","同時に可視光400〜700 nmでの表面反射率を0.2%以下へ抑える多層AR干渉膜と一体化しており、画質劣化や透過ロスはほぼゼロです。"],"formula":{"expression":"R_vis < 0.2%（多層AR） ／ 水接触角 θ_c ≥ 110°（フッ素撥油） ／ R_sheet < 10⁹ Ω/□（帯電防止）","description":"光の反射ロスを0.2%未満に保ったまま、静電気によるホコリ吸着と油汚れ固着をナノ薄膜でダブルブロック"},"nextGenInnovation":"クリーニング耐擦傷性を高めた硬質ナノシリカ下地とフッ素分子の化学結合により、長年のメンテナンスでも撥水・帯電防止性能が劣化しない長寿命設計。","specs":[{"label":"膜構成","value":"帯電防止透明導電膜＋多層AR＋フッ素撥油膜"},{"label":"可視光反射率","value":"0.2% 以下（400〜700 nm）"},{"label":"撥水・撥油性","value":"水接触角 110° 以上（油滴固着防止）"},{"label":"主な効果","value":"ホコリ静電反発＋センサークリーニング保護"}],"diagramType":"sensor_sswf_fluorine_ar"},{"id":"sensor-wirebond-dam-baffle","order":80,"swatchColor":"#475569","groupKey":"パッケージ遮光_S80_ピカピカ光る極細の金線を_真っ黒な樹脂の","assembledPos":[0,0,0.55],"explodeOffset":[-82,10,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S80. 金ワイヤーボンディング黒色「ダム＆フィル」保護封止＆段差遮光ベベル","subtitle":"Gold Wire-Bond Black Epoxy Dam-and-Fill Encapsulation & Stepped Flare-Baffle Collar","category":"パッケージ遮光 S80 — ピカピカ光る極細の金線を「真っ黒な樹脂の堤防」で包み込み、断線と乱反射を同時に防ぐ","plainAnalogy":"センサーチップの周囲には、髪の毛より細い「金色の電線（金ワイヤー）」が何百本もアーチ状に張られています。剥き出しだと強い光が当たってキラキラ乱反射し、写真にフレアが出ちゃいます。そこで周囲に「真っ黒な樹脂の堤防（ダム）」を作って黒い樹脂で優しく固め、保護と遮光を一石二鳥でこなします！","summary":"CMOSチップ外周とセラミックパッケージ電極を結ぶ数百本の極細金ワイヤーボンディング部を、高粘度黒色エポキシ堤防（ダム）と低応力黒色充填材（フィル）で覆い、さらに45°段差遮光ベベルを設けた保護・防眩封止構造です。","opticsAndPhysics":["金ワイヤーやアルミ電極パッドは鏡のように高い反射率（>90%）を持つため、F1.2レンズの強い周辺光束が当たるとカバーガラス裏面で再反射し、画面端に帯状のカラーフレアを引き起こします。","有効画素領域（36×24 mm）を一切汚さない精密ディスペンサーでまず外周に「黒色ダム（堤防）」を描き、その中へワイヤーを包む「黒色フィル樹脂」を流し込んで硬化させます。","これにより、超音波振動や落下衝撃によるワイヤー断線・共振ショートを完全に防ぐと同時に、ワイヤー周辺の反射率を1%未満へ落とし込みます。"],"formula":{"expression":"R_wire(95%) → R_encap(< 1.0%)  （ワイヤー周囲迷光強度を約 -20 dB 以上遮断）","description":"高反射な金線・電極パッドを低応力黒色エポキシで完全被覆し、耐衝撃保護と極限のフレア防止を同時に実現"},"nextGenInnovation":"熱膨張係数をシリコン・セラミックに合わせた低応力シリカフィラー配合により、-20℃〜+85℃のヒートサイクルでも金ワイヤーを引っ張らない超高信頼封止。","specs":[{"label":"封止方式","value":"2液精密ディスペンス「ダム＆フィル」構造"},{"label":"封止樹脂","value":"カーボン遮光・低応力黒色エポキシ"},{"label":"光学効果","value":"金ワイヤー・ボンディングパッド乱反射遮断"},{"label":"機械保護","value":"落下衝撃・超音波振動からの断線防止"}],"diagramType":"sensor_wirebond_dam_baffle"},{"id":"sensor-tcxo-clock-tree","order":81,"swatchColor":"#eab308","groupKey":"超精密タイミング_S81_1秒間に数億回きざむ_ズレない心臓の鼓","assembledPos":[-12.5,16.2,-3.35],"explodeOffset":[-64,72,-34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S81. センサー基板直載・超低ジッター温度補償水晶発振器（TCXO）＆同期クロック分配器","subtitle":"Sensor-Board Mounted Ultra-Low-Jitter TCXO Clock & Genlock Timing Distribution Tree","category":"超精密タイミング S81 — 1秒間に数億回きざむ「ズレない心臓の鼓動」でノイズと映像ズレを封じる専用時計","plainAnalogy":"オーケストラの指揮者のリズムが少しでもフラつくと演奏がぐちゃぐちゃになりますよね。センサーも1秒間に何億回もタイミングを合わせて光を読み出しています。温度が変わっても100万分の0.5しか狂わない「超高級な専用ストップウォッチ（TCXO）」をセンサーの真横に置くことで、ノイズのない澄んだ画と複数台同期を実現します！","summary":"イメージセンサー背面基板のすぐ近くに配置された、温度補償型水晶発振器（TCXO：Temperature Compensated Crystal Oscillator）と超低ジッターPLLクロック分配IC。画素のA/D変換やSLVS-EC超高速シリアル伝送、プロ動画のゲンロック同期の基準となる精密クロックを供給します。","opticsAndPhysics":["センサーは長時間撮影で温度が20℃→60℃へ上昇しますが、通常の水晶では周波数がズレてしまい、映画のマルチカメラ収録で音声と映像のズレ（リップシンク誤差）を生みます。","TCXOは内部の温度センサーと可変容量ダイオードで水晶の温度特性を自動キャンセルし、±0.5 ppm（1時間で約1.8ミリ秒未満）という驚異的な周波数安定度を保ちます。","さらにクロック波形の時間的な揺らぎ（位相ジッター）をフェムト秒〜ピコ秒オーダーへ抑え込むことで、14-bit ADC変換時のタイミング誤差ノイズや高速SLVS-EC通信のビットエラーを根絶します。"],"formula":{"expression":"Δf / f₀ ≤ ±0.5 ppm  （位相ジッター σ_j < 0.5 ps RMS @ 72 MHz 基準発振）","description":"温度変化に動じない±0.5ppmの高精度基準時計をセンサー至近に置き、14-bit高画質読出とプロ動画同期を保証"},"nextGenInnovation":"カメラ本体のタイムコード入力（TC IN）とセンサー側TCXOをデジタルPLLで位相同期させ、複数カメラによる映画・バーチャルプロダクションの完全フレーム同期を実現。","specs":[{"label":"発振器種別","value":"超小型表面実装 TCXO（温度補償水晶）"},{"label":"周波数安定度","value":"±0.5 ppm（-20〜+75℃ 動作保証）"},{"label":"位相ジッター","value":"< 0.5 ps RMS（超低ノイズPLL直結）"},{"label":"主な役割","value":"ADC基準タイミング / SLVS-EC / 動画同期"}],"diagramType":"sensor_tcxo_clock_tree"},{"id":"sensor-cross-roller-guide","order":82,"swatchColor":"#94a3b8","groupKey":"超高剛性案内_S82_重いセンサーが高速に動いても_ピント面が1","assembledPos":[0,0,-6],"explodeOffset":[88,60,-86],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S82. 超高剛性クロスローラー＆板バネ（フレクシャー）IBIS直動案内ユニット","subtitle":"High-Rigidity Cross-Roller Guide Rail & Parallel-Flexure Anti-Tilt IBIS Suspension","category":"超高剛性案内 S82 — 重いセンサーが高速に動いても「ピント面が1ミクロンも傾かない」無摩擦ガイドレール","plainAnalogy":"重たいカメラセンサーを手ブレ補正でブンブン素早く動かすと、少しだけ前後にお辞儀（傾き）してピントがボケそうになります。そこで、工場の精密工作機械と同じ「交互に組んだ極小ローラーレール（クロスローラー）」や「しなやかな金属板バネ（フレクシャー）」で支え、上下左右にはスルスル動くのに前後にはビクともしない魔法の足回りを作っています！","summary":"8.5段クラスの広ストロークIBISや大型・重量級の多層冷却センサーを、前後方向（光軸Z軸）のガタつき・傾き（チルト）ゼロで滑らかに平面案内する、精密クロスローラー直動ガイドおよびベリリウム銅並列板バネ（フレクシャー）懸架機構です。","opticsAndPhysics":["ボール点接触支持に加え、円筒ローラーを90°交互に直交配置したクロスローラーや弾性ヒンジ型フレクシャーを併用することで、Z軸方向の平面剛性を桁違いに高められます。","金属同士のすべり摩擦がほぼゼロのため、わずかな手ブレ（数マイクロメートルの微小揺れ）に対しても引っかかり（スティクション）なく即座に追従できます。","望遠レンズでの縦位置・下向き・上向き撮影でも自重によるセンサー垂れ下がりを防ぎ、F1.2開放の極薄ピント面を全方向で死守します。"],"formula":{"expression":"K_z / K_xy > 10³  （光軸方向の傾き剛性は平面移動剛性の1,000倍以上）","description":"横と回転には無摩擦で素早く動きつつ、ピントに関わる前後方向のブレだけは鉄壁に抑え込む異方性ガイド構造"},"nextGenInnovation":"摩耗粉が出ない弾性フレクシャー案内と超低摩擦セラミックガイドのハイブリッド化により、数十万ショットを超えても初期の片ボケゼロ精度を維持。","specs":[{"label":"案内機構","value":"クロスローラー直動レール＋ベリリウム銅板バネ"},{"label":"平面維持精度","value":"チルト誤差 < 2 秒角（全ストローク全域）"},{"label":"摩擦・摩耗","value":"実質ゼロ（スティクション・摩耗粉レス）"},{"label":"主な効果","value":"8.5段広ストローク＆下向き撮影時の片ボケ防止"}],"diagramType":"sensor_cross_roller_guide"},{"id":"sensor-peltier-tec-cooler","order":83,"swatchColor":"#38bdf8","groupKey":"極限能動冷却_S83_電気を流すだけでセンサーを氷点下近くまで冷","assembledPos":[0,0,-12.2],"explodeOffset":[0,-68,-182],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S83. ペルチェ素子（TEC）能動冷却モジュール＆コールドフィンガー結露防止ヒーター","subtitle":"Thermoelectric Peltier Cooler (TEC) Module & Anti-Dew Window Heater (Astro / Cinema)","category":"極限能動冷却 S83 — 電気を流すだけでセンサーを氷点下近くまで冷やし、熱ノイズを消し去る「超小型冷蔵庫」","plainAnalogy":"真夏の暑い部屋で長時間星空を撮ると、センサーが熱を持ってザラザラの赤や青のノイズ（暗電流）が湧いてきます。ペルチェ素子は「電気を流すと片面がキンキンに冷えて反対側が熱くなる魔法の半導体プレート」！これでセンサーだけを冷やし、さらにガラスが曇らないよう縁をほんのり温める結露防止ヒーターも備えています。","summary":"天体撮影用フルサイズカメラやシネマカメラの熱ノイズ極小化に用いられる、Bi₂Te₃（ビスマステルル）半導体P/N接合対によるペルチェ（TEC：Thermoelectric Cooler）能動冷却モジュール、銅コールドフィンガー、およびカバーガラス結露防止マイクロヒーター環です。","opticsAndPhysics":["シリコンCMOSの熱ノイズ（暗電流）は温度が約6〜8℃下がるごとに半分になる性質（アレニウス則）があるため、センサーを環境温度より20〜35℃低く冷やすと暗電流が1/10〜1/30以下へ劇的に消滅します。","2枚のアルミナセラミック基板の間に数十対のP型・N型半導体柱を直列配置し、直流電流を流すとペルチェ効果でセンサー側から熱を強制的に汲み上げ、背面のヒートシンク／冷却ファンへ排熱します。","急冷すると表面ガラスに結露（くもり）が生じるため、光路外の縁に極小消費電力の温熱ヒーター線を巡らせて露点以上を保つ工夫がセットになっています。"],"formula":{"expression":"I_dark(T) ∝ T^(3/2) · exp(−E_g / 2kT)  （約 6〜7 ℃ 冷却するごとに熱ノイズが半減！）","description":"ペルチェ能動冷却で撮像素子の温度を強制低下させ、数分間の星空長時間露光や8K連続収録でも澄み切った暗部を維持"},"nextGenInnovation":"軽量薄型マイクロTECと高効率グラファイト／アクティブファン排熱の組み合わせにより、小型ボディでも熱暴走ゼロ・超低暗電流撮影を実現する次世代冷却技術。","specs":[{"label":"冷却原理","value":"Bi₂Te₃ 半導体ペルチェ効果（能動ヒートポンプ）"},{"label":"最大冷却差 ΔT","value":"外気温比 -20〜-35 ℃（天体・シネマ仕様）"},{"label":"結露対策","value":"カバーガラス周縁 0.3W 防曇ヒーター併用"},{"label":"画質効果","value":"長時間露光の暗電流・ホットピクセル激減"}],"diagramType":"sensor_peltier_tec_cooler"},{"id":"sensor-die-fiducial-targets","order":84,"swatchColor":"#facc15","groupKey":"工場ミクロン照準_S84_チップの四隅に刻まれた_超精密な十字照","assembledPos":[0,0,0.18],"explodeOffset":[82,-14,24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S84. ウェハー端面アライメント基準マーク（フィデューシャル）＆6軸レーザー自動調芯ターゲット","subtitle":"Silicon Die-Corner Optical Fiducial Crosshairs & 6-Axis Active-Alignment Laser Targets","category":"工場ミクロン照準 S84 — チップの四隅に刻まれた「超精密な十字照準」で0.001ミリ単位のピント合わせを可能にする","plainAnalogy":"カラー印刷のポスターの端っこに「＋」のトンボマークが印刷されていますよね。実はイメージセンサーのシリコンチップの四隅にも、顕微鏡でしか見えない黄金の「＋」マーク（フィデューシャル）が刻まれています！組立ロボットがこの4つの十字をレーザーで見つめながら、髪の毛の1/50の精度で真っ直ぐ取り付けるんです。","summary":"フルサイズCMOSシリコンダイの有効撮像領域外（四隅ベゼル）にフォトリソグラフィでナノメートル精度にパターニングされた、金属クロム／金製の光学アライメント基準マーク（フィデューシャル）および6軸レーザー干渉調芯用ミラーターゲットです。","opticsAndPhysics":["セラミックパッケージへのダイボンディング工程、さらにはカメラ本体マウント面に対する6軸アクティブアライメント（X, Y, Z, ピッチ, ヨー, ロール調整）の絶対座標基準として機能します。","シリコン外形をダイヤモンドブレードで切断（ダイシング）した端面には数ミクロンの誤差が出ますが、画素アレイと同一の半導体露光マスクで焼き付けたフィデューシャルマークは画素中心に対して数十ナノメートル以内の絶対精度を誇ります。","工場のマシンビジョンカメラが4隅の十字ターゲットを同時認識することで、画面の回転傾き（ロール誤差0.01°以下）と光軸中心ズレを完璧にゼロ化します。"],"formula":{"expression":"ε_align(X, Y) < ±1.0 μm ／ ε_roll < ±0.01°  （4隅光学フィデューシャル同時画像認識）","description":"画素と同一マスクで焼き付けた4隅の十字ターゲットを基準にし、センサー取付の傾きと中心ズレをミクロン以下へ収束"},"nextGenInnovation":"AIマシンビジョンと6軸ピエゾロボットによる全自動アクティブアライメントが、6,000万画素超時代でも四隅まで均質な解像力を全数保証。","specs":[{"label":"形成工程","value":"画素アレイ同一リソグラフィ（絶対基準）"},{"label":"配置位置","value":"36×24 mm 有効域外の四隅コーナーパッド"},{"label":"認識精度","value":"位置 ±1 μm 以下 ／ 回転角 ±0.01° 以下"},{"label":"主な用途","value":"ダイ実装・6軸レーザー調芯・工場検査"}],"diagramType":"sensor_die_fiducial_targets"},{"id":"sensor-carrier-piezo-accel","order":85,"swatchColor":"#f43f5e","groupKey":"直載ブレ検知_S85_カメラ本体のジャイロだけでは捉えきれない_","assembledPos":[19.5,14.8,-4.9],"explodeOffset":[74,64,-56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S85. IBIS可動ステージ直載・超小型MEMS/圧電加速度センサー（シャッター衝撃逆位相打消し）","subtitle":"IBIS-Carrier Mounted 3-Axis MEMS/Piezo Accelerometer (Real-Time Shutter-Shock Canceller)","category":"直載ブレ検知 S85 — カメラ本体のジャイロだけでは捉えきれない「シャッターの微振動」を現場で直接キャッチ","plainAnalogy":"ノイズキャンセリングヘッドホンは、耳元のマイクで騒音を直接聴いて「真逆の波」を出して音を消しますよね。センサーが乗る可動台座にも超小型の加速度センサーを直接乗せておくことで、メカシャッターがガシャンと閉まる瞬間の微振動をその場で感知し、VCMモーターで逆向きの力を出して微ブレを打ち消します！","summary":"カメラ本体メイン基板のジャイロセンサーとは別に、IBIS可動キャリア（撮像素子ユニット側）へ直載された超小型・広帯域3軸MEMS／圧電加速度センサー。シャッター幕の走行ショックや手持ち時の高周波微振動を現場で直接検知し、フィードフォワード逆位相制御で相殺します。","opticsAndPhysics":["メイン基板のジャイロは「カメラ全体のゆっくりした回転ブレ（0.5〜20 Hz）」の検知に優れますが、メカシャッターの停止衝撃は100〜500 Hzの高周波並進振動（微ブレ）としてセンサーへ直撃します。","可動キャリア直上に加速度センサーを置くことで、構造体の共振遅れなしに並進加速度（X/Y/Z）をダイレクト検出し、1/60〜1/250秒付近で起きやすい「シャッターショック微ブレ」を逆位相推力で打ち消します。","さらに近接マクロ撮影時に支配的となる並進シフトブレ（上下左右の平行移動）の検出精度も大きく高めます。"],"formula":{"expression":"F_cancel(t) = −m_stage · a_measured(t)  （高帯域 1 kHz 閉ループ逆位相アクティブ制振）","description":"可動ステージ自身の加速度を1/1000秒単位で直接計測し、シャッターショックと並進マクロブレを瞬時に相殺"},"nextGenInnovation":"ボディ側ジャイロ＋レンズ側ジャイロ＋IBIS直載加速度センサーの3系統センサーフュージョンにより、マクロから超望遠まで全帯域の微ブレを完全制圧。","specs":[{"label":"センサー素子","value":"超小型 3軸 MEMS／圧電加速度計（2×2 mm）"},{"label":"サンプリング","value":"最大 2〜4 kHz 高速フィードバック"},{"label":"主な検知対象","value":"シャッターショック高周波振動・並進シフトブレ"},{"label":"実装場所","value":"IBIS可動キャリア／センサー基板端"}],"diagramType":"sensor_carrier_piezo_accel"},{"id":"sensor-dual-edge-slvs16","order":86,"swatchColor":"#14b8a6","groupKey":"超広帯域伝送_S86_左右両側から計16車線の超高速道路でデータ","assembledPos":[0,0,-2.85],"explodeOffset":[96,12,-32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S86. 16レーン両端並列 SLVS-EC v3.0 超高速インターポーザー＆コモンモードチョーク帯","subtitle":"Dual-Edge 16-Lane SLVS-EC v3.0 High-Speed Interposer & Common-Mode Choke Filter Bank","category":"超広帯域伝送 S86 — 左右両側から計16車線の超高速道路でデータを送り出し、電波ノイズだけを食い止める関所","plainAnalogy":"6,000万画素の写真や8K動画を1秒間に何十枚も撮ると、片側の出口だけでは大渋滞してしまいます。そこでセンサー基板の左右両端に計16車線の超高速出口（SLVS-EC v3.0）を設け、出口ごとに「大事な映像信号は素通りさせ、邪魔な電磁ノイズだけを通行止めにする小さな関所（コモンモードチョーク）」をずらりと並べています！","summary":"フルサイズCMOSセンサーの左右両端にシンメトリー配置された、計16レーン（片側8レーン×2）SLVS-EC v3.0超高速差動出力インターポーザーと、各レーン対の直近に並ぶ超小型フェライト・コモンモードチョークコイル配列です。","opticsAndPhysics":["左右対称のデュアルエッジ読み出しとSLVS-EC v3.0（最大12.5〜20 Gbps/レーン）により、実効160〜250 Gbps級の圧倒的なRAWデータ帯域を遅延なくBIONZ XRへ直結伝送します。","差動ペア（＋線と−線）を互いに逆位相で伝わる映像信号は磁界が打ち消し合ってチョークをロスなく通過しますが、外部へ漏れ出す同相ノイズ（コモンモードEMI）だけはフェライトのインピーダンスで強力に減衰させます。","これにより、カメラ内部のWi-Fi 6EやGNSSアンテナへの電波干渉を防ぎつつ、長尺IBISフレキ経由でも信号波形（アイパターン）をクッキリ保ちます。"],"formula":{"expression":"BW_total = 16 lanes × 12.5 Gbps = 200 Gbps  （特性インピーダンス Z_diff = 100 Ω ±5%）","description":"左右16レーン並列＋コモンモードノイズ除去により、8K RAW・120fps連写データを超低EMIでエラーゼロ伝送"},"nextGenInnovation":"クロック埋め込み方式＋フレキシブル基板への差動インピーダンス整合設計で、IBISの激しい振動下でも200 Gbps級データリンクを安定維持。","specs":[{"label":"レーン構成","value":"左右対称 8レーン × 2 ＝ 計 16 レーン"},{"label":"対応規格","value":"Sony SLVS-EC v2.0 / v3.0 差動高速IF"},{"label":"ノイズ対策","value":"0605サイズ極小フェライト・コモンモードチョーク"},{"label":"差動抵抗整合","value":"100 Ω ±5% 等長蛇行配線（スキュー極小）"}],"diagramType":"sensor_dual_edge_slvs16"},{"id":"sensor-thermal-via-dieattach","order":87,"swatchColor":"#d97706","groupKey":"極限排熱_無反り_S87_チップの真下に何百本もの_銅の熱ぬき煙","assembledPos":[0,0,-1.35],"explodeOffset":[-92,-16,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S87. セラミック基板貫通「銅サーマルビアアレイ」＆低応力ナノ銀焼結ダイボンド緩衝層","subtitle":"Ceramic Package Filled-Copper Thermal Via Array & Low-Stress Nano-Silver Sintered Die-Attach","category":"極限排熱＆無反り S87 — チップの真下に何百本もの「銅の熱ぬき煙突」を貫通させ、熱と反りを同時に逃がす","plainAnalogy":"セラミックの土台は硬くて歪みにくいのですが、金属より熱を通しにくい弱点があります。そこで土台に極小の穴を何百個もあけて純銅をぎっしり詰め込んだ「熱の特急エレベーター（サーマルビア）」を作り、チップとはしなやかなナノ銀の接着層で貼ることで、8K動画の熱を裏側へ一気に逃がしながらシリコンの反りも防ぎます！","summary":"CMOSシリコンダイの裏面とセラミックパッケージの間を接合する低応力ナノ銀焼結（シンタード・シルバー）ダイボンド層と、セラミック基板を垂直貫通して熱を背面ヒートシンクへ直通させる高密度・純銅充填サーマルビアアレイです。","opticsAndPhysics":["通常のエポキシ樹脂系接着剤（熱伝導率 1〜5 W/m·K）に代わり、ナノサイズの銀粒子を低温焼結した多孔質・純銀接合層（熱伝導率 > 150 W/m·K）を使うことで、熱抵抗を一桁以上低減します。","さらにシリコン（熱膨張率 2.6 ppm/K）と金属放熱板の膨張差をナノ銀の微細構造がクッションのように吸収するため、8K長時間撮影で高温になっても撮像面が弓なりに反る（像面歪み）のを防ぎます。","セラミック基板内部を垂直に貫く数百本の銅サーマルビア（熱伝導率 398 W/m·K）が、シリコンで生じた熱を最短距離で背面の銅ヒートスプレッダー・グラファイトシートへ橋渡しします。"],"formula":{"expression":"R_th = t / (k_eff · A)  （ナノ銀 k > 150 W/m·K ＋ 貫通銅ビア k ≈ 398 W/m·K で熱抵抗を大幅削減）","description":"セラミック基板の熱の壁を数百本の純銅ビアで貫通し、センサー中心部の温度上昇と反り歪みを徹底的に抑え込む"},"nextGenInnovation":"鉛フリー・ボイド（気泡）レスの圧力アシスト銀焼結プロセスにより、高発熱な積層DRAM付きグローバルシャッターセンサーでも2時間超の連続8K記録を下支え。","specs":[{"label":"接合層材質","value":"低応力ナノ銀焼結層（k > 150 W/m·K）"},{"label":"貫通ビア","value":"純銅充填サーマルビアアレイ（数百本格子）"},{"label":"主な効果","value":"撮像面温度 -8〜12℃ 低減＆熱反り防止"},{"label":"配置位置","value":"CMOSダイ直下〜セラミックパッケージ貫通部"}],"diagramType":"sensor_thermal_via_dieattach"},{"id":"sensor-freefall-ibis-brake","order":88,"swatchColor":"#e11d48","groupKey":"落下緊急保護_S88_カメラをうっかり落とした0_05秒後に_緊","assembledPos":[0,0,-7.9],"explodeOffset":[-96,-54,-120],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S88. 電源OFF磁気ディテント＆落下検知「緊急電磁ブレーキ・ストッパー」","subtitle":"Power-Off Magnetic Park Detent & Freefall Emergency Electromagnetic IBIS Brake Shoes","category":"落下緊急保護 S88 — カメラをうっかり落とした0.05秒後に「緊急ブレーキ」で浮いているセンサーをガッチリ守る","plainAnalogy":"手ブレ補正のセンサーは磁石の力で宙に浮いているので、電源を切ったときやうっかりカメラを落としたときに中でゴツンと暴れると大変です！そこで、ボディの落下センサーが「あ、落ちた！」と気づいた瞬間（床に着く前！）に、この電磁ブレーキと柔らかいラバー歯がセンサーを中央へキュッと固定して衝撃から救い出します。","summary":"電源OFF時にIBIS可動ステージを中央パーク位置へ優しく保持する磁気ディテントと、ボディ側の落下検知加速度センサー（B112）からの緊急割込みを受けて数ミリ秒で可動部を制動・クランプする電磁ブレーキ・衝撃吸収ストッパー機構です。","opticsAndPhysics":["自由落下開始から床に衝突するまで（高さ1mで約450ミリ秒）の間に、約30〜50ミリ秒で無重力状態（全軸合計加速度 ≈ 0 G）を検知し、VCMの回生ショート制動（電磁ブレーキ）とクランプシューを同時作動させます。","電源OFF中にカメラをバッグで運ぶ際も、わずかな電力も使わずに可動枠を定位置へ引き寄せる磁気ディテントと、高減衰ブチルゴム歯付きストッパーがカタカタ音とボール座の打痕（ブリネリング）を防ぎます。","衝撃エネルギーを柔らかいエラストマーと磁気ダンピングで分散させることで、落下後の「手ブレ補正エラー・片ボケ故障」リスクを劇的に引き下げます。"],"formula":{"expression":"t_brake ≈ 15 ms ≪ t_fall = √(2h / g) ≈ 450 ms（高さ 1 m 落下時・着地前に完全制動！）","description":"1メートルの高さから落としても、地面に着く約0.4秒も前にIBIS可動部を安全ロック＆電磁ダンピング完了"},"nextGenInnovation":"ボディ落下IMU（B112）と連動したリアルタイム安全プロトコルにより、電源ON中の不意のアクシデントでも高価な8.5段IBIS機構を守り抜くプロ機信頼性。","specs":[{"label":"制動方式","value":"VCM電磁ショートブレーキ＋ゴム歯ストッパー"},{"label":"緊急応答時間","value":"落下検知から約 15〜30 ms 以内で保護完了"},{"label":"電源OFF保持","value":"無通電・磁気パークディテント機構"},{"label":"保護対象","value":"セラミックボール座の打痕・コイル断線防止"}],"diagramType":"sensor_freefall_ibis_brake"},{"id":"sensor-low-alpha-mold","order":89,"swatchColor":"#a855f7","groupKey":"放射線ノイズ対策_S89_ガラスや陶器に微量に含まれる_天然の放","assembledPos":[0,0,1.75],"explodeOffset":[88,-42,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S89. 低α線（ウラン/トリウム除去）超高純度カバーガラス＆ソフトエラー防止セラミック遮蔽壁","subtitle":"Ultra-Low-Alpha (ULA < 0.002 cph/cm²) Cover Glass Rim & Soft-Error Ceramic Shield Wall","category":"放射線ノイズ対策 S89 — ガラスや陶器に微量に含まれる「天然の放射線」を取り除き、謎の白い点キズを消す","plainAnalogy":"実はふつうのガラスや瀬戸物には、自然界のウランやトリウムがごく微量だけ混ざっていて、たまに「α線（アルファ線）」という目に見えない粒をポンと飛ばします。それがセンサーに当たると写真に白い点やエラーが出ます！そこで不純物を極限まで精製した「超ピュアな低α線ガラス＆セラミック壁」で撮像面をガードしているんです。","summary":"CMOSシリコンダイ直上に密封されるパッケージ材（カバーガラス・封止フリット・セラミック側壁）から微量放射性元素（ウラン・トリウム）を極限精製除去した、ウルトラ・ローアルファ（ULA）低α線光学パッケージ遮蔽構造です。","opticsAndPhysics":["自然界の通常のアルミナセラミックや鉛入りはんだ・光学ガラスからは微量のα粒子（ヘリウム原子核）が放出され、数MeVのエネルギーでシリコン内部に数十万個の偽電子を一瞬で生み出します。","このα線が画素に飛び込むと長時間露光写真に「謎の明るい輝点（ソフトエラー／偽の星）」が写り込んだり、積層DRAMバッファのビット反転を引き起こしたりする原因になります。","α線放出量を 0.002 cph/cm² 未満に抑えた合成石英系ULAカバーガラスと高純度アルミナ遮蔽壁・低αはんだを採用することで、天体撮影や長時間動画でも信頼性抜群のクリアな画質を守ります。"],"formula":{"expression":"Φ_α < 0.002 counts / (h · cm²)  （通常ガラス比 1/100〜1/1000 以下の超低α線放射）","description":"パッケージ材由来の微量α線による偽の白点や積層DRAMビット反転（ソフトエラー）を極限精製材料で根絶"},"nextGenInnovation":"3D積層DRAMの大容量化と画素微細化が進む最新高画素フルサイズ機ほど重要性が増している、半導体信頼性工学の最前線マテリアル。","specs":[{"label":"α線放出率","value":"< 0.002 cph/cm²（ULAグレード準拠）"},{"label":"採用素材","value":"超高純度合成石英ガラス＋精製アルミナ壁"},{"label":"防止トラブル","value":"α線誘起白点ノイズ・積層DRAMソフトエラー"},{"label":"関連規格","value":"JEDEC JESD221 低α線半導体パッケージ基準"}],"diagramType":"sensor_low_alpha_mold"},{"id":"sensor-chamber-labyrinth-felt","order":90,"swatchColor":"#f97316","groupKey":"撮像室最終仕上げ_S90_迷路のような黒いベルベット枠で_漏れた","assembledPos":[0,0,9.4],"explodeOffset":[-76,62,118],"edgeOpacity":0.22,"standaloneOnly":true,"title":"S90. 撮像室周囲・遮光植毛ラビリンス枠＆シャッター衝撃吸収シリコーンアイソレーター環","subtitle":"Imaging-Chamber Velvet-Flocked Labyrinth Light-Trap Frame & Silicone Vibration Isolators","category":"撮像室最終仕上げ S90 — 迷路のような黒いベルベット枠で「漏れた光とホコリ」と「シャッターの振動」を最終ブロック","plainAnalogy":"映画館の入り口がカクッと曲がった暗い通路（迷路）になっていて外の光が一切漏れないのと同じです！センサーの入り口を囲むこの枠も、光を吸い込む真っ黒な起毛（ベルベット植毛）と段差迷路（ラビリンス）で迷光とゴミを遮断し、4隅のぷにぷにシリコーンゴム環でシャッターの振動がセンサーへ伝わるのを和らげます。","summary":"フォーカルプレーンシャッター背面とイメージセンサー最前面のすき間を光学的・機械的に隔てる、段差ラビリンス構造の黒色植毛（フロッキング）遮光枠と、シャッター衝撃波を遮断する4点高減衰シリコーン・アイソレーター環です。","opticsAndPhysics":["シャッターユニットとIBIS可動センサーの間には必ず数ミリの可動クリアランスが必要ですが、その隙間から斜め迷光や金属摩耗粉が回り込むのを「階段状ラビリンス溝＋極細黒色植毛」でトラップします。","植毛繊維の微細な隙間に飛び込んだ光は何度も多重反射するうちに99.5%以上吸収されるため、真黒な宇宙や暗い室内で強烈な逆光が入っても画面端の白浮きを防ぎます。","同時に、枠の四隅へ組み込んだシリコーンエラストマー・アイソレーター環が、シャッター幕走行時の高周波衝撃がフロントマウント経由でセンサー光学枠へ伝わるのを減衰させます。"],"formula":{"expression":"R_flock < 0.4%（多重反射吸光） ／ 振動伝達率 T_vib < 0.25（> 200 Hz シャッター衝撃帯）","description":"真っ黒な植毛迷路による光・ゴミ完全封鎖と、シリコーン防振環によるシャッター衝撃遮断を1つの枠で両立"},"nextGenInnovation":"繊維が絶対に抜け落ちない静電強固着フロッキング加工＋無発ガス（アウトガスフリー）医療級シリコーンにより、10年使ってもセンサーを汚さないクリーン設計。","specs":[{"label":"遮光表面","value":"静電植毛ベルベット＋段差ラビリンス溝"},{"label":"反射率","value":"< 0.4%（可視〜近赤外域ワイド吸光）"},{"label":"防振要素","value":"4点高減衰シリコーン・アイソレーター環"},{"label":"主な役割","value":"シャッター隙間迷光＆摩耗塵侵入＋振動遮断"}],"diagramType":"sensor_chamber_labyrinth_felt"}]'),i={unitId:e,version:a,nameJa:l,nameEn:s,declaredPartCount:90,parts:o};export{t as declaredPartCount,i as default,s as nameEn,l as nameJa,o as parts,e as unitId,a as version};
